  ui_story_5017_50170101_151_dialog_content = "(เสียงกระดิ่ง?)",
  ui_story_5017_50170101_152_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5017_50170101_153_dialog_content = "เป็นไงบ้าง?",
  ui_story_5017_50170101_154_dialog_content = "เคเลสไทต์ผู้วิเศษ นายเจอความทรงจำของฉันรึยัง?",
  ui_story_5017_50170101_155_dialog_content = "ขอโทษครับ... ส่วนลึกสุดของความทรงจำคุณก็คือภาพมหาสมุทรที่กว้างใหญ่...",
  ui_story_5017_50170101_156_dialog_content = "งั้นเหรอ...",
  ui_story_5017_50170101_157_dialog_content = "นายพูดถูกแล้ว ความทรงจำของฉันเริ่มจากตรงนั้น",
  ui_story_5017_50170101_158_dialog_content = "ฉันตื่นมาที่ทะเล แล้วก็จำอะไรไม่ได้เลยนอกจากชื่อตัวเอง",
  ui_story_5017_50170101_159_dialog_content = "อา ตอนนั้นฉันอยู่บนเรือหาปลา",
  ui_story_5017_50170101_160_dialog_content = "คนเรือบอกว่าฉันมาจาก<color=#FFB400>เกาะเมฆา</color>",
  ui_story_5017_50170101_161_dialog_content = "เกาะเมฆา... ภูเขาเมฆางั้นเหรอ?",
  ui_story_5017_50170101_162_dialog_content = "ใช่ ภูเขาเมฆาตั้งอยู่บนเกาะเมฆา",
  ui_story_5017_50170101_163_dialog_content = "ฉันจำเรื่องราวเกี่ยวกับเกาะเมฆาไม่ได้เลย",
  ui_story_5017_50170101_164_dialog_content = "โลกใบนี้เป็นสถานที่แปลกประหลาดสำหรับฉัน เพราะฉันไม่ได้รู้สึกเกี่ยวข้องอะไรกับมันสักนิด",
  ui_story_5017_50170101_165_dialog_content = "สิ่งเดียวที่เชื่อมโยงฉันกับโลกใบนี้ก็คือเจ้านี่",
  ui_story_5017_50170101_166_dialog_content = "นี่มัน...",
  ui_story_5017_50170101_167_dialog_content = "<color=#FFB400>หยก</color>งั้นเหรอ?",
  ui_story_5017_50170101_168_dialog_content = "ใช่",
  ui_story_5017_50170101_169_dialog_content = "พอฟื้นขึ้นมา ฉันก็มีมันติดตัวอยู่แล้ว",
  ui_story_5017_50170101_170_dialog_content = "ฉันไม่รู้ว่าใครให้มา และให้มาเพราะอะไร",
  ui_story_5017_50170101_171_dialog_content = "แต่มันก็มอบความอบอุ่นให้ฉันเสมอ ราวกับว่าหัวใจของฉันผูกพันกับใครบางคนที่ก็ไม่เคยได้พบ",
