  ui_story_5017_50170101_173_dialog_content = "ฉันก็จำอะไรไม่ได้หรอกนะ!",
  ui_story_5017_50170101_174_dialog_content = "นายเห็นอะไรก่อนความทรงจำเรื่องทะเลบ้างมั้ย?",
