  ui_story_5017_50170101_176_dialog_content = "กระดิ่ง?",
  ui_story_5017_50170101_177_dialog_content = "ใช่ครับ กระดิ่ง หรืออาจจะเป็นโมบาย มันดังเป็นจังหวะ",
