  ui_story_5017_50170101_181_dialog_content = "...",
  ui_story_5017_50170101_182_dialog_content = "... พอจะช่วยอะไรได้บ้างมั้ย?",
  ui_story_5017_50170101_183_dialog_content = "ฉันนึกถึงรถไฟขึ้นมาเลย",
  ui_story_5017_50170101_184_dialog_content = "ฉันนึกถึงห้องครัวแฮะ",
  ui_story_5017_50170101_185_dialog_content = "ขอโทษที่เลียนแบบไม่เก่งนะ!",
  ui_story_5017_50170101_186_dialog_content = "คุณเหยาเคยกลับไปที่เกาะเมฆาหรือยังคะ?",
