  ui_story_5017_50170101_190_dialog_content = "คนที่นั่นอาจจะจำฉันได้",
  ui_story_5017_50170101_191_dialog_content = "พวกเขาอาจจะเป็นเพื่อน ครอบครัว หรือไม่ก็คนชั่วที่ฉันเคยเล่นงาน...",
  ui_story_5017_50170101_192_dialog_content = "(เป็นไปได้สูงเลยแหละ!)",
  ui_story_5017_50170101_193_dialog_content = "แต่ฉันก็จะจำพวกเขาไม่ได้...",
  ui_story_5017_50170101_194_dialog_content = "เลยไม่รู้ว่าควรจะทำตัวยังไง",
  ui_story_5017_50170101_195_dialog_content = "เข้าใจล่ะ",
  ui_story_5017_50170101_196_dialog_content = "ฉันเข้าใจความรู้สึกของคุณนะ แต่...",
  ui_story_5017_50170101_197_dialog_content = "พวกเขาอาจช่วยให้คุณจำอะไรขึ้นมาบ้างก็ได้",
  ui_story_5017_50170101_198_dialog_content = "พอฉันลืมอะไรบางอย่าง การได้เห็นของอีกอย่างก็มักจะช่วยฟื้นความจำขึ้นมา",
  ui_story_5017_50170101_199_dialog_content = "ถึงนั่นจะไม่ตรงกับสถานการณ์ของคุณนัก แต่ฉันว่ามันอาจจะได้ผล",
  ui_story_5017_50170101_200_dialog_content = "ว้าว... ไม่นึกเลยนะเนี่ย! งั้นฉันควรกลับไปเหรอ?",
  ui_story_5017_50170101_201_dialog_content = "ควรสุด ๆ เลยครับ!",
  ui_story_5017_50170101_202_dialog_content = "ผมรับปากแล้วว่าจะช่วยคุณตามหาความทรงจำ เพราะฉะนั้นผมจะช่วยทุกทางเท่าที่ทำได้!",
  ui_story_5017_50170101_203_dialog_content = "ไปกันเลย! เกาะเมฆา!",
  ui_story_5017_50170101_204_dialog_content = "หืม?",
  ui_story_5017_50170101_205_dialog_content = "ตอนนี้เลยเหรอ?",
