  ui_story_5017_50170201_74_dialog_content = "ตั้งอยู่ทางตะวันออกของทวีปแอสตรา เกาะเมฆาเป็นส่วนหนึ่งของหมู่เกาะที่ตั้งอยู่ท่ามกลางทะเลวายุ",
