  ui_story_5017_50170201_81_dialog_content = "แล้วทำไมเธอถึงมี<color=#FFB400>หนังสือนำเที่ยวเกาะเมฆา</color>ล่ะ?",
  ui_story_5017_50170201_82_dialog_content = "ฮิฮิ ฉันพกคู่มือนี่ติดตัวตลอดเวลาอยู่แล้ว!",
