  ui_story_5017_50170201_84_dialog_content = "เป็นการคิดถึงบ้านที่แหวกแนวสุด ๆ!",
  ui_story_5017_50170201_85_dialog_content = "งั้นจะให้ข้อมูลต่อล่ะนะ",
  ui_story_5017_50170201_86_dialog_content = "คุณลักษณะทางภูมิประเทศแนวราบของเกาะเมฆาประกอบด้วย...",
  ui_story_5017_50170201_87_dialog_content = "เดี๋ยวก่อน!",
  ui_story_5017_50170201_88_dialog_content = "เรื่องภูมิศาสตร์เอาไว้ก่อนเถอะ! คุณช่วยอ่านอะไรที่มันเอาไปใช้งานจริงได้มั้ย?",
  ui_story_5017_50170201_89_dialog_content = "ขอดูสารบัญก่อนนะ...",
  ui_story_5017_50170201_90_dialog_content = "ทำไมข้อมูลเยอะขนาดนี้ล่ะเนี่ย! เรื่องซุบซิบในเกาะเมฆา, เสื้อผ้าฤดูต่าง ๆ, นิทานพื้นบ้าน, อาหารที่แนะนำ...",
  ui_story_5017_50170201_91_dialog_content = "นี่มันคู่มือจริง ๆ น่ะเหรอ?",
  ui_story_5017_50170201_92_dialog_content = "แน่นอน! อ่านชื่อหนังสือสิ!",
  ui_story_5017_50170201_93_dialog_content = "โอเค เริ่มจากคำแนะนำในการท่องเที่ยว",
  ui_story_5017_50170201_94_dialog_content = "อื้ม",
  ui_story_5017_50170201_95_dialog_content = "เกาะเมฆามีทิวทัศน์งดงามพร้อมสิ่งต่าง ๆ มากมายให้เที่ยวชมตลอดทั้งปี ผู้มาเยือนสามารถแช่น้ำพุร้อนและชมดอกซากุระ",
  ui_story_5017_50170201_96_dialog_content = "ที่สำคัญกว่านั้น สถานที่แห่งนี้ปลอดภัยมาก ๆ <color=#FFB400>ไม่มีอิคลิพไซท์แม้แต่ตัวเดียว</color>",
  ui_story_5017_50170201_97_dialog_content = "ถ้ามีอิคลิพไซท์ ความงามอันเงียบสงบของที่นี่คงจะถูกทำลาย",
  ui_story_5017_50170201_98_dialog_content = "จริงด้วย!",
  ui_story_5017_50170201_99_dialog_content = "ฉันไม่ได้ฆ่าพวกอิคลิพไซท์มาหลายวันแล้ว ชักจะเหงาแล้วสิ",
  ui_story_5017_50170201_100_dialog_content = "นี่คุณใช้ชีวิตแบบไหนกันเนี่ย?",
  ui_story_5017_50170201_101_dialog_content = "ฉันจะอ่านข้อมูลเพิ่มอีกก็แล้วกัน",
  ui_story_5017_50170201_102_dialog_content = "ประชากรของเกาะเมฆาส่วนใหญ่อาศัยอยู่ตามแนวชายฝั่ง และได้สร้างเมืองท่าแห่งหนึ่งจนเติบโตอย่างรุ่งเรือง เมืองนั้นมีชื่อว่า...",
  ui_story_5017_50170201_103_dialog_content = "<color=#FFB400>โคฟุโจ</color>",
  ui_story_5017_50170201_104_dialog_content = "หา! เมืองงั้นเหรอ!",
  ui_story_5017_50170201_105_dialog_content = "งั้นถ้าไปที่นั่นก็คงจะมีโอกาสมากกว่าเนอะ?",
  ui_story_5017_50170201_106_dialog_content = "ถ้าเหยาเป็นคนจากเกาะนี้ ก็น่าจะมีคนที่นั่นจำเธอได้",
  ui_story_5017_50170201_107_dialog_content = "ฉันก็ว่างั้น!",
  ui_story_5017_50170201_108_dialog_content = "งั้นก็ไปโคฟุโจกันเลย!",
  ui_story_5017_50170201_109_dialog_content = "ไปโคฟุโจกันเถอะ!",
  ui_story_5017_50170201_110_dialog_content = "...",
  ui_story_5017_50170201_X110_dialog_content = "...",
  ui_story_5017_50170201_111_dialog_content = "แล้ว... โคฟุโจมันอยู่ไหนกันล่ะ?",
  ui_story_5017_50170201_112_dialog_content = "เราเดินมาตั้งนานแต่วิวก็ยังไม่ค่อยเปลี่ยนเท่าไหร่",
  ui_story_5017_50170201_113_dialog_content = "เหนื่อยชะมัด!",
  ui_story_5017_50170201_114_dialog_content = "ฉันอยากจะพักเต็มแก่แล้ว... โคฟุโจต้องมีร้านอาหารอร่อย ๆ แน่ ๆ เลย...",
  ui_story_5017_50170201_115_dialog_content = "แต่ปัญหาก็คือ เราไม่รู้เลยว่าจะต้องเดินทางอีกนานเท่าไหร่กว่าจะถึง...",
  ui_story_5017_50170201_116_dialog_content = "หืมม? ฉันว่าฉันได้ยินเสียงคนล่ะ!",
  ui_story_5017_50170201_117_dialog_content = "ว้าว! ดีเลย!",
  ui_story_5017_50170201_118_dialog_content = "สวัสดี! ได้ยินพวกเรามั้ย?",
  ui_story_5017_50170201_119_dialog_content = "ยอดเลย เดี๋ยวฉันไปถามทางดีกว่า!",
  ui_story_5017_50170201_120_dialog_content = "<color=#e8d9bb>ลา ลา ล้า...</color>",
  ui_story_5017_50170201_121_dialog_content = "ขอโทษนะคะ...",
  ui_story_5017_50170201_122_dialog_content = "...",
  ui_story_5017_50170201_123_dialog_content = "พวกเราเป็นนักท่องเที่ยวที่เพิ่งมาเกาะนี้เป็นครั้งแรก คุณช่วยบอกทางไปโคฟุโจหน่อยได้มั้ยคะ?",
  ui_story_5017_50170201_124_dialog_content = "...",
  ui_story_5017_50170201_125_dialog_content = "ไม่ได้ยินเหรอคะ? คือฉัน...",
  ui_story_5017_50170201_126_dialog_content = "เอ่อ...",
  ui_story_5017_50170201_127_dialog_content = "อ๊าาา!",
  ui_story_5017_50170201_128_dialog_content = "หืม?",
  ui_story_5017_50170201_129_dialog_content = "ไวซ์! ระวัง!",
  ui_story_5017_50170202_1_dialog_content = "อาา...",
  ui_story_5017_50170202_2_dialog_content = "สัตว์ประหลาดน่ารังเกียจ...",
  ui_story_5017_50170202_3_dialog_content = "ไหนว่าเกาะนี้ไม่มีอิคลิพไซท์ไงล่ะ",
  ui_story_5017_50170202_4_dialog_content = "ฉันว่านั่นไม่ใช่อิคลิพไซท์นะ...",
  ui_story_5017_50170202_5_dialog_content = "จริงด้วย...",
  ui_story_5017_50170202_6_dialog_content = "ดูสิ พวกมันสลายหายไปเลย",
  ui_story_5017_50170202_7_dialog_content = "ไม่ใช่อิคลิพไซท์... แล้วมันตัวอะไรกันล่ะ?",
  ui_story_5017_50170202_8_dialog_content = "ดูจากหน้าตาแล้วก็ท่าทาง... สัตว์ประหลาดพวกนี้...",
  ui_story_5017_50170202_9_dialog_content = "ฉันมีสมมุติฐานที่ออกจะน่ากลัวสักหน่อย...",
  ui_story_5017_50170202_10_dialog_content = "ฉันก็คิดเหมือนนาย...",
  ui_story_5017_50170202_11_dialog_content = "หือ? มันคือตัวอะไรเหรอ?",
  ui_story_5017_50170202_12_dialog_content = "\"ผี\" ไงล่ะ...",
  ui_story_5017_50170202_13_dialog_content = "นี่! อย่าพูดเรื่องหลอน ๆ ด้วยหน้าตาน่ากลัวแบบนั้นสิ!",
  ui_story_5017_50170202_14_dialog_content = "ฉัน... ฉันแค่ถามทางพวกเขาเท่านั้นเอง...",
  ui_story_5017_50170202_15_dialog_content = "เป็นไปไม่ได้! โลกนี้มีผีที่ไหนกันล่ะ!",
  ui_story_5017_50170202_16_dialog_content = "ถึงเป็นผีจริง ๆ ฉันก็จะสั่งสอนพวกมันเอง!",
  ui_story_5017_50170202_17_dialog_content = "คุณไม่กลัวเหรอ?",
  ui_story_5017_50170202_18_dialog_content = "ไม่อยู่แล้ว!",
  ui_story_5017_50170202_19_dialog_content = "ฉันไม่กลัวสิ่งที่อ่อนแอกว่าฉันหรอกนะ!",
  ui_story_5017_50170202_20_dialog_content = "เราต้องระวังตัวให้ดี ที่นี่ไม่ปลอดภัยอย่างที่โฆษณาไว้เลย",
  ui_story_5017_50170202_21_dialog_content = "<color=#e8d9bb>กริ๊ง...</color>",
  ui_story_5017_50170202_22_dialog_content = "เสียงอะไรน่ะ?!",
  ui_story_5017_50170202_23_dialog_content = "ใจเย็น ๆ สิ! ฉันตกใจนะ!",
  ui_story_5017_50170202_24_dialog_content = "<color=#e8d9bb>กริ๊ง...</color>",
  ui_story_5017_50170202_25_dialog_content = "เสียงมาจากในป่า",
  ui_story_5017_50170202_26_dialog_content = "เดี๋ยวนะ นี่มัน...",
  ui_story_5017_50170202_27_dialog_content = "<color=#e8d9bb>กริ๊ง...</color>",
  ui_story_5017_50170202_28_dialog_content = "ฉันได้ยินเสียงนี้ในความทรงจำของเหยา!",
  ui_story_5017_50170202_29_dialog_content = "เหยา! คุณ...",
  ui_story_5017_50170202_30_dialog_content = "ฉันเคยได้ยินเสียงนี้มาก่อน!",
  ui_story_5017_50170202_31_dialog_content = "<color=#e8d9bb>กริ๊ง... กริ๊ง...</color>",
  ui_story_5017_50170202_32_dialog_content = "ใช่แล้วล่ะ! ฉันมั่นใจ!",
  ui_story_5017_50170202_33_dialog_content = "เหยา! รอเดี๋ยว!",
  ui_story_5017_50170202_34_dialog_content = "อย่าไปคนเดียวแบบนั้นสิ!",
  ui_story_5017_50170202_35_dialog_content = "เธอวิ่งเข้าป่าไปแล้ว",
  ui_story_5017_50170202_36_dialog_content = "เร็วเข้า เราต้องตามเธอให้ทัน!",
  ui_story_5017_50170202_37_dialog_content = "<color=#e8d9bb>กริ๊ง... กริ๊ง...</color>",
  ui_story_5017_50170202_38_dialog_content = "เหยาเร็วมากเลย ฉันไม่เห็นเธอแล้ว",
  ui_story_5017_50170202_39_dialog_content = "ตามเสียงกระดิ่งไป!",
  ui_story_5017_50170202_40_dialog_content = "<color=#e8d9bb>ซวบ... ซวบ...</color>",
  ui_story_5017_50170202_41_dialog_content = "ได้ยินเสียงแปลก ๆ รึเปล่า?",
  ui_story_5017_50170202_42_dialog_content = "ฉันไม่รู้",
  ui_story_5017_50170202_43_dialog_content = "ตอบอะไรของนายน่ะ?",
  ui_story_5017_50170202_44_dialog_content = "เอ่อ...",
  ui_story_5017_50170202_45_dialog_content = "ฉันยังไม่ได้พูดอะไรเลยนะ...",
  ui_story_5017_50170202_46_dialog_content = "หือ?",
  ui_story_5017_50170202_47_dialog_content = "อู..",
  ui_story_5017_50170202_48_dialog_content = "ใจเย็นก่อน ไวซ์! เธอเกือบจะยิงฉันแล้วนะ!",
  ui_story_5017_50170202_49_dialog_content = "ไปกันเถอะ! เราจะคลาดกับคุณเหยาไม่ได้นะ!",
  ui_story_5017_50170202_50_dialog_content = "เร็วชะมัด!",
  ui_story_5017_50170202_51_dialog_content = "ฉันตามไม่ทันแล้ว!",
  ui_story_5017_50170202_52_dialog_content = "ให้ตายสิ",
  ui_story_5017_50170202_53_dialog_content = "อย่าขยับตัวนะ!",
  ui_story_5017_50170202_54_dialog_content = "หือ?",
  ui_story_5017_50170202_55_dialog_content = "เฮ้... หวา!",
  ui_story_5017_50170202_56_dialog_content = "เฮ้ เฮ้ เฮ้!",
  ui_story_5017_50170202_57_dialog_content = "ทำไมอยู่ ๆ ก็แบกฉันขึ้นมาล่ะ?",
  ui_story_5017_50170202_58_dialog_content = "ก็ไม่มีทางอื่นแล้วนี่นา!",
  ui_story_5017_50170202_59_dialog_content = "เร็วเข้าเถอะ!",
  ui_story_5017_50170202_60_dialog_content = "เธอ... ช่างเถอะ",
  ui_story_5017_50170202_61_dialog_content = "ขอแนะนำอะไรหน่อยก็แล้วกัน",
  ui_story_5017_50170202_62_dialog_content = "อย่าหันกลับไปมองข้างหลังนะ",
  ui_story_5017_50170202_63_dialog_content = "มันใช่เวลามาแหย่ฉันเล่นมั้ยเนี่ย!",
  ui_story_5017_50170202_64_dialog_content = "นี่ไม่ได้ล้อเล่นนะ ฉันพูดจริง ๆ...",
  ui_story_5017_50170202_65_dialog_content = "<color=#e8d9bb>กริ๊ง...</color>",
  ui_story_5017_50170202_66_dialog_content = "<color=#e8d9bb>กริ๊ง...</color>",
  ui_story_5017_50170202_67_dialog_content = "เกือบแล้ว!",
  ui_story_5017_50170202_68_dialog_content = "ฉันเห็นคุณเหยาแล้ว เธออยู่ข้างหน้านี่เอง!",
  ui_story_5017_50170202_69_dialog_content = "<color=#e8d9bb>กริ๊ง...</color>",
  ui_story_5017_50170202_70_dialog_content = "ให้ตายสิ... พวกผีล้อมเธออยู่!",
  ui_story_5017_50170202_71_dialog_content = "ทำไมเธอไม่สู้กับพวกมันล่ะ?",
  ui_story_5017_50170202_72_dialog_content = "เธอตกอยู่ในภวังค์!",
  ui_story_5017_50170202_73_dialog_content = "<color=#e8d9bb>กริ๊ง...</color>",
  ui_story_5017_50170202_74_dialog_content = "คุณเหยา!",
  ui_story_5017_50170202_75_dialog_content = "คุณเหยา!!!",
  ui_story_5017_50170202_76_dialog_content = "<color=#e8d9bb>กริ๊ง...</color>",
  ui_story_5017_50170202_77_dialog_content = "ข้าขอกล่าวบทสวดแห่งหยินหยาง เพื่อพาเจ้าข้ามฟากสู่ปรภพ",
  ui_story_5017_50170202_78_dialog_content = "ใต้แม่น้ำซันสึ เหล่าวิญญาณทวีความเคียดแค้นขมขื่น",
  ui_story_5017_50170202_79_dialog_content = "ภาษาแห่งดอกลำโพง สอดประสานเป็นท่วงทำนองแสนไพเราะ",
  ui_story_5017_50170202_80_dialog_content = "(พวกเราสงบลงในทันที)",
  ui_story_5017_50170202_81_dialog_content = "(หญิงสาวยืนด้วยปลายเท้าท่ามกลางป่าไผ่ ร่ายรำตามจังหวะกระดิ่งในมือของเธอ)",
  ui_story_5017_50170202_82_dialog_content = "(ทุกย่างก้าวของเธอเงียบงัน ฉันได้ยินเพียงเสียงกระดิ่งเท่านั้น)",
  ui_story_5017_50170202_83_dialog_content = "(ฉันไม่เคยเห็นอะไรแบบนี้มาก่อน)",
  ui_story_5017_50170202_84_dialog_content = "(ทุกสายตาต่างจับจ้องไปที่เธอ)",
  ui_story_5017_50170202_85_dialog_content = "โปรดรับฟังอย่างสงบ และขอดวงวิญญาณจงได้รับการเติมเต็ม",
  ui_story_5017_50170202_86_dialog_content = "ไม่ว่าจะเป็นผู้ล่วงลับ หรือผู้ที่ยังมีลมหายใจ",
  ui_story_5017_50170202_87_dialog_content = "กรร!... โอ...",
  ui_story_5017_50170202_88_dialog_content = "ฉันเคยเห็นการร่ายรำนี้มาก่อน...",
  ui_story_5017_50170202_89_dialog_content = "กระดิ่ง ท่าทาง และเสียงกรีดร้องของภูตผี...",
  ui_story_5017_50170202_90_dialog_content = "(นั่นทำให้ฉันจำได้...)",
  ui_story_5017_50170202_91_dialog_content = "(นี่เป็นเสียงกระดิ่งแบบเดียวกับที่ได้ยินในความทรงจำของเหยา!)",
  ui_story_5017_50170202_92_dialog_content = "เธอร่ายรำได้สวยมาก ๆ เลย...",
  ui_story_5017_50170202_93_dialog_content = "ถ้าฉันเป็นผี ฉันคงตายอย่างเป็นสุขหลังจากได้ดู",
  ui_story_5017_50170202_94_dialog_content = "ฉันก็คิดยังงั้นเหมือนกัน",
  ui_story_5017_50170202_95_dialog_content = "หึหึ",
  ui_story_5017_50170202_96_dialog_content = "เพลิดเพลินกับการร่ายรำของฉันได้ แต่อย่าเพิ่งรีบจากโลกนี้ไปล่ะ",
  ui_story_5017_50170202_97_dialog_content = "ต้องตามเก็บกวาดทีหลังมันวุ่นวายน่ะ",
  ui_story_5017_50170202_98_dialog_content = "เธอพูดกับฉันด้วย!",
  ui_story_5017_50170202_99_dialog_content = "ฉันตอบเธอได้มั้ย?",
  ui_story_5017_50170202_100_dialog_content = "เอาสิ! กล้า ๆ หน่อย! แนะนำตัวไปก่อนก็แล้วกัน!",
  ui_story_5017_50170202_101_dialog_content = "เอ่อ... ฉันชื่อ...",
  ui_story_5017_50170202_102_dialog_content = "เธอรู้จักฉันรึเปล่า?",
  ui_story_5017_50170202_103_dialog_content = "หืม?",
  ui_story_5017_50170202_104_dialog_content = "แล้วคุณชื่ออะไรล่ะ?",
  ui_story_5017_50170202_105_dialog_content = "ฉันชื่อเหยา!",
  ui_story_5017_50170202_106_dialog_content = "เหยาสินะ~ เอาล่ะ ทีนี้เราก็รู้จักกันแล้ว",
  ui_story_5017_50170202_107_dialog_content = "หา! ไม่ใช่แบบนั้นสักหน่อย...",
  ui_story_5017_50170202_108_dialog_content = "ฉันตามเสียงกระดิ่งมาที่นี่ แล้วก็ดูเธอเต้นรำ...",
  ui_story_5017_50170202_109_dialog_content = "แล้วฉันก็รู้สึกว่าเราสองคน...",
  ui_story_5017_50170202_110_dialog_content = "เอาล่ะ เอาล่ะ",
  ui_story_5017_50170202_111_dialog_content = "ฉันชื่อ<color=#FFB400>รินเนะ</color> เป็นมิโกะแห่งเกาะนี้",
  ui_story_5017_50170202_112_dialog_content = "ถ้าคุณชอบ<color=#FFB400>ระบำคางุระ</color> เดี๋ยวคุณก็จะได้เห็นอีกแน่",
  ui_story_5017_50170202_113_dialog_content = "วันนี้ \"เจ้าพวกนั้น\" ค่อนข้างจะอยู่ไม่สุขกว่าปกติ",
  ui_story_5017_50170202_114_dialog_content = "เจ้าพวกนั้น... คุณหมายถึง...",
  ui_story_5017_50170202_115_dialog_content = "ใช่ ฉันกำลังพูดถึง...",
  ui_story_5017_50170202_116_dialog_content = "<color=#FFB400>ผี</color>",
  ui_story_5017_50170301_1_dialog_content = "<color=#FFB400>ผี</color>?",
  ui_story_5017_50170301_2_dialog_content = "ว่าแต่เราเข้าใจคำว่า \"ผี\" ตรงกันรึเปล่านะ?",
  ui_story_5017_50170301_3_dialog_content = "ผีคือผู้ตายที่ไม่สามารถไปเกิดใหม่ ซึ่งปรากฏกายในโลกนี้เพราะยังมีห่วงบางอย่าง",
  ui_story_5017_50170301_4_dialog_content = "มลทินอันสกปรกก่อตัวเป็นรูปร่างอย่างที่คุณเห็น",
  ui_story_5017_50170301_5_dialog_content = "เศษเสี้ยววิญญาณออกเร่ร่อนด้วยสติสัมปชัญญะที่หลงเหลืออยู่เพียงน้อยนิด",
  ui_story_5017_50170301_6_dialog_content = "ผู้ล่วงลับเหล่านี้หวนคืนสู่โลกด้วยสภาพที่เน่าเปื่อย ผุพัง",
  ui_story_5017_50170301_7_dialog_content = "นี่ล่ะคือ \"ภูตผี\"",
  ui_story_5017_50170301_8_dialog_content = "แสดงว่าพวกเขา...",
  ui_story_5017_50170301_9_dialog_content = "ใช่ พวกเขา<color=#FFB400>ตายไปแล้ว</color>",
  ui_story_5017_50170301_10_dialog_content = "หวาา!",
  ui_story_5017_50170301_11_dialog_content = "มันมีอยู่จริงเหรอเนี่ย... ผีดิบคืนชีพ...",
  ui_story_5017_50170301_12_dialog_content = "คุณคงเพิ่งเคยมาเกาะเมฆาสินะ",
  ui_story_5017_50170301_13_dialog_content = "ฉันเข้าใจดีว่าโลกภายนอกไม่เชื่อแนวคิดเรื่องวิญญาณ ดังนั้นเมื่อไม่มีวิญญาณ ผีก็ไม่มีจริง",
  ui_story_5017_50170301_14_dialog_content = "แต่นั่นก็ไม่เป็นปัญหาหรอกนะ",
  ui_story_5017_50170301_15_dialog_content = "อีกเดี๋ยวคุณก็จะเริ่มเชื่อเอง...",
  ui_story_5017_50170301_16_dialog_content = "*สั่นหงึก*...",
  ui_story_5017_50170301_17_dialog_content = "ผีพวกนี้เป็นเรื่องธรรมดาในเกาะเมฆาเหรอครับ?",
  ui_story_5017_50170301_18_dialog_content = "เอ่อ... จะบอกว่าธรรมดาก็ไม่ได้หรอก",
  ui_story_5017_50170301_19_dialog_content = "ปกติพวกมันไม่ได้มีจำนวนมากนัก",
  ui_story_5017_50170301_20_dialog_content = "แต่เมื่อสองวันที่ผ่านมา กระแสของหยินมีปริมาณสูงท่วมท้นจนบดบังหยาง",
  ui_story_5017_50170301_21_dialog_content = "ทำให้สิ่งโสมมพวกนั้นออกอาละวาดไปทั่วเกาะ",
  ui_story_5017_50170301_22_dialog_content = "<color=#FFB400>หยินกับหยางงั้นเหรอ?</color>",
  ui_story_5017_50170301_23_dialog_content = "หยินและหยางคือพลังสองขั้วที่เป็นองค์ประกอบของทุกสิ่งบนโลกมนุษย์และสรวงสวรรค์",
  ui_story_5017_50170301_24_dialog_content = "พวกมันทั้งส่งเสริมและต่อต้านซึ่งกันและกัน",
  ui_story_5017_50170301_25_dialog_content = "เอ่อ...",
  ui_story_5017_50170301_26_dialog_content = "คุณไม่จำเป็นต้องเข้าใจเรื่องนี้หรอก แค่รู้ว่าพื้นที่นอกเมืองไม่ปลอดภัยก็พอแล้ว",
  ui_story_5017_50170301_27_dialog_content = "กรุณาตามฉันมา ฉันจะพาพวกคุณไปที่โคฟุโจเอง",
  ui_story_5017_50170301_28_dialog_content = "โคฟุโจ! เราจะไปที่นั่นอยู่พอดีเลย!",
  ui_story_5017_50170301_29_dialog_content = "ฮะฮะ คุณมาร่วม<color=#FFB400>เทศกาลคาสึกะ</color>อย่างนั้นรึ?",
  ui_story_5017_50170301_30_dialog_content = "เทศกาลคาสึกะ?",
  ui_story_5017_50170301_31_dialog_content = "ไม่ใช่สินะ...",
  ui_story_5017_50170301_32_dialog_content = "ถ้าอย่างนั้นพวกคุณโชคดีแล้วล่ะ นี่เป็นช่วงเวลาที่ดีที่สุดในการมาเยือนโคฟุโจ",
  ui_story_5017_50170301_33_dialog_content = "ว้าว! เทศกาลงั้นเหรอ? เกี่ยวกับอะไรเหรอคะ?",
  ui_story_5017_50170301_34_dialog_content = "เรื่องนั้นฉันคิดว่าให้คุณหาคำตอบเองจะดีกว่า",
  ui_story_5017_50170301_35_dialog_content = "ฉันก็แค่หวังว่าในสถานการณ์แบบนี้ ทุกอย่างจะยังดำเนินต่อไปได้อย่างราบรื่น...",
  ui_story_5017_50170301_36_dialog_content = "คุณรินเนะ คุณไม่ได้รู้จักฉันใช่มั้ย?",
  ui_story_5017_50170301_37_dialog_content = "ขอโทษด้วย ฉันคิดว่าไม่เคยเจอคุณมาก่อนนะ",
  ui_story_5017_50170301_38_dialog_content = "แล้วทำไมเรียกฉันอย่างสนิทสนมแบบนั้นล่ะ?",
  ui_story_5017_50170301_39_dialog_content = "เพราะเธอน่ารักมาก ๆ ยังไงล่ะ",
  ui_story_5017_50170301_40_dialog_content = "ไม่ชอบเหรอ?",
  ui_story_5017_50170301_41_dialog_content = "เอ่อ... ไม่ใช่อย่างนั้นหรอก...",
  ui_story_5017_50170301_42_dialog_content = "ฉันรู้สึกคุ้นเคยกับกระดิ่งและการร่ายรำนั่นอย่างบอกไม่ถูก",
  ui_story_5017_50170301_43_dialog_content = "ฉันมั่นใจว่าเราต้องเคยเจอกันมาก่อน! ตอนนั้นพวกเราอาจจะยังเด็กก็ได้!",
  ui_story_5017_50170301_44_dialog_content = "ถ้าอย่างนั้นฉันก็ต้องจำเด็กสาวน่ารักอย่างคุณได้สิ",
  ui_story_5017_50170301_45_dialog_content = "งั้นเหรอ...",
  ui_story_5017_50170301_46_dialog_content = "คุณเคยเห็นสิ่งนี้รึเปล่า?",
  ui_story_5017_50170301_47_dialog_content = "หืม?",
  ui_story_5017_50170301_48_dialog_content = "...",
  ui_story_5017_50170301_49_dialog_content = "ขอโทษด้วย ฉันไม่เคยเห็นมันมาก่อน",
  ui_story_5017_50170301_50_dialog_content = "แต่หยกชิ้นนี้เปี่ยมด้วยพลังหยางอันแสนบริสุทธิ์",
  ui_story_5017_50170301_51_dialog_content = "แสดงว่าจะต้องเป็นของมีค่าอย่างแน่นอน ดูแลมันให้ดีด้วยล่ะ",
  ui_story_5017_50170301_52_dialog_content = "ว้าว! คุณมีความรู้เยอะจัง!",
  ui_story_5017_50170301_53_dialog_content = "เล่าเรื่องของมันให้ฟังมากกว่านี้ได้มั้ย!",
  ui_story_5017_50170301_54_dialog_content = "ฉันบอกได้ว่ามันมีต้นกำเนิดอยู่ที่โคฟุโจ วัสดุและฝีมือช่างค่อนข้างเก่าแก่...",
  ui_story_5017_50170301_55_dialog_content = "ดังนั้นจะต้องไม่ใช่เครื่องประดับธรรมดาอย่างแน่นอน",
  ui_story_5017_50170301_56_dialog_content = "ไม่ใช่เครื่องประดับเหรอ?",
  ui_story_5017_50170301_57_dialog_content = "ฉันว่ามันไม่น่าเอาไปใช้อะไรได้หรอก",
  ui_story_5017_50170301_58_dialog_content = "หักตรงนี้ออกเอาไปทำช้อนดีมั้ยนะ?",
  ui_story_5017_50170301_59_dialog_content = "ชู่—",
  ui_story_5017_50170301_60_dialog_content = "หืม?",
  ui_story_5017_50170301_61_dialog_content = "ฉันได้ยินเสียงพวกมัน",
  ui_story_5017_50170301_62_dialog_content = "พวกภูตผี",
  ui_story_5017_50170301_63_dialog_content = "ผีงั้นเหรอ! ไหนล่ะ?",
  ui_story_5017_50170301_64_dialog_content = "อ๊าาาาา!",
  ui_story_5017_50170301_65_dialog_content = "มีคนอยู่ตรงนั้น!",
  ui_story_5017_50170301_66_dialog_content = "หืม? ไปทางนั้นแล้วเหรอ?",
  ui_story_5017_50170301_67_dialog_content = "เร็วเข้า! รีบตามไปกันเถอะ!",
  ui_story_5017_50170302_1_dialog_content = "สวรรค์ทรงโปรด!",
  ui_story_5017_50170302_2_dialog_content = "ในป่าก็มีพวกมันเหรอเนี่ย... เราต้องรีบวิ่งลงเขา!",
  ui_story_5017_50170302_3_dialog_content = "ทำไมวันนี้ถึงมีผีเยอะจังนะ?",
  ui_story_5017_50170302_4_dialog_content = "เหมือนปีนั้นเลย...",
  ui_story_5017_50170302_5_dialog_content = "ไอ้พวกผีร้าย...",
  ui_story_5017_50170302_6_dialog_content = "ไปให้พ้นนะ!",
  ui_story_5017_50170302_7_dialog_content = "โอ...",
  ui_story_5017_50170302_8_dialog_content = "เมื่อบทเพลงแห่งสวรรค์เริ่มบรรเลง วิญญาณชั่วทั้งหลายจักแหลกสลายเป็นธุลี",
  ui_story_5017_50170302_9_dialog_content = "เยี่ยมสุด ๆ ไปเลย!",
  ui_story_5017_50170302_10_dialog_content = "เรายังต้องเข้าไปช่วยอีกมั้ยเนี่ย?",
  ui_story_5017_50170302_11_dialog_content = "แค่ปรบมืออย่างเดียวก็คงพอแหละ!",
  ui_story_5017_50170302_12_dialog_content = "ฉันเป็นมิโกะ การขับไล่วิญญาณร้ายเป็นหน้าที่ของฉันอยู่แล้ว",
  ui_story_5017_50170302_13_dialog_content = "ฉันจะนำทางวิญญาณไร้สติเหล่านี้สู่ภพหน้าเอง",
  ui_story_5017_50170302_14_dialog_content = "พวกคุณช่วยปลอบขวัญชาวบ้านที่กำลังตื่นตระหนกได้ไหม?",
  ui_story_5017_50170302_15_dialog_content = "เหยา และสหายทั้งสองคน...",
  ui_story_5017_50170302_16_dialog_content = "ฉันยังไม่รู้ชื่อพวกคุณเลย",
  ui_story_5017_50170302_17_dialog_content = "จริงด้วย!",
  ui_story_5017_50170302_18_dialog_content = "ฉันชื่อไวซ์ ส่วนเจ้าหนุ่มถั่วงอกคนนี้ชื่อ PlayerName!",
  ui_story_5017_50170302_19_dialog_content = "ถั่วงอกเรอะ?",
  ui_story_5017_50170302_20_dialog_content = "หึหึ ฉันจะพยายามจำให้ได้ก็แล้วกันนะ",
  ui_story_5017_50170302_21_dialog_content = "ไว้ใจได้เลย!",
  ui_story_5017_50170302_22_dialog_content = "ฉันคุ้มกันกองคาราวานมาแล้วมากมาย เรื่องดูแลชาวบ้านไม่มีปัญหาอยู่แล้ว!",
  ui_story_5017_50170302_23_dialog_content = "ขอบคุณนะทุกคน",
  ui_story_5017_50170302_24_dialog_content = "ขอบคุณ! ขอบคุณมาก ๆ เลย!",
  ui_story_5017_50170302_25_dialog_content = "เราเกือบจะเป็นอาหารพวกผีซะแล้ว...",
  ui_story_5017_50170302_26_dialog_content = "คุณช่วยชีวิตเราไว้!",
  ui_story_5017_50170302_27_dialog_content = "แหะแหะ ไม่ต้องขอบคุณกันหรอกค่ะ...",
  ui_story_5017_50170302_28_dialog_content = "คุณควรขอบคุณมิโกะคนนั้นมากกว่า",
  ui_story_5017_50170302_29_dialog_content = "มิโกะ...",
  ui_story_5017_50170302_30_dialog_content = "พวกคุณเป็นคนจากโคฟุโจเหรอ?",
  ui_story_5017_50170302_31_dialog_content = "ใช่แล้ว พวกเรากำลังเดินทางกลับบ้าน",
  ui_story_5017_50170302_32_dialog_content = "คุณรู้จักฉันรึเปล่า?",
  ui_story_5017_50170302_33_dialog_content = "เอ่อ...",
  ui_story_5017_50170302_34_dialog_content = "ตั้งใจมองฉันให้ดี ๆ สิ!",
  ui_story_5017_50170302_35_dialog_content = "เราควรรู้จักคุณด้วยเหรอ?",
  ui_story_5017_50170302_36_dialog_content = "เรื่องนั้นไว้ทีหลังเถอะ",
  ui_story_5017_50170302_37_dialog_content = "พาพวกเขาไปที่ปลอดภัยก่อนดีกว่า",
  ui_story_5017_50170302_38_dialog_content = "จริงด้วย! เธอพูดถูก!",
  ui_story_5017_50170302_39_dialog_content = "ไม่รู้ว่ารินเนะจะเป็นยังไงบ้าง...",
  ui_story_5017_50170302_40_dialog_content = "(พลังหยินเพิ่มขึ้นเรื่อย ๆ)",
  ui_story_5017_50170302_41_dialog_content = "(เรื่องนี้เกี่ยวกับเทศกาลคาสึกะหรือเปล่านะ?)",
  ui_story_5017_50170302_42_dialog_content = "(ฉันก็ไม่แน่ใจว่าข้างนอกนั่นมีพวกผีอยู่เท่าไหร่...)",
  ui_story_5017_50170302_43_dialog_content = "(แต่ไม่ว่าอย่างไรก็ตาม เราจะให้เรื่องนี้ขัดขวางเทศกาลคาสึกะไม่ได้...)",
  ui_story_5017_50170302_44_dialog_content = "ฟาดฟัน",
  ui_story_5017_50170302_45_dialog_content = "ชิ!",
  ui_story_5017_50170302_46_dialog_content = "นี่มัน...",
  ui_story_5017_50170302_47_dialog_content = "อัก... อึก...",
  ui_story_5017_50170302_48_dialog_content = "คุไน...",
  ui_story_5017_50170302_49_dialog_content = "ลอบกัดกันแบบนี้...",
  ui_story_5017_50170302_50_dialog_content = "เธออีกแล้วสินะ",
  ui_story_5017_50170302_51_dialog_content = "โอ... อาา...",
  ui_story_5017_50170302_52_dialog_content = "*แค่ก แค่ก*",
  ui_story_5017_50170302_53_dialog_content = "วันนี้ไม่อยากปรากฏตัวงั้นรึ?",
  ui_story_5017_50170302_54_dialog_content = "<color=#FFB400>คุณนินจา</color>",
  ui_story_5017_50170302_55_dialog_content = "เดี๋ยวก่อนตายเธอก็จะได้เห็นหน้าฉันเอง",
  ui_story_5017_50170302_56_dialog_content = "งั้นก็ช่วยทำหน้าตาน่ารักให้ดูหน่อยนะ",
  ui_story_5017_50170302_57_dialog_content = "อย่าให้ความสวยของเธอต้องเสียเปล่าล่ะ",
  ui_story_5017_50170302_58_dialog_content = "ขัดขืนไปก็ไร้ประโยชน์",
  ui_story_5017_50170302_59_dialog_content = "ต้องขออภัยด้วย คุณนินจา",
  ui_story_5017_50170302_60_dialog_content = "ตอนนี้ฉันยังตายไม่ได้หรอกนะ",
  ui_story_5017_50170302_61_dialog_content = "!",
  ui_story_5017_50170302_62_dialog_content = "รินเนะ! คุณไม่เป็นไรใช่มั้ย?",
  ui_story_5017_50170302_63_dialog_content = "ไม่เป็นไร แค่แผลเล็ก ๆ เท่านั้น",
  ui_story_5017_50170302_64_dialog_content = "เธอ...",
  ui_story_5017_50170302_65_dialog_content = "ซ่อนตัวในเงามืดแล้วก็ลอบทำร้ายรินเนะ กล้าดีนักนะ!",
  ui_story_5017_50170302_66_dialog_content = "ไอ้พวกขี้ขลาด เจอกำปั้นฉันหน่อยเป็นไง!",
  ui_story_5017_50170401_1_dialog_content = "ว้าว! เก่งไม่ใช่เล่นเลยนี่!",
  ui_story_5017_50170401_2_dialog_content = "ไม่ได้เจอศัตรูที่คู่ควรแบบนี้มานานแล้ว!",
  ui_story_5017_50170401_3_dialog_content = "น่าสนใจจริง ๆ!",
  ui_story_5017_50170401_4_dialog_content = "เดี๋ยวก่อน เธอคือ...",
  ui_story_5017_50170401_5_dialog_content = "หลบได้อีกแล้วเรอะ",
