  ui_story_5017_50170401_26_dialog_content = "แต่เพื่อนของฉันสองคนไม่เห็นหัวพวกผีเลยแม้แต่นิดเดียว ฉันก็เลยค่อย ๆ หายกลัวน่ะ",
