  ui_story_5017_50170401_56_dialog_content = "เฮ้...",
  ui_story_5017_50170401_57_dialog_content = "สวัสดี!",
  ui_story_5017_50170401_58_dialog_content = "พวกคุณ! สนใจเราหน่อย!",
