  ui_story_5017_50170501_19_dialog_content = "บ้านเกิดของฉันเป็นแบบนี้เองสินะ...",
  ui_story_5017_50170501_20_dialog_content = "ว่าแต่บ้านฉันจะอยู่ตรงไหนกันนะ?",
  ui_story_5017_50170501_21_dialog_content = "รู้แล้ว! ต้องเป็นคฤหาสน์หลังใหญ่สุดแน่ ๆ เลย!",
  ui_story_5017_50170501_22_dialog_content = "หึหึ สิ่งปลูกสร้างที่ใหญ่ที่สุดของโคฟุโจก็คือ<color=#FFB400>ปราสาทหลัก</color> แต่ที่นั่นมีคนจองแล้วน่ะนะ",
  ui_story_5017_50170501_23_dialog_content = "เจ้าของปราสาทแห่งนี้ก็คือผู้ดำรงตำแหน่ง<color=#FFB400>ท่านคุโบ</color> โชกุนผู้ปกครองโคฟุโจ",
  ui_story_5017_50170501_24_dialog_content = "ผู้ช่วยคนสนิทบางส่วนของท่านคุโบก็อาศัยอยู่ที่นั่นเช่นกัน",
  ui_story_5017_50170501_25_dialog_content = "รวมถึงฉันด้วย",
  ui_story_5017_50170501_26_dialog_content = "หือ? รินเนะ เธออยู่ในคฤหาสน์สุดหรูเหรอเนี่ย!",
  ui_story_5017_50170501_27_dialog_content = "ใช่แล้ว เพราะท่านคุโบคือพ่อบุญธรรมของฉัน",
  ui_story_5017_50170501_28_dialog_content = "ดีจัง...",
  ui_story_5017_50170501_29_dialog_content = "ฉันจะไม่ทะเลาะแย่งบ้านกับรินเนะหรอก เอาเป็นว่าฉันจะหาบ้านอยู่ข้าง ๆ รินเนะก็แล้วกัน!",
  ui_story_5017_50170501_30_dialog_content = "ฮะฮะ! ถ้าทำได้แบบนั้นก็ยอดเลย",
  ui_story_5017_50170501_31_dialog_content = "เขตที่มีคนพลุกพล่านใต้ปราสาทหลักนั่นมีชื่อว่า<color=#FFB400>ซาคาอิ</color>",
  ui_story_5017_50170501_32_dialog_content = "ที่นั่นมีอาหารอร่อยและอะไรสนุก ๆ ให้ทำมากมาย เหยาจะต้องชอบแน่ ๆ",
  ui_story_5017_50170501_33_dialog_content = "งั้นเหรอ! ต้องสนุกแน่ ๆ เลย!",
  ui_story_5017_50170501_34_dialog_content = "เอาล่ะ แขกผู้มาเยือนจากแดนไกล",
  ui_story_5017_50170501_35_dialog_content = "ยินดีต้อนรับสู่โคฟุโจ",
  ui_story_5017_50170501_36_dialog_content = "ถึงบ้านสักที!",
  ui_story_5017_50170501_37_dialog_content = "ขอบคุณที่ช่วยปกป้องเรามาตลอดทางนะ!",
  ui_story_5017_50170501_38_dialog_content = "ด้วยความยินดี...",
  ui_story_5017_50170501_39_dialog_content = "นี่! คุณยังไม่ได้ตอบฉันเลยนะ!",
  ui_story_5017_50170501_40_dialog_content = "หน้าฉันดูคุ้น ๆ รึเปล่า?",
  ui_story_5017_50170501_41_dialog_content = "เอ่อ...",
  ui_story_5017_50170501_42_dialog_content = "ตอนนั้นอาจจะไม่เหมือนตอนนี้สักเท่าไหร่...",
  ui_story_5017_50170501_43_dialog_content = "แต่พวกคุณอาจจะเคยเห็นฉันตอนเด็ก ๆ ก็ได้",
  ui_story_5017_50170501_44_dialog_content = "เอ่อ...",
  ui_story_5017_50170501_45_dialog_content = "ฉันคงจะเตี้ยกว่านี้ แล้วก็หน้ากลมกว่านี้",
  ui_story_5017_50170501_46_dialog_content = "ผมก็คงสั้นกว่า แล้วก็อาจจะมัดเป็นก้อนกลม ๆ...",
  ui_story_5017_50170501_47_dialog_content = "ขอบคุณที่ช่วยชีวิตพวกเราไว้!",
  ui_story_5017_50170501_48_dialog_content = "ทำไมจู่ ๆ ถึงโค้งคำนับล่ะ?",
  ui_story_5017_50170501_49_dialog_content = "ไม่เห็นหรือไงว่าพวกเขาอยากเปลี่ยนเรื่องคุยจะแย่แล้ว?",
  ui_story_5017_50170501_50_dialog_content = "แล้วก็ คุณคนต่างแดนที่แต่งตัวแปลก ๆ ทั้งสองคน ขอบคุณมากนะ!",
  ui_story_5017_50170501_51_dialog_content = "แต่งตัวแปลก ๆ งั้นเหรอ?",
  ui_story_5017_50170501_52_dialog_content = "แล้วก็...",
  ui_story_5017_50170501_53_dialog_content = "...",
  ui_story_5017_50170501_54_dialog_content = "...",
  ui_story_5017_50170501_55_dialog_content = "เราขอบคุณท่านเหลือเกินที่กรุณาเมตตา!",
  ui_story_5017_50170501_56_dialog_content = "แต่เรามีงานด่วนต้องทำ เพราะฉะนั้นคงต้องขอตัวก่อน",
  ui_story_5017_50170501_57_dialog_content = "ลาก่อน!",
  ui_story_5017_50170501_58_dialog_content = "อ้าว? ไปแล้วเหรอ?",
  ui_story_5017_50170501_59_dialog_content = "ทำไมรีบร้อนจัง...",
  ui_story_5017_50170501_60_dialog_content = "นี่เป็นช่วงเทศกาลคาสึกะ ทุกคนก็เลยยุ่งกับการเตรียมงาน",
