  ui_story_5017_50170501_62_dialog_content = "ก็ได้",
  ui_story_5017_50170501_63_dialog_content = "รินเนะเองก็งานยุ่งสินะ?",
  ui_story_5017_50170501_64_dialog_content = "ใช่",
  ui_story_5017_50170501_65_dialog_content = "ฉันจะต้องกลับปราสาทหลักแล้ว",
  ui_story_5017_50170501_66_dialog_content = "เขตนอกเมืองมีภูตผีออกอาละวาดมากเกินไปแล้ว เราจะต้องทำอะไรสักอย่าง",
  ui_story_5017_50170501_67_dialog_content = "โอ้...",
