  ui_story_5017_50170501_69_dialog_content = "หึหึ",
  ui_story_5017_50170501_70_dialog_content = "ถ้ามาทางเดียวกับฉัน เราก็ยังพอเดินเที่ยวชมเมืองได้นะ",
