  ui_story_5017_50170501_83_dialog_content = "เมื่อเทศกาลคาสึกะเริ่มขึ้นอย่างเป็นทางการ มันจะสนุกกว่านี้อีกนะ",
  ui_story_5017_50170501_84_dialog_content = "ผู้คนจะใส่ยูกาตะกับหน้ากากที่สวยที่สุด และมาชุมนุมกันที่ซาคาอิ",
