  ui_story_5017_50170501_168_dialog_content = "ทำไมพูดแบบนั้นล่ะ?",
  ui_story_5017_50170501_169_dialog_content = "พี่สาวชุดแดงพูดจานุ่มนวลมากเลยนะ แล้วเมื่อกี้เธอก็จะซื้อแอปเปิลเชื่อมด้วย!",
  ui_story_5017_50170501_170_dialog_content = "นั่นก็เพราะว่า...",
  ui_story_5017_50170501_171_dialog_content = "<size=30>เธออยู่กับโชกุนน่ะสิ</size>",
  ui_story_5017_50170501_172_dialog_content = "หืมม?",
  ui_story_5017_50170501_173_dialog_content = "แล้วมันทำไมเหรอ?",
  ui_story_5017_50170501_174_dialog_content = "โชกุนเป็นคนไม่ดีงั้นเหรอ?",
  ui_story_5017_50170501_175_dialog_content = "ชู่!",
  ui_story_5017_50170501_176_dialog_content = "ระวังปากหน่อย! ลูกจะพูดแบบนั้นในที่สาธารณะไม่ได้นะ!",
  ui_story_5017_50170501_177_dialog_content = "อืมม...",
  ui_story_5017_50170501_178_dialog_content = "วันนี้พ่อน่ากลัวจังเลย...",
  ui_story_5017_50170501_179_dialog_content = "ลูกยังเด็กไปสำหรับเรื่องนี้... แต่สักวันลูกก็จะเข้าใจ",
  ui_story_5017_50170501_180_dialog_content = "ทำตามที่พ่อสอนก็พอ พ่อไม่มีวันคิดร้ายกับลูกหรอก",
  ui_story_5017_50170501_181_dialog_content = "อื้อ...",
  ui_story_5017_50170501_182_dialog_content = "จำที่พ่อสอนได้มั้ย?",
  ui_story_5017_50170501_183_dialog_content = "อย่ายุ่งกับผู้หญิงชุดแดง... เธอเป็นคนไม่ดี...",
  ui_story_5017_50170501_184_dialog_content = "ดีมาก",
  ui_story_5017_50170501_185_dialog_content = "ยืนขายของทั้งวันคงจะเหนื่อยสินะ",
  ui_story_5017_50170501_186_dialog_content = "มาเถอะ พ่อจะซื้อน้ำแข็งไสให้",
  ui_story_5017_50170501_187_dialog_content = "เย่! น้ำแข็งไส!",
  ui_story_5017_50170601_1_dialog_content = "<color=#e8d9bb>ตุ๋ม...</color>",
  ui_story_5017_50170601_2_dialog_content = "โธ่... ไวซ์กับฉันอุตส่าห์ลำบากช้อนปลามาให้นายนะ!",
  ui_story_5017_50170601_3_dialog_content = "ขอให้มีชีวิตที่ดีล่ะ!",
  ui_story_5017_50170601_4_dialog_content = "ใช่แล้ว ขอให้มีชีวิตที่ดีนะ!",
  ui_story_5017_50170601_5_dialog_content = "แค่ปล่อยปลาเราต้องทำซึ้งขนาดนี้เลยเหรอ?",
  ui_story_5017_50170601_6_dialog_content = "นายไม่เข้าใจหรอก พวกปลาน่ะ...",
  ui_story_5017_50170601_7_dialog_content = "ไปกินข้าวกันมั้ย?",
  ui_story_5017_50170601_8_dialog_content = "ไป ๆ!",
  ui_story_5017_50170601_9_dialog_content = "เป็นคนง่าย ๆ จังแฮะ...",
  ui_story_5017_50170601_10_dialog_content = "รินเนะ มีร้านแนะนำมั้ย?",
  ui_story_5017_50170601_11_dialog_content = "ให้ฉันแนะนำเหรอ?",
  ui_story_5017_50170601_12_dialog_content = "แน่นอน เธอรู้จักเมืองดีกว่าเรานี่นา",
  ui_story_5017_50170601_13_dialog_content = "ขอคิดก่อนนะ...",
  ui_story_5017_50170601_14_dialog_content = "มีร้านประจำของฉันอยู่ไม่ไกลจากนี่",
  ui_story_5017_50170601_15_dialog_content = "ไม่สัญญาก็แล้วกันว่ารสชาติอาหารเป็นยังไง แต่รับประกันว่าวิวสวยไม่แพ้ใคร",
  ui_story_5017_50170601_16_dialog_content = "เอาล่ะ งั้นไปที่นั่นกันเถอะ!",
  ui_story_5017_50170601_17_dialog_content = "ยินดีต้อนรับ เชิญชั้นบนได้เลย",
  ui_story_5017_50170601_18_dialog_content = "โอ้ ว้าว!",
  ui_story_5017_50170601_19_dialog_content = "ยอดไปเลย!",
  ui_story_5017_50170601_20_dialog_content = "เห็นวิวทั้งเมืองเลย สวยอะไรยังงี้!",
  ui_story_5017_50170601_21_dialog_content = "ทุกคนกำลังยุ่งกับการเตรียมเทศกาลคาสึกะอยู่เลย",
  ui_story_5017_50170601_22_dialog_content = "แล้วเทศกาลคาสึกะนี่มันอะไรกันเหรอครับ?",
  ui_story_5017_50170601_23_dialog_content = "เป็นพิธีรำลึกหรือพิธีฉลองกันแน่?",
  ui_story_5017_50170601_24_dialog_content = "หึหึ~ ที่จริงมันก็ไม่ได้ซับซ้อนอะไร",
  ui_story_5017_50170601_25_dialog_content = "ตอนนี้เป็นฤดูของดอกซากุระ ชาวเมืองของเราจะหยุดทำทุกอย่างและใช้เวลาไปกับการชื่นชมความงามของดอกซากุระ",
  ui_story_5017_50170601_26_dialog_content = "เมื่อเวลาผ่านไป กิจกรรมนี้ก็กลายมาเป็นประเพณีสำคัญของชาวโคฟุโจ",
  ui_story_5017_50170601_27_dialog_content = "ถ้าอยากค้นหาที่มาให้ลึกกว่านั้น... ฤดูใบไม้ผลิก็เป็นจุดเริ่มต้นของปีใหม่",
  ui_story_5017_50170601_28_dialog_content = "ในระหว่างเทศกาล เราก็จะถวายเครื่องบวงสรวงแก่เทพเจ้า เพื่อปีที่อุดมสมบูรณ์และราบรื่น",
  ui_story_5017_50170601_29_dialog_content = "เข้าใจแล้วครับ",
  ui_story_5017_50170601_30_dialog_content = "ดอกซากุระบนเกาะเมฆาสวยมากจริง ๆ ควรค่าแก่การชื่นชม!",
  ui_story_5017_50170601_31_dialog_content = "สำหรับคนในท้องที่ ตัวเทศกาลเองน่ะ มีความหมายมากกว่าดอกซากุระเสียอีก",
  ui_story_5017_50170601_32_dialog_content = "เราควรไปเที่ยวที่ไหนบ้างระหว่างเทศกาลคาสึกะเหรอคะ?",
  ui_story_5017_50170601_33_dialog_content = "เราไม่ได้มาที่นี่บ่อย ๆ ฉันไม่อยากพลาดอะไรสนุก ๆ น่ะ!",
  ui_story_5017_50170601_34_dialog_content = "เอ่อ... ฉันเองก็บอกเธอได้ไม่มากหรอกนะ",
  ui_story_5017_50170601_35_dialog_content = "ที่จริงฉันไม่ได้เข้าร่วมเทศกาลคาสึกะของเกาะเมฆามาหลายปีแล้ว",
  ui_story_5017_50170601_36_dialog_content = "อ้าว? เธอเป็นมิโกะของที่นี่ไม่ใช่เหรอ?",
  ui_story_5017_50170601_37_dialog_content = "... ฉันเพิ่งได้เป็นมิโกะเมื่อปีที่แล้วเอง",
  ui_story_5017_50170601_38_dialog_content = "ก่อนหน้านั้น ฉัน<color=#FFB400>ฝึกวิชาอยู่ที่เกาะหลัก</color>",
  ui_story_5017_50170601_39_dialog_content = "เกาะหลัก?",
  ui_story_5017_50170601_40_dialog_content = "ใช่ ที่นั่นเป็นเกาะที่ใหญ่ที่สุดในหมู่เกาะนี้",
  ui_story_5017_50170601_41_dialog_content = "เกาะเล็ก ๆ อย่างเกาะเมฆาล้วนอยู่ภายใต้การปกครองของเกาะหลักทั้งสิ้น",
  ui_story_5017_50170601_42_dialog_content = "แสดงว่ารินเนะก็เป็นคนจากเกาะหลักงั้นเหรอ?",
  ui_story_5017_50170601_43_dialog_content = "ก็ไม่เชิง",
  ui_story_5017_50170601_44_dialog_content = "ตัวฉันเกิดที่เกาะเมฆา...",
  ui_story_5017_50170601_45_dialog_content = "แต่ต้องเดินทางไปรับการฝึกเพื่อสืบทอดตำแหน่งมิโกะที่เกาะหลัก",
  ui_story_5017_50170601_46_dialog_content = "ว้าว คงจะลำบากน่าดูเนอะ ฉันเองก็เคยฝึกหนักมาก่อน ฉันเข้าใจเลยแหละ",
  ui_story_5017_50170601_47_dialog_content = "ผมคิดว่าการฝึกของคุณไม่น่าจะเหมือนกันนะ...",
  ui_story_5017_50170601_48_dialog_content = "ฉันไม่รู้หรอกว่าเทศกาลคาสึกะสมัยนี้เป็นยังไงบ้าง...",
  ui_story_5017_50170601_49_dialog_content = "ขอโทษด้วยนะที่ช่วยอะไรพวกคุณไม่ค่อยได้",
  ui_story_5017_50170601_50_dialog_content = "ไม่ต้องห่วง เพราะทุกคนยังมีฉันอยู่!",
  ui_story_5017_50170601_51_dialog_content = "จำได้มั้ย? ฉันยังมีคู่มือเที่ยวเกาะเมฆาอยู่นะ!",
  ui_story_5017_50170601_52_dialog_content = "...",
  ui_story_5017_50170601_53_dialog_content = "...",
  ui_story_5017_50170601_54_dialog_content = "ฉันลืมคู่มือนั่นไปได้ไงนะ...",
  ui_story_5017_50170601_55_dialog_content = "อย่าดูถูกคู่มือของฉันนะ! ข้อมูลมันแน่นจะตาย!",
