  ui_story_5017_50170601_57_dialog_content = "นี่หยิบมาอ่านบ่อย ๆ ด้วยเรอะ?",
  ui_story_5017_50170601_58_dialog_content = "ใช่ เนื้อหาในนั้นน่าสนใจมากเลยนะ แถมยังมีคอลัมน์นิทานพื้นบ้านสั้น ๆ เยอะแยะไปหมด",
  ui_story_5017_50170601_59_dialog_content = "นิทานพื้นบ้าน?",
  ui_story_5017_50170601_60_dialog_content = "เดี๋ยวอ่านให้ฟังนิดหน่อยก็แล้วกัน...",
  ui_story_5017_50170601_61_dialog_content = "บ้านเรือนบางแห่งในเขตชานเมืองโคฟุโจเป็นบ้านที่ถูกทิ้งร้างไม่มีคนอยู่อาศัย",
  ui_story_5017_50170601_62_dialog_content = "แต่ผู้ที่เดินผ่านไปผ่านมากลับได้ยินเสียงคนกวาดใบไม้...",
  ui_story_5017_50170601_63_dialog_content = "เป็นไง เป็นไง?",
  ui_story_5017_50170601_64_dialog_content = "ก็เรื่องผีทั่ว ๆ ไปนี่ครับ...",
  ui_story_5017_50170601_65_dialog_content = "ยังมีอีกนะ!",
  ui_story_5017_50170601_66_dialog_content = "เกาะเมฆามีสมบัติโบราณสามชิ้นที่หายสาบสูญไปเนิ่นนาน",
  ui_story_5017_50170601_67_dialog_content = "หญิงชราผู้อาวุโสที่สุดในเมืองเคยบอกฉันว่าสมบัติเหล่านี้สามารถดลบันดาลสิ่งที่ปรารถนาให้เป็นจริง...",
