  ui_story_5017_50170601_90_dialog_content = "<color=#e8d9bb>โครม!</color>",
  ui_story_5017_50170601_91_dialog_content = "อ๊าาา!",
  ui_story_5017_50170601_92_dialog_content = "ท่านโชกุน! ผมไม่ได้ทำอะไรผิด! ผมไม่รู้อะไรจริง ๆ!",
