  ui_story_5017_50170601_100_dialog_content = "เป็นไปไม่ได้... ภูตผีปรากฏตัวที่นี่ได้ยังไง?",
  ui_story_5017_50170602_1_dialog_content = "พวกผีบุกเข้ามาถึงในเมือง...",
  ui_story_5017_50170602_2_dialog_content = "จะรอช้าไม่ได้แล้ว ฉันจะต้องไปที่ปราสาทหลักเดี๋ยวนี้!",
  ui_story_5017_50170602_3_dialog_content = "ก่อนหน้านี้คุณก็บอกว่าจะกลับปราสาทหลัก เรื่องนี้เกี่ยวกับผีพวกนี้ใช่มั้ยครับ?",
  ui_story_5017_50170602_4_dialog_content = "ใช่",
  ui_story_5017_50170602_5_dialog_content = "อุปกรณ์ศักดิ์สิทธิ์ที่ส่งต่อให้กับมิโกะจากรุ่นสู่รุ่น สิ่งนี้ถูกเก็บรักษาอยู่ในปราสาทหลักเพื่อให้ผู้คนเคารพบูชา...",
  ui_story_5017_50170602_6_dialog_content = "<color=#FFB400>กระจกเมฆา</color>",
  ui_story_5017_50170602_7_dialog_content = "ถ้านำกระจกเมฆาออกมาใช้ ภัยคุกคามจากวิญญาณร้ายพวกนี้ก็จะจบลง",
  ui_story_5017_50170602_8_dialog_content = "อุปกรณ์ศักดิ์สิทธิ์ของมิโกะ... ทำไมถึงทิ้งไว้ที่ปราสาทล่ะครับ นึกว่าคุณจะพกมันติดตัวซะอีก?",
  ui_story_5017_50170602_9_dialog_content = "ตอนนี้กระจกเมฆาอยู่ในความดูแลของท่านคุโบชั่วคราว",
  ui_story_5017_50170602_10_dialog_content = "ฉันไม่ได้ปฏิบัติหน้าที่เป็นมิโกะมานาน จึงไม่มีคุณสมบัติดูแลกระจกเมฆา",
