  ui_story_5017_50170602_12_dialog_content = "เขาคือผู้ปกครองเมืองโคฟุโจแห่งนี้",
  ui_story_5017_50170602_13_dialog_content = "ผู้คนต่างเรียกเขาว่าโชกุน",
  ui_story_5017_50170602_14_dialog_content = "อ๋อ! คนที่เจ้าของร้านพูดถึงนั่นเอง!",
  ui_story_5017_50170602_X14_dialog_content = "ถูกต้อง",
  ui_story_5017_50170602_15_dialog_content = "(ถึงฉันจะไม่เคยสัมผัสกับกระจกเมฆามาก่อน...)",
  ui_story_5017_50170602_16_dialog_content = "(แต่นี่เป็นทางเดียวเท่านั้น... ฉันจะต้องลอง)",
  ui_story_5017_50170602_17_dialog_content = "(หวังว่าท่านคุโบจะอภัยให้กับการกระทำโดยพลการของฉัน...)",
