  ui_story_5017_50170602_19_dialog_content = "พวกผีบุกเข้ามาถึงในเมืองแล้ว เราช่วยคุณได้นะ",
  ui_story_5017_50170602_20_dialog_content = "...",
  ui_story_5017_50170602_21_dialog_content = "ก็ได้ ในสถานการณ์แบบนี้ฉันคงปฏิเสธน้ำใจพวกคุณไม่ได้หรอก",
  ui_story_5017_50170602_22_dialog_content = "ขอบคุณนะ",
  ui_story_5017_50170602_23_dialog_content = "ไวซ์ เหยา ได้ยินมั้ย?",
  ui_story_5017_50170602_24_dialog_content = "ไป ๆ!",
  ui_story_5017_50170602_25_dialog_content = "ฉันไม่เข้าใจตรงครึ่งแรกเท่าไหร่",
  ui_story_5017_50170602_26_dialog_content = "แต่เราจะไปกับรินเนะใช่มั้ย!",
  ui_story_5017_50170602_27_dialog_content = "เหยานี่หัวไวจังเลยนะ",
  ui_story_5017_50170602_28_dialog_content = "อะฮ่า!",
  ui_story_5017_50170602_29_dialog_content = "ปราสาทหลักอยู่ทางนี้ กรุณาตามฉันมา",
  ui_story_5017_50170602_30_dialog_content = "PlayerName... ฉันหยุดคิดไม่ได้เลย ว่าทำไมผีมากมายถึงโผล่มาแบบนี้",
  ui_story_5017_50170602_31_dialog_content = "โทรจิตของนายเห็นอะไรบ้างรึเปล่า?",
  ui_story_5017_50170602_32_dialog_content = "ไม่รู้สิ เกิดมาฉันก็ไม่เคยเห็นอะไรแบบนี้มาก่อน",
  ui_story_5017_50170602_33_dialog_content = "ฉันรู้สึกได้แค่ว่าพลังงานที่ก่อตัวเป็นร่างกายของผีมันค่อนข้างจะคล้ายกับลูมินา แค่นั้นแหละ...",
  ui_story_5017_50170602_34_dialog_content = "ฉันไม่รู้ว่าอะไรที่รวมพลังงานนี้เข้าด้วยกัน แล้วก็ไม่รู้ว่าอะไรขับเคลื่อนภูตผีพวกนี้...",
