  ui_story_5017_50170602_37_dialog_content = "แล้วนายคิดว่าเรื่องทุกอย่างมันเป็นยังไงกันล่ะ?",
  ui_story_5017_50170602_38_dialog_content = "จู่ ๆ โซรอซก็ขัดข้อง แล้วชาวบ้านก็พูดเรื่องการเปิดออกของประตูนรก...",
