  ui_story_5017_50170701_5_dialog_content = "ปัทโธ่ ไปไหนอีกล่ะเนี่ย?",
  ui_story_5017_50170701_6_dialog_content = "รินเนะ ระวัง!",
  ui_story_5017_50170701_7_dialog_content = "คุณนินจา คุณบาดเจ็บอยู่นี่",
  ui_story_5017_50170701_8_dialog_content = "แล้วไง?",
  ui_story_5017_50170701_9_dialog_content = "ตอนนี้ฉันกำลังยุ่งอยู่ ทำไมไม่รักษาแผลของตัวเองก่อนล่ะ?",
  ui_story_5017_50170701_10_dialog_content = "ฉันเองก็ไม่มีเวลาเหมือนกัน",
  ui_story_5017_50170701_11_dialog_content = "เธอต้องตายเดี๋ยวนี้",
  ui_story_5017_50170701_12_dialog_content = "พวกผีบุกมาอีกแล้ว!",
  ui_story_5017_50170701_13_dialog_content = "เราควรจัดการฝั่งไหนก่อนดีล่ะ?",
  ui_story_5017_50170701_14_dialog_content = "อาเมะโมริ เรามาทำสัญญาลูกผู้ชายอีกทีดีกว่า...",
  ui_story_5017_50170701_15_dialog_content = "ผีพวกนั้นไม่ใช่ปัญหาของฉัน",
  ui_story_5017_50170701_16_dialog_content = "ฉันมาเพื่อจบชีวิตมิโกะคนนี้",
  ui_story_5017_50170701_17_dialog_content = "PlayerName เราต้องหยุดอาเมะโมริให้ได้!",
  ui_story_5017_50170701_18_dialog_content = "ตอนนี้ไม่ใช่เวลามาสู้กับผีนะ!",
  ui_story_5017_50170701_19_dialog_content = "ฉันก็พยายามอยู่! คิดว่าฉันนั่งเหม่อเฉย ๆ หรือไง?",
  ui_story_5017_50170701_20_dialog_content = "เธอไปโจมตีทางขวา...",
  ui_story_5017_50170701_21_dialog_content = "!",
  ui_story_5017_50170701_22_dialog_content = "หยุดก่อน! มีอะไรบางอย่างอยู่แถวนี้!",
  ui_story_5017_50170701_23_dialog_content = "อะไรอีกล่ะ? ผีพวกนี้ยังไม่พออีกเหรอเนี่ย?",
  ui_story_5017_50170701_24_dialog_content = "มันแข็งแกร่งกว่าผีพวกนี้มาก ๆ!",
  ui_story_5017_50170701_25_dialog_content = "รินเนะ อาเมะโมริ หลบเร็ว!",
  ui_story_5017_50170701_26_dialog_content = "แย่ล่ะ!",
  ui_story_5017_50170701_27_dialog_content = "อะไรกันเนี่ย...",
  ui_story_5017_50170701_28_dialog_content = "ไปให้พ้น",
  ui_story_5017_50170701_29_dialog_content = "เกิดอะไรขึ้น?",
  ui_story_5017_50170701_30_dialog_content = "ดาบ... แห่งยมโลก...",
  ui_story_5017_50170701_31_dialog_content = "<size=45>ดาบแห่ง... ยมโลก!</size>",
  ui_story_5017_50170701_32_dialog_content = "เจ้านี่พูดภาษาคนได้ด้วยเหรอ?",
  ui_story_5017_50170701_33_dialog_content = "ใช่...",
  ui_story_5017_50170701_34_dialog_content = "ไม่นึกเลยว่าจะได้เจอกับผีคั่งแค้น...",
  ui_story_5017_50170701_35_dialog_content = "นี่มันเลวร้ายมาก ๆ เลย",
  ui_story_5017_50170701_36_dialog_content = "ผีคั่งแค้น? พวกมันต่างจากผีตัวอื่น ๆ ยังไงเหรอ?",
  ui_story_5017_50170701_37_dialog_content = "ผีคั่งแค้นคือวิญญาณที่มีความพยาบาทแรงกล้า แม้แต่ความตายก็ไม่อาจพวกเขาสงบลงได้",
  ui_story_5017_50170701_38_dialog_content = "ด้วยการเกื้อหนุนจากหยิน พวกมันจึงได้รับพลังอันแข็งแกร่งเหลือเชื่อเมื่อถือกำเนิดขึ้นมา...",
  ui_story_5017_50170701_39_dialog_content = "มันก็เลยพูดได้สินะ?",
  ui_story_5017_50170701_40_dialog_content = "ถูกต้อง ความเกลียดชังและความแค้นยังฝังแน่นในจิตสำนึกที่หลงเหลืออยู่ เป็นพันธะสุดท้ายที่ผูกมัดพวกมันกับโลกมนุษย์",
  ui_story_5017_50170701_41_dialog_content = "ชื่อ \"ดาบแห่งยมโลก\" อาจมีความหมายพิเศษกับมัน",
  ui_story_5017_50170701_42_dialog_content = "โอ... อ๊ากกก!",
  ui_story_5017_50170701_43_dialog_content = "ดาบ... แห่งยมโลก...",
  ui_story_5017_50170701_44_dialog_content = "แก... รู้จัก...",
  ui_story_5017_50170701_45_dialog_content = "หวา มันมาหาเราแล้ว!",
  ui_story_5017_50170701_46_dialog_content = "ฮึบ!",
  ui_story_5017_50170701_47_dialog_content = "เจ้าพวกชั่ว! เจอกำปั้นฉันหน่อยเป็นไง...",
  ui_story_5017_50170701_48_dialog_content = "เหยา!",
  ui_story_5017_50170701_49_dialog_content = "*แค่ก*",
  ui_story_5017_50170701_50_dialog_content = "ไม่ต้องห่วง ฉันไม่เป็นไร...",
