  ui_story_5017_50170701_54_dialog_content = "อ๊ะ! รินเนะ! เธอมาช่วยฉัน!",
  ui_story_5017_50170701_55_dialog_content = "อย่าเพิ่งรีบดีใจไป",
  ui_story_5017_50170701_56_dialog_content = "ในสถานการณ์แบบนี้ ฉันเองก็ไม่รู้ว่าจะรับมือผีคั่งแค้นไหวหรือเปล่า...",
