  ui_story_5017_50170702_101_dialog_content = "เดี๋ยวเราก็จะโดนผีจำนวนมหาศาลล้อม!",
  ui_story_5017_50170702_102_dialog_content = "เราไม่มีที่ให้หนี แต่ถึงจะสู้ก็แทบไม่มีโอกาสชนะ",
  ui_story_5017_50170702_103_dialog_content = "ไม่ว่าหยกชิ้นนั้นจะสำคัญแค่ไหน แต่ถ้าเธอตายที่นี่มันก็ไร้ประโยชน์!",
  ui_story_5017_50170702_104_dialog_content = "...",
  ui_story_5017_50170702_105_dialog_content = "ก็ได้",
  ui_story_5017_50170702_106_dialog_content = "เธอปล่อยแล้ว!",
  ui_story_5017_50170702_107_dialog_content = "PlayerName เจรจาเก่งไม่เบาเลยนี่!",
  ui_story_5017_50170702_108_dialog_content = "ขึ้นไปบนหลังคา",
  ui_story_5017_50170702_109_dialog_content = "เร็วเข้า!",
  ui_story_5017_50170702_110_dialog_content = "เอ่อ? เธอมีแผนรึเปล่าเนี่ย?",
  ui_story_5017_50170702_111_dialog_content = "!",
  ui_story_5017_50170702_112_dialog_content = "จริงด้วย! อาจจะได้ผลก็ได้!",
  ui_story_5017_50170702_113_dialog_content = "พวกผียังไม่ขึ้นมาบนหลังคา!",
  ui_story_5017_50170702_114_dialog_content = "โอ้!",
  ui_story_5017_50170702_115_dialog_content = "ว่าแต่...อาเมะโมริ เธอช่วยพวกเราเหรอ?",
  ui_story_5017_50170702_116_dialog_content = "ในเมื่อเธอไม่ยอมให้หยกนั่นกับฉัน...",
  ui_story_5017_50170702_117_dialog_content = "เธอจะยังตายไม่ได้",
  ui_story_5017_50170702_118_dialog_content = "ฮึ่มม! ฉันอยากจะโชว์เพลงหมัดจนแทบจะทนไม่ไหวแล้ว!",
  ui_story_5017_50170702_119_dialog_content = "หนึ่ง สอง...",
  ui_story_5017_50170702_120_dialog_content = "สาม!",
  ui_story_5017_50170702_121_dialog_content = "หวาาาา!",
  ui_story_5017_50170702_122_dialog_content = "<color=#e8d9bb>โครม!</color>",
  ui_story_5017_50170702_123_dialog_content = "โอ๊ย...",
  ui_story_5017_50170702_124_dialog_content = "PlayerName นายต้องออกกำลังกายจริง ๆ จัง ๆ แล้วนะเนี่ย แค่ขึ้นหลังคายังทำไม่ได้เลย",
  ui_story_5017_50170702_125_dialog_content = "ต้องให้คุณเหยาโยนขึ้นมาแบบนี้",
  ui_story_5017_50170702_126_dialog_content = "หึหึ",
  ui_story_5017_50170702_127_dialog_content = "คุณ PlayerName รู้สึกยังไงบ้าง?",
  ui_story_5017_50170702_128_dialog_content = "เดี๋ยวฉันช่วยพยุงให้นะ",
  ui_story_5017_50170702_129_dialog_content = "โอย... ขอบคุณครับ!",
  ui_story_5017_50170702_130_dialog_content = "ทำไมทุกคนถึงไม่ใจดีเหมือนคุณรินเนะเลยนะ?",
  ui_story_5017_50170702_131_dialog_content = "นี่! ต้องการจะสื่ออะไรน่ะ?",
  ui_story_5017_50170702_132_dialog_content = "แล้วเหยากับอาเมะโมริล่ะ? ทำไมนานจังเลย?",
  ui_story_5017_50170702_133_dialog_content = "อาเมะโมริ เธอไปก่อนเลย!",
  ui_story_5017_50170702_134_dialog_content = "เดี๋ยวพวกผีจะไล่เธอทันนะ!",
  ui_story_5017_50170702_135_dialog_content = "เธอไปก่อนเถอะ",
  ui_story_5017_50170702_136_dialog_content = "บ้าเอ๊ย! นี่ไม่ใช่เวลามามีมารยาทนะ!",
  ui_story_5017_50170702_137_dialog_content = "ฉันปีนเร็วกว่าเธออยู่แล้ว",
  ui_story_5017_50170702_138_dialog_content = "เธอกับฉันจะต้องรอดไปให้ได้",
  ui_story_5017_50170702_139_dialog_content = "ก็ได้ งั้นเราไปด้วยกัน!",
  ui_story_5017_50170702_140_dialog_content = "<color=#e8d9bb>ปึง ปึง ปึง...</color>",
  ui_story_5017_50170702_141_dialog_content = "<color=#e8d9bb>เปรี้ยง!</color>",
  ui_story_5017_50170702_142_dialog_content = "อาเมะโมริ!",
  ui_story_5017_50170702_143_dialog_content = "ฉันไม่เป็นไร...",
  ui_story_5017_50170702_144_dialog_content = "เร็วเข้า! รีบปีนขึ้นไป!",
  ui_story_5017_50170702_145_dialog_content = "อ๊ะ!",
  ui_story_5017_50170702_146_dialog_content = "เป็นอะไรไป?",
  ui_story_5017_50170702_147_dialog_content = "มีบางอย่างจับข้อเท้าฉันไว้!",
  ui_story_5017_50170702_148_dialog_content = "ฉันจะช่วยเธอเอง",
  ui_story_5017_50170702_149_dialog_content = "ระวังให้ดีนะ!",
  ui_story_5017_50170702_150_dialog_content = "ชิ...",
  ui_story_5017_50170702_151_dialog_content = "เดี๋ยวฉันหาทางให้นะ!",
  ui_story_5017_50170702_152_dialog_content = "ไปเถอะน่า!",
  ui_story_5017_50170702_153_dialog_content = "เร็วเข้าเถอะ! ฉันบอกแล้วไงว่าให้เธอไปก่อน!",
  ui_story_5017_50170702_154_dialog_content = "น่าหงุดหงิดจริงชะมัด! เลิกทำตัวมีมารยาทแบบนั้นได้มั้ย!",
  ui_story_5017_50170702_155_dialog_content = "หวาาา!",
  ui_story_5017_50170702_156_dialog_content = "!",
  ui_story_5017_50170702_157_dialog_content = "ไม่เป็นไรนะ?",
  ui_story_5017_50170702_158_dialog_content = "ฉันไม่เป็นไร...",
  ui_story_5017_50170702_159_dialog_content = "...",
  ui_story_5017_50170702_160_dialog_content = "โอบไหล่ฉันไว้",
  ui_story_5017_50170702_161_dialog_content = "เธอ...",
  ui_story_5017_50170702_162_dialog_content = "จะทำอะไรของเธอเนี่ย? ไม่ต้องฝืนขนาดนั้นก็ได้มั้ง!",
  ui_story_5017_50170702_163_dialog_content = "ตอนนี้ชีวิตของเธอไม่ใช่ของเธอคนเดียวแล้ว",
  ui_story_5017_50170702_164_dialog_content = "อย่างที่ฉันบอกไว้ ฉันกับเธอยังตายไม่ได้",
  ui_story_5017_50170702_165_dialog_content = "แต่แบบนี้เราจะตายกันทั้งคู่นะ!",
  ui_story_5017_50170702_166_dialog_content = "หา? นั่นมัน...",
  ui_story_5017_50170702_167_dialog_content = "รินเนะ! คุณกระโดดลงไปทำไม?",
  ui_story_5017_50170702_168_dialog_content = "มิโกะ?",
  ui_story_5017_50170702_169_dialog_content = "ทำอะไรของเธอน่ะ? จะใช้โอกาสนี้กำจัดฉันงั้นเหรอ?",
  ui_story_5017_50170702_170_dialog_content = "หึหึ",
  ui_story_5017_50170702_171_dialog_content = "...",
  ui_story_5017_50170702_172_dialog_content = "ทำไมกัน?",
  ui_story_5017_50170702_173_dialog_content = "ฉันต้องมีเหตุผลด้วยเหรอ? นี่ไม่ใช่เรื่องของเธอคนเดียวหรอกนะ",
  ui_story_5017_50170702_174_dialog_content = "เธอไม่เคยเป็นศัตรูของฉันอยู่แล้ว",
  ui_story_5017_50170702_175_dialog_content = "ศัตรูของฉัน<color=#FFB400>คือพวกภูตผีเท่านั้น</color>",
  ui_story_5017_50170801_1_dialog_content = "ทั้งสองคนรีบขึ้นมาก่อนเถอะ!",
  ui_story_5017_50170801_2_dialog_content = "ไม่ได้! รินเนะยังอยู่ข้างล่าง!",
  ui_story_5017_50170801_3_dialog_content = "ฉันจะต้องช่วยเธอ!",
  ui_story_5017_50170801_4_dialog_content = "ใจเย็นก่อนนะ!",
  ui_story_5017_50170801_5_dialog_content = "ผีเยอะขนาดนั้น เธอตายได้เลยนะ!",
  ui_story_5017_50170801_6_dialog_content = "แล้วจะให้ทำยังไง? ยืนดูเธอตายเฉย ๆ งั้นเหรอ?",
  ui_story_5017_50170801_7_dialog_content = "PlayerName นายพอจะมีแผนอะไรมั้ย?",
  ui_story_5017_50170801_8_dialog_content = "ฉันกำลังคิดอยู่!",
  ui_story_5017_50170801_9_dialog_content = "(รินเนะ คุณได้ยินผมมั้ย?)",
  ui_story_5017_50170801_10_dialog_content = "(สนามพลังงานข้างล่างวุ่นวายมาก ผมมองไม่ชัดเลย)",
  ui_story_5017_50170801_11_dialog_content = "(รินเนะ? ช่วยตอบผมที...)",
  ui_story_5017_50170801_12_dialog_content = "<color=#e8d9bb>ฟึบ!</color>",
  ui_story_5017_50170801_13_dialog_content = "?",
  ui_story_5017_50170801_14_dialog_content = "<color=#e8d9bb>ฟึบ!</color>",
  ui_story_5017_50170801_15_dialog_content = "อ๊าาา!",
  ui_story_5017_50170801_16_dialog_content = "แสงนั่นมันอะไรน่ะ?",
  ui_story_5017_50170801_17_dialog_content = "ฉันก็เห็นเหมือนกัน!",
  ui_story_5017_50170801_18_dialog_content = "ในที่สุด!",
  ui_story_5017_50170801_19_dialog_content = "PlayerName นั่นมันอะไรเหรอ?",
