  ui_story_5017_50170801_21_dialog_content = "นายไม่เห็นหรือไง?",
  ui_story_5017_50170801_22_dialog_content = "เห็นสิ",
  ui_story_5017_50170801_23_dialog_content = "เห็นมาสองครั้งแล้วด้วย...",
  ui_story_5017_50170801_24_dialog_content = "เดินทางกันต่อเถอะ ไปที่โคฟุโจกัน",
  ui_story_5017_50170801_25_dialog_content = "ได้เลย",
  ui_story_5017_50170801_26_dialog_content = "<color=#e8d9bb>ฟึบ!</color>",
  ui_story_5017_50170801_27_dialog_content = "หืม?",
  ui_story_5017_50170801_28_dialog_content = "เรามาเดินเล่นกันมั้ย?",
  ui_story_5017_50170801_29_dialog_content = "ได้ครับ...",
  ui_story_5017_50170801_30_dialog_content = "<color=#e8d9bb>ฟึบ!</color>",
  ui_story_5017_50170801_31_dialog_content = "?",
  ui_story_5017_50170801_32_dialog_content = "หรือว่าจะเป็นผี?",
  ui_story_5017_50170801_33_dialog_content = "<color=#e8d9bb>พรึบ... พรึบ... พรึบ...</color>",
  ui_story_5017_50170801_34_dialog_content = "ฟู่!",
  ui_story_5017_50170801_35_dialog_content = "หวา!",
  ui_story_5017_50170801_36_dialog_content = "<size=45>ผีจริง ๆ ด้วย!</size>",
  ui_story_5017_50170801_37_dialog_content = "เอ่อ... ที่จริง...",
  ui_story_5017_50170801_38_dialog_content = "ช่างเถอะ นั่นมันไม่สำคัญหรอก...",
