  ui_story_5017_50170801_47_dialog_content = "แล้วทำไมเธอมาอยู่นี่ได้ล่ะ?",
  ui_story_5017_50170801_48_dialog_content = "ที่จริง ฉันก็อยู่กับพวกคุณมาตลอดนั่นล่ะ...",
