  ui_story_5017_50170801_50_dialog_content = "ตอนที่คุณพบท่านมิโกะครั้งแรกไงล่ะ...",
  ui_story_5017_50170801_51_dialog_content = "ตั้งแต่แรกเลยเรอะ!",
  ui_story_5017_50170801_52_dialog_content = "แสดงว่าเงาที่บินไปบินมานั่น...",
  ui_story_5017_50170801_53_dialog_content = "ใช่... นั่นคือฉันเอง",
  ui_story_5017_50170801_54_dialog_content = "หึหึ คายาโนะขี้อายมาก ๆ เวลาอยู่ต่อหน้าคนไม่รู้จัก ความไวในการหลบหน้าคนนี่เรียกได้ว่าเท่าความเร็วแสงเลยล่ะ",
  ui_story_5017_50170801_55_dialog_content = "ถ้าเธอไม่เผยตัวออกมาเองก็ไม่มีใครมองเธอทันหรอก",
  ui_story_5017_50170801_56_dialog_content = "ไม่แปลกเลยที่เธอจะช่วยรินเนะจากฝูงผีได้...",
  ui_story_5017_50170801_57_dialog_content = "<color=#e8d9bb>แก๊ก... แก๊ก...</color>",
  ui_story_5017_50170801_58_dialog_content = "ผีบางตัวปีนขึ้นหลังคามาแล้ว!",
  ui_story_5017_50170801_59_dialog_content = "ตามตื๊อไม่เลิกเลยนะ...",
  ui_story_5017_50170801_60_dialog_content = "เหอะ! ดูให้ดี! ฉันจะซัดพวกมันทุกตัวให้ร่วงเลย!",
  ui_story_5017_50170802_1_dialog_content = "กรุณาตามฉันมา...",
  ui_story_5017_50170802_2_dialog_content = "ฉันรู้ทางไปปราสาทหลัก...",
  ui_story_5017_50170802_3_dialog_content = "รินเนะ ให้ฉันช่วยนะ",
