  ui_story_5017_50170802_19_dialog_content = "ทั้งสุภาพแล้วก็อ่อนโยนมากเลย...",
  ui_story_5017_50170802_20_dialog_content = "พวกเขาอยู่ข้าง ๆ คุณเหรอ?",
  ui_story_5017_50170802_21_dialog_content = "ใช่...",
  ui_story_5017_50170802_22_dialog_content = "มีคนนึงนั่งบนไหล่คุณด้วย...",
  ui_story_5017_50170802_23_dialog_content = "เขาอยากรู้ว่าคุณกินข้าวรึยัง...",
