  ui_story_5017_50170802_25_dialog_content = "ขอบคุณที่ถามนะ...",
  ui_story_5017_50170802_26_dialog_content = "เราใกล้ถึงแล้ว",
  ui_story_5017_50170802_27_dialog_content = "คุณนินจา ฉันไม่เคยเห็นเธอฟังคนอื่นขนาดนี้มาก่อน",
  ui_story_5017_50170802_28_dialog_content = "...",
  ui_story_5017_50170802_29_dialog_content = "ได้มองหน้าเธอโดยไม่โดนอาวุธจ่อที่คอ ฉันเองก็ยังไม่ชินเท่าไหร่",
  ui_story_5017_50170802_30_dialog_content = "... ฉันจะทำหรือไม่ทำอะไรมันก็เรื่องของฉัน",
  ui_story_5017_50170802_31_dialog_content = "โธ่เอ๊ย",
  ui_story_5017_50170802_32_dialog_content = "ความตั้งใจที่ \"สังหารมิโกะ\" มันจบลงแค่นี้เองรึ?",
  ui_story_5017_50170802_33_dialog_content = "...",
  ui_story_5017_50170802_34_dialog_content = "ถ้าจะตอบแทนที่ฉันช่วยชีวิตเธอไว้... ฉันว่าอย่าเลยจะดีกว่า",
