  ui_story_5017_50170802_36_dialog_content = "ฉันไม่ต้องให้เธอมาสอนการเป็นนินจาหรอกนะ",
  ui_story_5017_50170802_37_dialog_content = "หึหึ ถ้าอย่างนั้นก็ดีแล้ว",
  ui_story_5017_50170802_38_dialog_content = "ได้ตายด้วยมือเธอ ฉันว่ามันก็น่ารักดีเหมือนกัน",
  ui_story_5017_50170802_39_dialog_content = "อย่าทำให้ฉันผิดหวังล่ะ",
  ui_story_5017_50170802_40_dialog_content = "<color=#e8d9bb>คึ่ก...!</color>",
  ui_story_5017_50170802_41_dialog_content = "!",
  ui_story_5017_50170802_42_dialog_content = "<size=45>เจ้าพวกชั่ว ถอยไปซะ!</size>",
  ui_story_5017_50170802_43_dialog_content = "พวกหนอนแมลงที่บังอาจคุกคามความปลอดภัยของท่านมิโกะ...",
  ui_story_5017_50170802_44_dialog_content = "จะต้องถูกกำจัด!",
  ui_story_5017_50170802_45_dialog_content = "ทำไมเราต้องมาสู้กันอีกแล้วล่ะเนี่ย?",
  ui_story_5017_50170802_46_dialog_content = "คนพวกนี้คือ...",
  ui_story_5017_50170802_47_dialog_content = "ซามูไรของท่านโชกุนน่ะ...",
  ui_story_5017_50170802_48_dialog_content = "พวกเขาภักดีต่อโคฟุโจและมีหน้าที่คุ้มครองความปลอดภัยของท่านมิโกะ...",
  ui_story_5017_50170802_49_dialog_content = "น่าประหลาดใจยิ่งนัก...",
  ui_story_5017_50170802_50_dialog_content = "พวกกบฏที่บ่อนทำลายและก่อความขัดแย้งในโคฟุโจยังเหลือรอดอยู่อีกรึนี่!",
  ui_story_5017_50170802_51_dialog_content = "<color=#FFB400>บ่อนทำลายและก่อความขัดแย้งงั้นเหรอ?</color>",
  ui_story_5017_50170802_52_dialog_content = "เข้าใจใส่ความกันดีนี่",
  ui_story_5017_50170802_53_dialog_content = "!",
  ui_story_5017_50170802_54_dialog_content = "(เธอตัดไม้ไผ่ทำไมน่ะ? ระบายอารมณ์โกรธอยู่เหรอ?)",
  ui_story_5017_50170802_55_dialog_content = "ฆ่าเธอซะ!",
  ui_story_5017_50170802_56_dialog_content = "ฆ่าฉัน? คิดว่ามีปัญญาทำได้เรอะ?",
  ui_story_5017_50170802_57_dialog_content = "แกถอนรากถอนโคนพวกเราไม่ได้หรอก",
  ui_story_5017_50170802_58_dialog_content = "พวกแกไม่มีทางยึดโคฟุโจไว้ได้ตลอดไปหรอก",
  ui_story_5017_50170802_59_dialog_content = "บ้าเอ๊ย... มันหนีไปได้...",
  ui_story_5017_50170802_60_dialog_content = "ท่านมิโกะ ไม่เป็นไรใช่มั้ย?",
  ui_story_5017_50170802_61_dialog_content = "ฉันปลอดภัยดี",
  ui_story_5017_50170802_62_dialog_content = "ดีใจที่ได้เจอนะ แสดงว่าทุกคนที่นี่ยังปลอดภัยใช่มั้ย",
  ui_story_5017_50170802_63_dialog_content = "ปลอดภัย?",
  ui_story_5017_50170802_64_dialog_content = "เกิดอะไรขึ้นรึ?",
  ui_story_5017_50170802_65_dialog_content = "เราเจอกับพวกภูตผีในโคฟุโจน่ะ...",
  ui_story_5017_50170802_66_dialog_content = "พวกมันบุกมามากมาย",
  ui_story_5017_50170802_67_dialog_content = "เป็นไปได้ยังไงกัน?",
  ui_story_5017_50170802_68_dialog_content = "ฉันกำลังไปที่ปราสาทหลัก เพื่อที่จะได้...",
  ui_story_5017_50170802_69_dialog_content = "ช่างเถอะ พวกคุณรู้แค่นี้ก็พอ",
  ui_story_5017_50170802_70_dialog_content = "...",
  ui_story_5017_50170802_71_dialog_content = "รับทราบ ท่านมิโกะ",
  ui_story_5017_50170802_72_dialog_content = "เราจะอารักขาท่านไปที่ปราสาทหลักเอง",
  ui_story_5017_50170802_73_dialog_content = "ท่านอาเมะโมริ! ทางนี้!",
  ui_story_5017_50170802_74_dialog_content = "ท่านบาดเจ็บนี่นา...",
  ui_story_5017_50170802_75_dialog_content = "ไม่ใช่เรื่องหนักหนาอะไรหรอก",
  ui_story_5017_50170802_76_dialog_content = "เมื่อกี้เราเห็นซามูไรด้วย",
  ui_story_5017_50170802_77_dialog_content = "แผนสังหารมิโกะของท่าน...",
  ui_story_5017_50170802_78_dialog_content = "ฉันทำพลาด มิโกะยังไม่ตาย",
  ui_story_5017_50170802_79_dialog_content = "ไม่เป็นไรหรอก ท่านอาเมะโมริ",
  ui_story_5017_50170802_80_dialog_content = "อย่าคิดมากเรื่องมิโกะเลย ความปลอดภัยของท่านเป็นสิ่งสำคัญที่สุด",
  ui_story_5017_50170802_81_dialog_content = "ฉันลองมาคิดดูแล้ว คุณพูดถูกจริง ๆ",
  ui_story_5017_50170802_82_dialog_content = "เรื่องอะไรเหรอ?",
  ui_story_5017_50170802_83_dialog_content = "การตายของมิโกะอาจจะไม่ทำให้ทุกอย่างจบลง",
  ui_story_5017_50170802_84_dialog_content = "เธอ... ค่อนข้างแตกต่างจากที่ฉันคิดไว้พอดู",
  ui_story_5017_50170802_85_dialog_content = "เรื่องนี้มันซับซ้อนกว่าที่ฉันเข้าใจมาก ๆ",
  ui_story_5017_50170802_86_dialog_content = "ท่านอาเมะโมริ...",
  ui_story_5017_50170802_87_dialog_content = "แต่วันนี้ฉันก็ได้รู้เรื่องสำคัญมาอย่างนึง",
  ui_story_5017_50170802_88_dialog_content = "เมื่อเทียบกับการฆ่ามิโกะนั่น สิ่งนี้สำคัญกว่านั้นมาก",
  ui_story_5017_50170802_89_dialog_content = "สำคัญกว่านั้น?",
  ui_story_5017_50170802_90_dialog_content = "ฉันเจอ<color=#FFB400>หยกชิโนะกิ</color>แล้ว",
  ui_story_5017_50170802_91_dialog_content = "หยกชิโนะกิ?",
  ui_story_5017_50170802_92_dialog_content = "ที่ไหนเหรอ?",
  ui_story_5017_50170802_93_dialog_content = "มันอยู่กับเพื่อนเก่าของฉัน",
  ui_story_5017_50170802_94_dialog_content = "เกรงว่าเราคงต้องบอกลากันตรงนี้แล้ว",
  ui_story_5017_50170802_95_dialog_content = "ต้องขอโทษสำหรับทุกอย่างจริง ๆ เรื่องนี้คงทำให้แผนหยุดพักผ่อนที่โคฟุโจของพวกคุณพังไม่เป็นท่า",
  ui_story_5017_50170802_96_dialog_content = "แหม อย่าพูดแบบนั้นเลย... รินเนะไม่ได้ทำอะไรผิดสักหน่อย!",
  ui_story_5017_50170802_97_dialog_content = "หน้าที่ของมิโกะคือการรักษาสมดุลระหว่างหยินกับหยาง",
  ui_story_5017_50170802_98_dialog_content = "ดังนั้นวิกฤตการณ์ครั้งนี้ฉันเองก็มีส่วนผิด",
  ui_story_5017_50170802_99_dialog_content = "อา... รินเนะพูดจาเข้าใจยากอีกแล้ว",
  ui_story_5017_50170802_100_dialog_content = "แต่ไม่ต้องห่วงนะ พื้นที่รอบปราสาทหลักปลอดภัย ไปเดินเที่ยวชมเมืองเถอะ",
  ui_story_5017_50170802_101_dialog_content = "คายาโนะเองก็เป็นคนโคฟุโจ เธอพาพวกคุณเที่ยวได้นะ",
  ui_story_5017_50170802_102_dialog_content = "หา? ฉันเหรอคะ?",
  ui_story_5017_50170802_103_dialog_content = "ใช่ เธอทำได้ ช่วยฉันทีนะ!",
  ui_story_5017_50170802_104_dialog_content = "เธอรู้จักโคฟุโจดีกว่าฉันมาก ๆ อยู่แล้ว",
  ui_story_5017_50170802_105_dialog_content = "ในเมื่อท่านมิโกะพูดแบบนั้น...",
  ui_story_5017_50170802_106_dialog_content = "เราจะได้เจอกันอีกมั้ย?",
  ui_story_5017_50170802_107_dialog_content = "แน่นอน เหยา",
  ui_story_5017_50170802_108_dialog_content = "เมื่อเรื่องทุกอย่างจบลง ฉันจะรีบมาหานะ",
  ui_story_5017_50170802_109_dialog_content = "เราจะได้สนุกกับเทศกาลคาสึกะด้วยกัน",
  ui_story_5017_50170802_110_dialog_content = "เย่!",
  ui_story_5017_50170802_111_dialog_content = "ตกลง! เราจะไปเที่ยวเทศกาลคาสึกะด้วยกัน!",
  ui_story_5017_50170901_1_dialog_content = "<color=#e8d9bb>บนถนนในเมืองเขตปราสาทโคฟุโจ</color>",
  ui_story_5017_50170901_2_dialog_content = "(อา... ฉันพาแขกผู้มีเกียรติมาที่นี่โดยไม่คิด...)",
  ui_story_5017_50170901_3_dialog_content = "(ประหม่าจังเลย... ฉันจะทำให้ท่านมิโกะผิดหวังไม่ได้... แต่...)",
  ui_story_5017_50170901_4_dialog_content = "(ฉันจะแนะนำที่นี่ยังไงดีล่ะ?)",
  ui_story_5017_50170901_5_dialog_content = "<size=30>นี่คือซาคาอิ... เขตในบริเวณปราสาทโคฟุโจ...</size>",
  ui_story_5017_50170901_6_dialog_content = "<size=30>ที่แห่งนี้คึกคักและสวยงามมาก ๆ อีกทั้งยังมีการจัดงานเทศกาลบ่อยครั้ง รวมถึงเทศกาลคาสึกะ...</size>",
  ui_story_5017_50170901_7_dialog_content = "(ฉันไม่ได้ยินที่เธอพูดเลย!)",
  ui_story_5017_50170901_8_dialog_content = "แต่ที่นี่มีบรรยากาศเทศกาลมากกว่าแถบชานเมืองจริง ๆ นั่นแหละ",
  ui_story_5017_50170901_9_dialog_content = "ดอกซากุระบาน ถนนที่มีผู้คนจอแจ กลีบดอกไม้โปรยปรายบนพื้นราวกับหิมะ และทุกคนก็ยุ่งกับการเตรียมอาหารสำหรับเทศกาลคาสึกะ...",
  ui_story_5017_50170901_10_dialog_content = "หืมม? นี่มัน...",
  ui_story_5017_50170901_11_dialog_content = "กลิ่นหอมจัง!",
  ui_story_5017_50170901_12_dialog_content = "พร้อมกันอะไรขนาดนี้เนี่ย!",
  ui_story_5017_50170901_13_dialog_content = "(อา... กลิ่นนี่มัน...)",
  ui_story_5017_50170901_14_dialog_content = "เอาล่ะ ถ้าท้องว่างเราก็จะไม่มีแรงทำอะไรนะ!",
  ui_story_5017_50170901_15_dialog_content = "ขอฉันหาร้านแนะนำจากคู่มือเที่ยวเกาะเมฆาก่อนนะ...",
  ui_story_5017_50170901_16_dialog_content = "สะดวกจังเลยแฮะ!",
  ui_story_5017_50170901_17_dialog_content = "อืมม... อาหารรสเลิศราคาย่อมเยา รับรองโดยท่านโชกุน อร่อยเด็ดดวง! ร้านราเม็งคานิยะพร้อมให้บริการท่านแล้ว",
  ui_story_5017_50170901_18_dialog_content = "\"ราคารับรองโดยท่านโชกุน\"... แม้แต่โชกุนก็ต้องจ่ายค่าราเม็งด้วยนะเนี่ย",
  ui_story_5017_50170901_19_dialog_content = "แหะแหะ ฉันว่าคุณแบ่งประโยคผิดมากกว่านะ...",
  ui_story_5017_50170901_20_dialog_content = "ไหนดูซิ... อืมม <color=#FFB400>ร้านราเม็งคานิยะ</color>เหรอ?",
  ui_story_5017_50170901_21_dialog_content = "(อ๊ะ... พวกเขาพูดชื่อร้านซะแล้ว...)",
  ui_story_5017_50170901_22_dialog_content = "<size=45>ราเม็งคานิยะ...</size>",
  ui_story_5017_50170901_23_dialog_content = "ร้านราเม็งอันดับ 1 ในใจคุณ!",
  ui_story_5017_50170901_24_dialog_content = "สวัสดี!",
  ui_story_5017_50170901_25_dialog_content = "กำลังหิวอยู่ใช่มั้ย?",
  ui_story_5017_50170901_26_dialog_content = "ยินดีต้อนรับสู่<color=#FFB400>ร้านราเม็งคานิยะ</color>ของโมโมะกับอันสึ!",
  ui_story_5017_50170901_27_dialog_content = "อาหารรสเลิศราคาย่อมเยา!",
  ui_story_5017_50170901_28_dialog_content = "รับรองโดยท่านโชกุน อร่อยเด็ดดวง!",
  ui_story_5017_50170901_29_dialog_content = "ราเม็งคานิยะ พร้อมให้บริการแล้ว!",
  ui_story_5017_50170901_30_dialog_content = "เหมือนโฆษณาในคู่มือเปี๊ยบ!",
  ui_story_5017_50170901_31_dialog_content = "ชิมสักคำแล้วคุณจะติดใจ!",
  ui_story_5017_50170901_32_dialog_content = "ว่าแล้วเชียว ถ้าพูดชื่อร้านแล้วโมโมะกับอันสึจะปรากฏตัวทันที...",
  ui_story_5017_50170901_33_dialog_content = "อ้าว? เด็กทำงานพิเศษของเรานี่นา!",
  ui_story_5017_50170901_34_dialog_content = "เด็กทำงานพิเศษก็มาด้วยงั้นเหรอ!",
  ui_story_5017_50170901_35_dialog_content = "เด็กทำงานพิเศษ?",
  ui_story_5017_50170901_36_dialog_content = "ใช่ค่ะ โมโมะกับอันสึเมตตาดูแลฉัน...",
  ui_story_5017_50170901_37_dialog_content = "ทำให้ฉันมีงานทำที่โคฟุโจ...",
  ui_story_5017_50170901_38_dialog_content = "ถึงเด็กทำงานพิเศษจะไม่มาทำงานพักใหญ่แล้ว แต่ก็ยังพาลูกค้ามาให้เรา!",
  ui_story_5017_50170901_39_dialog_content = "ในเมื่อทำงานหนักขนาดนี้ เราจะหักเงินเดือนแค่ครึ่งเดียวก็แล้วกัน!",
  ui_story_5017_50170901_40_dialog_content = "เชิญค่ะ คุณลูกค้า!",
  ui_story_5017_50170901_41_dialog_content = "เป็นเจ้าของร้านที่กระตือรือร้นสุด ๆ เลย",
  ui_story_5017_50170901_42_dialog_content = "<color=#e8d9bb>ใกล้กับร้านราเม็งคานิยะในเมืองเขตปราสาทโคฟุโจ</color>",
  ui_story_5017_50170901_43_dialog_content = "มาแล้ว ราเม็งคานิยะสูตรเด็ดของร้านร้อน ๆ เลยค่ะ...",
  ui_story_5017_50170901_44_dialog_content = "ว้าว! กลิ่นหอมน่ากินสุด ๆ!",
  ui_story_5017_50170901_45_dialog_content = "ถ้า<color=#FFB400>พี่สาวร่วมสาบาน</color>ของฉันได้มากินของอร่อยแบบนี้ด้วยกันก็คงจะดี...",
  ui_story_5017_50170901_46_dialog_content = "คุณมีพี่สาวด้วยเหรอ?",
  ui_story_5017_50170901_47_dialog_content = "นึกว่าคุณจะจำอะไรไม่ได้ซะอีก",
  ui_story_5017_50170901_48_dialog_content = "ฉันหมายถึงพี่สาวร่วมสาบานจากกิลด์หลินน่ะ!",
  ui_story_5017_50170901_49_dialog_content = "เธอไม่ใช่ผู้หญิงธรรมดานะ!",
  ui_story_5017_50170901_50_dialog_content = "เธอเก่งที่สุดในตระกูลหลิน... ไม่สิ ฉันว่าไม่มีใครในอัมบราตันสู้เธอได้",
  ui_story_5017_50170901_51_dialog_content = "นี่ไม่ได้โม้นะ แม้แต่อีสต์-อะแฮ่ม-วาน พี่สาวของฉันก็น่ามีโอกาสสัก 80% ล่ะ!",
  ui_story_5017_50170901_52_dialog_content = "กระแอมแบบนั้นผมก็ยังรู้อยู่ดีนะว่าคุณหมายถึงใคร!",
  ui_story_5017_50170901_53_dialog_content = "ฮึ่ม! เอาเป็นว่าพี่สาวของฉันเป็นคนที่เยี่ยมมาก ๆ ก็แล้วกัน! สิ่งเดียวในโลกที่เธอกลัว...",
  ui_story_5017_50170901_54_dialog_content = "ก็คือพริก!",
  ui_story_5017_50170901_55_dialog_content = "หา?",
  ui_story_5017_50170901_56_dialog_content = "พี่สาวของฉันเคยกินราเม็งอเวจี เมนูเด็ดของร้านร้านนึงในอัมบราตัน...",
  ui_story_5017_50170901_57_dialog_content = "เธอต่อยปากตัวเองเกินร้อยทีได้มั้ง เรื่องนั้นเป็นตำนานเลยล่ะ",
  ui_story_5017_50170901_58_dialog_content = "... กินน้ำแก้เผ็ดแทนไม่ได้เรอะ?",
  ui_story_5017_50170901_59_dialog_content = "ถ้าพี่สาวของฉันได้มาลิ้มรสราเม็งที่ลวกอย่างพอเหมาะและมีน้ำซุปเข้มข้นแบบนี้...",
  ui_story_5017_50170901_60_dialog_content = "เธอจะต้องตกหลุมรักแน่ ๆ!",
  ui_story_5017_50170901_61_dialog_content = "แหะแหะ... สูตรของเราเป็นความลับสุดยอด ถ้าอยากลองราเม็งคุณก็ต้องพาพี่สาวมาเที่ยวเกาะเมฆานะ",
  ui_story_5017_50170901_62_dialog_content = "แม้แต่โชกุนก็ชอบราเม็งของเรา!",
  ui_story_5017_50170901_63_dialog_content = "อา ดูท่าทางโชกุนก็เป็นคนใจดีแล้วก็เป็นมิตรเหมือนกันนะ",
  ui_story_5017_50170901_64_dialog_content = "... หวังว่ารินเนะจะขอใช้กระจกเมฆาได้โดยไม่มีปัญหานะ",
  ui_story_5017_50170901_65_dialog_content = "โชกุนน่ะเหรอ? ฮะฮะฮะ... คุณคงเป็นคนต่างแดนสินะ",
  ui_story_5017_50170901_66_dialog_content = "ตลอดเวลาสิบปีที่ผ่านมา โชกุนเป็นสัญลักษณ์ของอำนาจเด็ดขาดที่ปกครองเกาะเมฆาแห่งนี้",
  ui_story_5017_50170901_67_dialog_content = "(สิบปี... นี่มันเกี่ยวกับการสูญเสียความทรงจำของเหยารึเปล่านะ?)",
  ui_story_5017_50170901_68_dialog_content = "ช่วยเล่าประวัติศาสตร์ของเกาะเมฆาให้ฟังทีสิ!",
  ui_story_5017_50170901_69_dialog_content = "โอ้? แต่ว่านะ ราเม็งของคุณจะหมดแล้วน่ะสิ...",
  ui_story_5017_50170901_70_dialog_content = "ทำให้เขาอีกชามสิ!",
  ui_story_5017_50170901_71_dialog_content = "(ขอบคุณครับ!)",
  ui_story_5017_50170901_72_dialog_content = "ไม่มีปัญหา เป็นลูกค้าที่ร่าเริงดีจริงนะ!",
  ui_story_5017_50170901_73_dialog_content = "*อะแฮ่ม*... ตอนแรกเกาะเมฆาไม่ได้สงบสุขแบบนี้หรอก",
  ui_story_5017_50170901_74_dialog_content = "พลังของหยินกับหยางไหลเวียนทั่วดินแดนนี้ ภาพภูตผีออกอาละวาดเป็นเรื่องที่เห็นได้จนชินตา...",
  ui_story_5017_50170901_75_dialog_content = "นอกจากนี้ เกาะต่าง ๆ รอบเกาะเมฆาก็ทำสงครามสู้รบกันตลอดเวลา",
  ui_story_5017_50170901_76_dialog_content = "จนกระทั่งเกาะหลักได้ส่งโชกุนมาที่นี่เพื่อสร้างเมืองโคฟุโจ...",
  ui_story_5017_50170901_77_dialog_content = "ภายใต้การปกครองที่ดุดันและเด็ดขาด ในที่สุดชาวเกาะเมฆาก็มีช่วงเวลาแห่งความมั่งคั่งและสงบสุขอันยาวนาน",
  ui_story_5017_50170901_78_dialog_content = "การปกครองด้วยโชกุนเป็นประเพณีที่สืบทอดกันจากรุ่นสู่รุ่น และโชกุนคนปัจจุบันก็มีชื่อว่า<color=#FFB400>ฟูจิคุโมะ</color>",
  ui_story_5017_50170901_79_dialog_content = "หากต้องการติดตามตอนต่อไป...",
  ui_story_5017_50170901_80_dialog_content = "ขออีกชาม!",
  ui_story_5017_50170901_81_dialog_content = "(กินเยอะจังแฮะ!)",
  ui_story_5017_50170901_82_dialog_content = "ได้เลย! อะแฮ่ม... การปกครองอันโหดเหี้ยมของฟูจิคุโมะทำให้เกาะเมฆาปลอดภัย...",
  ui_story_5017_50170901_83_dialog_content = "แต่แม่ทัพหญิงคนหนึ่งซึ่งเป็นผู้นำแต่เดิมในท้องที่ และชนพื้นเมืองบางส่วน ก็ไม่ได้ยินดีกับเรื่องนี้ ความเกลียดชังจึงเริ่มก่อตัว...",
  ui_story_5017_50170901_84_dialog_content = "ในที่สุดแม่ทัพคนนั้นก็ก่อกบฏร่วมกับลูกศิษย์และผู้สนับสนุน แต่ว่า...",
  ui_story_5017_50170901_85_dialog_content = "ขออีกชาม!",
  ui_story_5017_50170901_86_dialog_content = "(เธอกินเก่งขนาดนี้เลยเหรอเนี่ย!)",
  ui_story_5017_50170901_87_dialog_content = "ทานให้อร่อยนะ! แต่ว่า... เธอก็ถูกฟูจิคุโมะปราบและคุมขังที่แดนผนึกซึ่งอยู่ในปราสาทหลัก",
  ui_story_5017_50170901_88_dialog_content = "ฉันรู้มาว่าผู้ติดตามบางส่วนก็ยังแอบดำเนินแผนการต่อต้านอย่างลับ ๆ ในเงามืด",
  ui_story_5017_50170901_89_dialog_content = "เธอช่างน่าสงสารจริง ๆ... ว่ากันว่าฟูจิโมโตะเป็นนักรบผู้ไร้พ่าย เขามีหัวใจที่แกร่งดั่งหินผา เย็นยะเยือกราวกับน้ำแข็ง",
  ui_story_5017_50170901_90_dialog_content = "ยังไงพวกกบฏก็คงไม่มีทางต่อกรกับโชกุนได้",
  ui_story_5017_50170901_91_dialog_content = "แต่ถึงอย่างนั้น ร้านราเม็งคานิยะไม่มีวันปฏิเสธลูกค้าหรอกนะ",
  ui_story_5017_50170901_92_dialog_content = "ไม่ว่าจะเป็นคนต่างแดนอย่างคุณหรือกบฏในท้องที่ก็สามารถเพลิดเพลินกับราเม็งของเราได้ แม้แต่ผีเราก็ยินดีต้อนรับ!",
  ui_story_5017_50170901_93_dialog_content = "ขออีกชาม!",
  ui_story_5017_50170901_94_dialog_content = "ได้เลยคุณลูกค้า คุณเจริญอาหารจังเลยนะเนี่ย!",
  ui_story_5017_50170901_95_dialog_content = "แต่เราไม่มีเรื่องเล่าแล้วล่ะ",
  ui_story_5017_50170901_96_dialog_content = "เจ้าเล่ห์ชะมัด!",
  ui_story_5017_50170901_97_dialog_content = "ขอคิดเงินก่อนนะ... ราเม็งหนึ่ง สอง สาม... เจ็ดชาม รวมกันก็...",
  ui_story_5017_50170901_98_dialog_content = "คิดเลขทำไมน่ะ? ฉันจ่ายให้แล้ว",
  ui_story_5017_50170901_99_dialog_content = "หา?",
  ui_story_5017_50170901_100_dialog_content = "ไม่เป็นน่า ยังไงฉันก็เอาแต่กินตั้งแต่เช้ายันเย็น ให้ฉันเลี้ยงเถอะ!",
  ui_story_5017_50170901_101_dialog_content = "อ๊ะ... จะมืดแล้วเหรอเนี่ย?",
  ui_story_5017_50170901_102_dialog_content = "เด็กทำงานพิเศษ รีบกลับบ้านเถอะ",
  ui_story_5017_50170901_103_dialog_content = "ก่อนที่<color=#FFB400>เจ้าพวกนั้น</color>จะเล่นงานเธออีก",
  ui_story_5017_50170901_104_dialog_content = "ค่ะ... ขอตัวนะคะ ขอบคุณมาก... แล้วเจอกันตอนเช้าค่ะ...",
  ui_story_5017_50170901_105_dialog_content = "เจ้าพวกนั้น? หมายถึงวิญญาณที่คายาโนะพูดถึงก่อนหน้านี้เหรอ?",
  ui_story_5017_50170901_106_dialog_content = "PlayerName คุณเหยา เราเดินไปส่งคายาโนะกันเถอะ",
  ui_story_5017_50170901_107_dialog_content = "ไม่มีปัญหา",
  ui_story_5017_50170901_108_dialog_content = "อื้มม! นี่เป็นหน้าที่ของจอมยุทธ์อยู่แล้ว!",
  ui_story_5017_50170901_109_dialog_content = "ขอบคุณสำหรับอาหารอร่อย ๆ นะ!",
  ui_story_5017_50170901_110_dialog_content = "แล้วมาอีกนะ",
  ui_story_5017_50170901_111_dialog_content = "<color=#e8d9bb>บนถนนในเมืองเขตปราสาทโคฟุโจ</color>",
  ui_story_5017_50170901_112_dialog_content = "อา... ขอโทษที่ทำให้ลำบากนะ...",
  ui_story_5017_50170901_113_dialog_content = "บ้านของฉันอยู่บนถนนสายนี้ ส่งตรงนี้ก็พอแล้วค่ะ...",
  ui_story_5017_50170901_114_dialog_content = "<color=#e8d9bb>ฟิ้ว ฟิ้ว...</color>",
  ui_story_5017_50170901_115_dialog_content = "หืม...",
  ui_story_5017_50170901_116_dialog_content = "คายาโนะ เธอหนาวเหรอ?",
  ui_story_5017_50170901_117_dialog_content = "ผมว่าเธอไม่ได้หนาวหรอกครับ เธอกำลังประหม่า",
  ui_story_5017_50170901_118_dialog_content = "ประหม่าเหรอ ทำไมอย่างนั้นล่ะ?",
  ui_story_5017_50170901_119_dialog_content = "<color=#e8d9bb>ฟิ้ว—</color>",
  ui_story_5017_50170901_120_dialog_content = "หา?",
  ui_story_5017_50170901_121_dialog_content = "นั่นอะไรน่ะ?",
  ui_story_5017_50170901_122_dialog_content = "แม้แต่ไวซ์ก็อินกับบรรยากาศไปด้วย...",
  ui_story_5017_50170901_123_dialog_content = "คายาโนะ นี่คือสิ่งที่เจ้าของร้านราเม็งพูดถึงใช่มั้ย?",
  ui_story_5017_50170901_124_dialog_content = "ค่ะ... น่าอายจัง...",
  ui_story_5017_50170901_125_dialog_content = "ฉันสัมผัสได้ว่ามีวิญญาณโชคร้ายที่ยังไม่กลายร่างกำลังเข้ามาใกล้พวกเรา",
  ui_story_5017_50170901_126_dialog_content = "หวา!",
  ui_story_5017_50170901_127_dialog_content = "คายาโนะ! เธอหมายถึงตอนนี้เลยน่ะเหรอ? พวกนั้นกลับมาอีกแล้วเหรอ?",
  ui_story_5017_50170901_128_dialog_content = "อา... คุณไวซ์ ไม่ต้องห่วง พวกเขาไม่ได้อยู่รอบตัวคุณ",
  ui_story_5017_50170901_129_dialog_content = "ใช่แล้ว วางใจได้ ไวซ์",
  ui_story_5017_50170901_130_dialog_content = "จากคู่มือเที่ยวเกาะเมฆา อันตรายจะปรากฏตัวยามค่ำคืน!",
  ui_story_5017_50170901_131_dialog_content = "หา?",
  ui_story_5017_50170901_132_dialog_content = "โอ๊ะ โทษที! ฉันอ่านผิด จริง ๆ ต้อง \"พื้นที่เขตเมืองด้านในปลอดภัยเป็นอย่างมาก!\"",
  ui_story_5017_50170901_133_dialog_content = "เราอยู่ใจกลางโคฟุโจ เพราะงั้นไม่ต้องกังวลหรอก",
  ui_story_5017_50170901_134_dialog_content = "ถูกต้อง... ขอบคุณมากเลยนะคะที่เดินมาส่ง... แล้วเจอกันค่ะ...",
  ui_story_5017_50170901_135_dialog_content = "ว่าแต่...",
  ui_story_5017_50170901_136_dialog_content = "ผีที่อยู่ใกล้กับ PlayerName... พวกคุณทุกคนเห็นใช่มั้ย?",
  ui_story_5017_50170901_137_dialog_content = "หา?",
  ui_story_5017_50170901_138_dialog_content = "อู!",
  ui_story_5017_50170901_139_dialog_content = "กรร!",
  ui_story_5017_50170901_140_dialog_content = "พระช่วย!",
  ui_story_5017_50170901_141_dialog_content = "ว้าว! ได้เวลาฉันออกโรงอีกแล้ว",
  ui_story_5017_50170901_142_dialog_content = "เข้ามา! หมัดของฉันพร้อมแล้ว!",
  ui_story_5017_50170902_1_dialog_content = "ย้ากก!",
  ui_story_5017_50170902_2_dialog_content = "อู!",
  ui_story_5017_50170902_3_dialog_content = "อู!",
  ui_story_5017_50170902_4_dialog_content = "อู!",
  ui_story_5017_50170902_5_dialog_content = "นึกว่าในเมืองจะปลอดภัยซะอีก!",
  ui_story_5017_50170902_6_dialog_content = "ทำไมถึงมีผีเยอะขนาดนี้ล่ะเนี่ย?",
  ui_story_5017_50170902_7_dialog_content = "ขอโทษค่ะ! ปกติแล้วฉันจะควบคุมวิญญาณที่อยู่รอบตัวได้...",
  ui_story_5017_50170902_8_dialog_content = "อืมม... ฉันจะต้องสงบใจ... สงบใจให้ได้...",
  ui_story_5017_50170902_9_dialog_content = "ไม่... ฉันทำไม่ได้... ขอโทษจริง ๆ นะคะ...",
  ui_story_5017_50170902_10_dialog_content = "ฉันควรอยู่ให้ห่างพวกคุณจะดีกว่า...",
  ui_story_5017_50170902_11_dialog_content = "ไม่ใช่ ผีพวกนี้ไม่ได้มาเพราะคายาโนะ",
  ui_story_5017_50170902_12_dialog_content = "มีบางอย่างควบคุมการเคลื่อนไหวของพวกมันอยู่...",
  ui_story_5017_50170902_13_dialog_content = "PlayerName! มัวรออะไรอยู่?",
  ui_story_5017_50170902_14_dialog_content = "หนอยย!",
  ui_story_5017_50170902_15_dialog_content = "อาาา...!!!",
  ui_story_5017_50170902_16_dialog_content = "<color=#e8d9bb>ฉัวะ! ฉับ!</color>",
  ui_story_5017_50170902_17_dialog_content = "อ๊ะ!",
  ui_story_5017_50170902_18_dialog_content = "อัก...",
  ui_story_5017_50170902_19_dialog_content = "ฟู่...",
  ui_story_5017_50170902_20_dialog_content = "นายท่าน ถ้าคิดมากเกินไปจะทำให้คุณเป็นอันตรายนะ",
  ui_story_5017_50170902_21_dialog_content = "ขอบคุณนะ!",
  ui_story_5017_50170902_22_dialog_content = "อาเมะโมริ? มาตั้งแต่เมื่อไหร่เนี่ย?",
  ui_story_5017_50170902_23_dialog_content = "เธอหนีซามูไรพวกนั้นมาได้แล้วเหรอ?",
  ui_story_5017_50170902_24_dialog_content = "พวกกระจอกนั่นก็เป็นได้แค่หินลับคมดาบของฉันเท่านั้น",
  ui_story_5017_50170902_25_dialog_content = "... เธอจะจ้องดาบฉันทำไม?",
  ui_story_5017_50170902_26_dialog_content = "ฉันอยากจะถามเธอมานานแล้ว...",
  ui_story_5017_50170902_27_dialog_content = "ฉันคิดว่าฉันเคยเห็นดาบของเธอมาก่อน เรารู้จักกันได้ยังไงเหรอ?",
  ui_story_5017_50170902_28_dialog_content = "... นี่ไม่ใช่คำถามที่ฉันมีสิทธิ์ตอบ",
  ui_story_5017_50170902_29_dialog_content = "ฉันไม่ได้ต้องการจะรู้จักกับเธอเลย",
  ui_story_5017_50170902_30_dialog_content = "พอเถอะ",
  ui_story_5017_50170902_31_dialog_content = "เรามีหยกที่หน้าตาเหมือนกัน แค่นั้นมันก็บอกทุกอย่างแล้วไม่ใช่เหรอ?",
  ui_story_5017_50170902_32_dialog_content = "ยกเว้นว่ามันจะเป็นของราคาถูกที่วางขายอยู่ทั่วซาคาอิน่ะนะ!",
  ui_story_5017_50170902_33_dialog_content = "เธอได้หยกนั่นมาจากไหน?",
  ui_story_5017_50170902_34_dialog_content = "แล้วเธอเรียนวิชาดาบมาจากใคร?",
  ui_story_5017_50170902_35_dialog_content = "เธอรู้ชื่อฉันได้ยังไงตอนที่เราเจอกันครั้งแรก?",
  ui_story_5017_50170902_36_dialog_content = "... หยก?",
  ui_story_5017_50170902_37_dialog_content = "ถ้าท่านอาจารย์รู้ว่าเธอเรียก<color=#FFB400>ฮาราอิชิโนะกิ</color>อันแสนล้ำค่านั้นว่าหยกธรรมดาละก็...",
  ui_story_5017_50170902_38_dialog_content = "เธอคงเสียใจที่ได้มอบหยกชิโนะกิให้กับเธอ",
  ui_story_5017_50170902_39_dialog_content = "?",
  ui_story_5017_50170902_40_dialog_content = "<color=#FFB400>อาจารย์</color>?",
  ui_story_5017_50170902_41_dialog_content = "...",
  ui_story_5017_50170902_42_dialog_content = "เธอจำอะไรไม่ได้เลยจริง ๆ สินะ...",
  ui_story_5017_50170902_43_dialog_content = "เราคงต้องคุยกันหน่อยแล้ว",
  ui_story_5017_50171001_1_dialog_content = "ฉันจำได้แค่นิดเดียว",
  ui_story_5017_50171001_2_dialog_content = "มีทะเลกว้างใหญ่ไพศาล ฉันได้ยินเสียงกระดิ่ง แล้วก็หยกชิ้นนี้",
  ui_story_5017_50171001_3_dialog_content = "ฉันพกมันติดตัวตั้งแต่จำความได้",
  ui_story_5017_50171001_4_dialog_content = "ทุกครั้งที่ถือมันไว้... ฉันจะสัมผัสได้ถึงพลังงานอันอบอุ่นที่ไม่ได้เป็นของฉัน",
  ui_story_5017_50171001_5_dialog_content = "PlayerName มั่นใจว่าหยกชิ้นนี้เป็นของสำคัญจากใครบางคน",
  ui_story_5017_50171001_6_dialog_content = "นั่นเป็นการตั้งสมมุติฐานจากเหตุผลเฉย ๆ น่ะ...",
