  ui_story_5017_50171001_9_dialog_content = "เข้าใจแล้ว",
  ui_story_5017_50171001_10_dialog_content = "บางทีลืมอดีตไปมันก็ไม่ใช่เรื่องแย่หรอก",
  ui_story_5017_50171001_11_dialog_content = "ฉันว่าเธอโชคดีด้วยซ้ำ",
  ui_story_5017_50171001_12_dialog_content = "(ให้ตายสิ! ยัยนี่ทำตัวน่าหงุดหงิดชะมัด!)",
  ui_story_5017_50171001_13_dialog_content = "... ช่วยบอกฉันมาตรง ๆ เถอะ ฉันอยากรู้อะไรก็ได้ที่เกี่ยวกับตัวเองแล้วก็อาจารย์!",
  ui_story_5017_50171001_14_dialog_content = "ฉันจะขอบคุณเป็นอย่างมาก!",
  ui_story_5017_50171001_15_dialog_content = "<color=#e8d9bb>กรึบ... กรึบ...</color>",
  ui_story_5017_50171001_16_dialog_content = "นั่นมัน... เสียงหักข้อนิ้วงั้นเหรอ?",
  ui_story_5017_50171001_17_dialog_content = "(นี่มันขู่กันชัด ๆ!)",
  ui_story_5017_50171001_18_dialog_content = "... เธอยังใจร้อนไม่เปลี่ยนเลย",
  ui_story_5017_50171001_19_dialog_content = "ฉันขอสาบานด้วยเกียรติของฉัน...",
  ui_story_5017_50171001_20_dialog_content = "ว่าหยกคู่นี้ \"ฮาราอิ\" กับ \"ชิโนะกิ\" เป็นสิ่งแทนคำสัญญาจากอาจารย์",
  ui_story_5017_50171001_21_dialog_content = "ถึงเธอจะจำอะไรไม่ได้ และไม่มีใครให้ความช่วยเหลือ...",
  ui_story_5017_50171001_22_dialog_content = "แต่หยกชิโนะกิก็จะพาเธอกลับมาที่เกาะเมฆาในที่สุด",
  ui_story_5017_50171001_23_dialog_content = "มีเพียงศิษย์อาจารย์เท่านั้นที่มีสายสัมพันธ์พิเศษเช่นนี้ต่อกัน",
  ui_story_5017_50171001_24_dialog_content = "... จริงด้วย ฉันสัมผัสได้ถึงพลังอันพิเศษบางอย่าง",
  ui_story_5017_50171001_25_dialog_content = "อาจารย์เป็นคนที่มีพรสวรรค์มาก ๆ เธอถ่ายทอดวิชานินจากับวิชาลมปราณให้เรา",
  ui_story_5017_50171001_26_dialog_content = "อ๊ะ! จำได้แล้ว! ไม่แปลกเลยที่ท่าดาบของเธอจะดูคุ้น ๆ",
