  ui_story_5017_50171001_28_dialog_content = "... ไม่เลย สมัยนั้นเธอยังไม่ได้เรื่อง ก็แค่มีดีพอที่จะทำให้ท่านอาจารย์ไม่ต้องขายหน้า",
  ui_story_5017_50171001_29_dialog_content = "แต่ไม่นึกเลยว่าหลังจากเธอไปจากเกาะเมฆา ฝีมือของเธอจะพัฒนาขึ้นขนาดนี้",
  ui_story_5017_50171001_30_dialog_content = "อ้อ... คือว่า เธอเป็นศิษย์น้องของฉันน่ะ",
  ui_story_5017_50171001_31_dialog_content = "ศิษย์น้อง?!",
  ui_story_5017_50171001_32_dialog_content = "ดูสารรูปตัวเองก่อนเถอะว่าขี้โรคแค่ไหน! ร่างกายไม่มีกล้ามเนื้อแม้แต่นิดเดียว...",
  ui_story_5017_50171001_33_dialog_content = "แล้วจะบอกว่าเป็นศิษย์พี่ของฉันได้ไง?",
  ui_story_5017_50171001_34_dialog_content = "การมีร่างกายที่เบาและคล่องตัวนั้นเป็นพื้นฐานของวิชานินจา",
  ui_story_5017_50171001_35_dialog_content = "อย่าดูถูกวิถีแห่งนินจาของฉันจะดีกว่า",
  ui_story_5017_50171001_36_dialog_content = "ฉันเองก็ไม่อยากจะยอมรับเหมือนกันว่ามาจากสำนักเดียวกับคนอย่างเธอ",
  ui_story_5017_50171001_37_dialog_content = "ฉันมันเป็นคนแบบไหนเรอะ? บอกมานะ ไม่งั้นฉันจะแสดงให้ดูว่าตอนนี้หมัดฉันหนักแค่ไหนแล้ว!",
  ui_story_5017_50171001_38_dialog_content = "ใจเย็นก่อนนะ",
