  ui_story_5017_50171001_40_dialog_content = "ฉันมั่นใจว่าเธอจะต้องดีใจแน่ถ้าได้เจอเหยา",
  ui_story_5017_50171001_41_dialog_content = "...",
  ui_story_5017_50171001_42_dialog_content = "ท่านอาจารย์...",
