  ui_story_5017_50171001_45_dialog_content = "แสดงว่าอาจารย์ของเธอก็คืออดีตผู้นำของเกาะเมฆาสินะ?",
  ui_story_5017_50171001_46_dialog_content = "อาจารย์ของฉันเก่งขนาดนั้นเลยเหรอ?",
