  ui_story_5017_50171101_13_dialog_content = "เธอรู้ทางหรือไง?",
  ui_story_5017_50171101_14_dialog_content = "...",
  ui_story_5017_50171101_15_dialog_content = "ก่อนเข้าปราสาทหลัก ให้เดินตามถนนเส้นหลักของซาคาอิ",
  ui_story_5017_50171101_16_dialog_content = "เอาล่ะ เตรียมตัว",
  ui_story_5017_50171101_17_dialog_content = "... อาเมะโมริ?",
  ui_story_5017_50171101_18_dialog_content = "...",
  ui_story_5017_50171101_19_dialog_content = "ช่วยเล่าเรื่องของอาจารย์พวกเราคร่าว ๆ ได้มั้ย?",
  ui_story_5017_50171101_20_dialog_content = "ฉันจำหน้าเธอไม่ได้",
  ui_story_5017_50171101_21_dialog_content = "อาจารย์เป็นคนยังไง?",
  ui_story_5017_50171101_22_dialog_content = "นอกจากเธอจะเป็น<color=#FFB400>ผู้นำท้องถิ่น</color> เธออาจจะคุ้นกับสมญานามของเธอ",
  ui_story_5017_50171101_23_dialog_content = "แทบจะไม่มีใครเรียกเธอด้วยชื่อจริง ชาวเกาะเมฆามักจะเรียกเธอว่าดาบแห่ง...",
  ui_story_5017_50171101_24_dialog_content = "อุ๊บบ?",
  ui_story_5017_50171101_25_dialog_content = "เธอมาปิดปากฉันทำไมเนี่ย?",
  ui_story_5017_50171101_26_dialog_content = "ชู่ว! ฉันเข้าใจแล้ว!",
  ui_story_5017_50171101_27_dialog_content = "เกาะนี้มีกฎว่าห้ามพูดชื่อนั่นในที่สาธารณะ",
  ui_story_5017_50171101_28_dialog_content = "เจ้าของภัตตาคารเคยเตือนฉันแล้ว ฉันเข้าใจดี!",
  ui_story_5017_50171101_29_dialog_content = "แต่ตอนนี้ไม่มีคนอื่นอยู่ด้วยนี่นา!",
  ui_story_5017_50171101_30_dialog_content = "... ห้ามพูดถึงงั้นรึ?",
  ui_story_5017_50171101_31_dialog_content = "ฮึ่ม! ฟูจิคุโมะกลัวท่านอาจารย์ขนาดนี้เลยสินะ",
  ui_story_5017_50171101_32_dialog_content = "<color=#FFB400>ดาบแห่งยมโลก</color> ก็สมเป็นชื่อที่ทำให้โชกุนจากเกาะหลักต้องตัวสั่นด้วยความกลัว",
  ui_story_5017_50171101_33_dialog_content = "ในวันนั้น ฟูจิคุโมะนำทัพซามูไรไปบุกบ้านของอาจารย์...",
  ui_story_5017_50171101_34_dialog_content = "ท่านอาจารย์ต้องรับมือกับกองทัพศัตรูอันแข็งแกร่งด้วยตัวคนเดียว",
  ui_story_5017_50171101_35_dialog_content = "แล้วอาจารย์แพ้รึเปล่า?",
  ui_story_5017_50171101_36_dialog_content = "มันไม่ใช่การพ่ายแพ้!",
  ui_story_5017_50171101_37_dialog_content = "เธอก็แค่อยากหาสถานที่สงบเพื่อฝึกฝนต่อ!",
  ui_story_5017_50171101_38_dialog_content = "อย่าเชื่อเรื่องที่ฟูจิคุโมะแต่งขึ้นเพื่อยกย่องให้ตัวเองดูดีสิ...",
  ui_story_5017_50171101_39_dialog_content = "ชั่วช้าที่สุด...",
  ui_story_5017_50171101_40_dialog_content = "...",
  ui_story_5017_50171101_41_dialog_content = "อาเมะโมริ... เป็นอะไรไปน่ะ?",
  ui_story_5017_50171101_42_dialog_content = "อาเมะโมริ?",
  ui_story_5017_50171101_43_dialog_content = "อาเมะโมริไปไหนแล้วล่ะ?",
  ui_story_5017_50171101_44_dialog_content = "หือ?",
  ui_story_5017_50171101_45_dialog_content = "ทำไมอยู่ ๆ ก็วิ่งแจ้นไปแบบนั้นล่ะ?",
  ui_story_5017_50171101_46_dialog_content = "<color=#e8d9bb>ฉับ ฉัวะ...</color>",
  ui_story_5017_50171101_47_dialog_content = "ฉันได้ยินอะไรบางอย่าง!",
  ui_story_5017_50171101_48_dialog_content = "อะไรเหรอ?",
  ui_story_5017_50171101_49_dialog_content = "คราวนี้ฉันพร้อมแล้ว... จะอะไรก็เข้ามาเลย!",
  ui_story_5017_50171101_50_dialog_content = "ทาง 4 นาฬิกา!",
  ui_story_5017_50171101_51_dialog_content = "จงสำแดงพลัง...",
  ui_story_5017_50171101_X51_dialog_content = "เพลงหมัด...",
  ui_story_5017_50171101_52_dialog_content = "... ฉันเอง",
  ui_story_5017_50171101_53_dialog_content = "อย่ามา ๆ หาย ๆ เหมือนพวกผีสิ!",
  ui_story_5017_50171101_54_dialog_content = "ขอโทษนะ ฉันไปฟันไม้ไผ่มา...",
  ui_story_5017_50171101_55_dialog_content = "... ให้ตายสิ!",
  ui_story_5017_50171101_56_dialog_content = "เอิ่ม... อาเมะโมริ",
  ui_story_5017_50171101_57_dialog_content = "นึกว่าจะตัวอะไรออกมาซะอีก...",
  ui_story_5017_50171101_58_dialog_content = "<color=#e8d9bb>ฟิ้ว—</color>",
  ui_story_5017_50171101_59_dialog_content = "หือ?",
  ui_story_5017_50171101_60_dialog_content = "อู!",
  ui_story_5017_50171101_61_dialog_content = "อู!",
  ui_story_5017_50171101_62_dialog_content = "พวกมันมาแล้ว!",
  ui_story_5017_50171101_63_dialog_content = "ฉันจะเบนความสนใจพวกมันเอง",
  ui_story_5017_50171101_64_dialog_content = "PlayerName กับไวซ์ ระวังหลังให้ด้วย",
  ui_story_5017_50171101_65_dialog_content = "ส่วนเหยา เธอจัดการพวกมันซะ",
  ui_story_5017_50171101_66_dialog_content = "ฮึ่มม! ได้เลย!",
  ui_story_5017_50171201_1_dialog_content = "<color=#e8d9bb>ห้องนั่งเล่นของโชกุน วังฟุบุกิ ปราสาทหลักโคฟุโจ</color>",
  ui_story_5017_50171201_2_dialog_content = "...",
  ui_story_5017_50171201_3_dialog_content = "(เหลือแค่ห้องเดียวเท่านั้น...)",
  ui_story_5017_50171201_4_dialog_content = "(นี่จะเป็นครั้งแรกที่ฉันเข้าห้องท่านคุโบ)",
  ui_story_5017_50171201_5_dialog_content = "(ดูจากแผนผังห้องแล้ว... กระจกเมฆาน่าจะ...)",
  ui_story_5017_50171201_6_dialog_content = "อา...",
  ui_story_5017_50171201_7_dialog_content = "(เจอแล้ว!)",
  ui_story_5017_50171201_8_dialog_content = "(ท่านคุโบช่างเลินเล่อจริง ๆ! ใส่ไว้ตรงหน้าอกของชุดฮิโตเอะเหรอเนี่ย...)",
  ui_story_5017_50171201_9_dialog_content = "(นึกว่าเขาจะแอบไว้ในที่ลับตากว่านี้แล้วก็ปิดผนึกอย่างแน่นหนาซะอีก...)",
  ui_story_5017_50171201_10_dialog_content = "<color=#e8d9bb>แกร๊ง...</color>",
  ui_story_5017_50171201_11_dialog_content = "นั่นใครน่ะ?",
  ui_story_5017_50171201_12_dialog_content = "ใครบังอาจลอบเข้าห้องท่านโชกุนน่ะ?",
  ui_story_5017_50171201_13_dialog_content = "...",
  ui_story_5017_50171201_14_dialog_content = "... ท่านมิโกะ",
  ui_story_5017_50171201_15_dialog_content = "ความหวาดระแวงของคุณไม่ทำให้เกิดประโยชน์อะไรหรอกนะ",
  ui_story_5017_50171201_16_dialog_content = "ทำไมถึงเอามือจับดาบตลอดเวลาแบบนั้นล่ะ? คุณคิดว่าฉัน...",
  ui_story_5017_50171201_17_dialog_content = "เป็นอันตรายกับคุณงั้นรึ?",
  ui_story_5017_50171201_18_dialog_content = "ตอนนี้ท่านคุโบไม่อยู่ที่ปราสาท มีอะไรให้เราช่วยไหม ท่านมิโกะ?",
  ui_story_5017_50171201_19_dialog_content = "เทศกาลคาสึกะใกล้เข้ามาแล้ว แต่เหล่าผีกับปีศาจร้ายก็ยังออกอาละวาดไปทั่วเกาะเมฆา",
  ui_story_5017_50171201_20_dialog_content = "ฉันต้องการกระจกเมฆามากำจัดภูตผี ทำไมคุณถึงมาขวางฉันกันล่ะ?",
  ui_story_5017_50171201_21_dialog_content = "ท่านได้รับอนุญาตจากท่านคุโบหรือยัง?",
  ui_story_5017_50171201_22_dialog_content = "หากท่านคุโบไม่อนุญาต เราก็นำกระจกเมฆาออกมาไม่ได้",
  ui_story_5017_50171201_23_dialog_content = "ฉันจะนำกระจกเมฆาไปหาท่านคุโบเพื่อขออนุญาต",
  ui_story_5017_50171201_24_dialog_content = "ขอบคุณที่ตั้งใจปฏิบัติหน้าที่นะ ท่านซามูไร",
  ui_story_5017_50171201_25_dialog_content = "<color=#e8d9bb>ฟึบ!</color>",
  ui_story_5017_50171201_26_dialog_content = "?",
  ui_story_5017_50171201_27_dialog_content = "ไม่ว่าเหตุผลของท่านจะมีเหตุผลแค่ไหน...",
  ui_story_5017_50171201_28_dialog_content = "แต่หากท่านคุโบไม่อนุญาต เราก็ปล่อยท่านไปไม่ได้เด็ดขาด",
  ui_story_5017_50171201_29_dialog_content = "ท่านมิโกะ โปรดอย่าทำให้เราลำบากใจเลย",
  ui_story_5017_50171201_30_dialog_content = "คุณจะขวางฉันไว้แบบนี้จนกว่าท่านคุโบจะกลับมาอย่างนั้นรึ?",
  ui_story_5017_50171201_31_dialog_content = "เราจะเอาเทศกาลคาสึกะมาเสี่ยงแล้วก็ต้องรอให้เขาอนุญาตเนี่ยนะ?",
  ui_story_5017_50171201_32_dialog_content = "... ท่านนี่ช่างต่างจากมิโกะคนก่อน ๆ จริง ๆ",
  ui_story_5017_50171201_33_dialog_content = "ข้าเริ่มเข้าใจแล้ว ว่าทำไมชาวบ้านในเกาะเมฆาถึงปฏิบัติตัวกับท่านแบบนั้น",
  ui_story_5017_50171201_34_dialog_content = "...",
  ui_story_5017_50171201_35_dialog_content = "...",
  ui_story_5017_50171201_36_dialog_content = "หึหึ ท่านซามูไร คุณชอบส่องกระจกหรือเปล่า?",
  ui_story_5017_50171201_37_dialog_content = "... ท่านมิโกะ อย่าฝ่าฝืนคำสั่งของท่านคุโบเลย",
  ui_story_5017_50171201_38_dialog_content = "ฉันใช้พลังของกระจกเมฆาได้ แต่ก็มีบางอย่างที่อยู่เหนือการควบคุมของฉัน",
  ui_story_5017_50171201_39_dialog_content = "ตามตำนานของเกาะเมฆา กระจกเมฆานำมาซึ่งโชคลาภ และสามารถหยั่งรู้อนาคตได้...",
  ui_story_5017_50171201_40_dialog_content = "แต่บางตำนานก็กล่าวว่ากระจกเมฆานำมาซึ่งโชคร้าย...",
  ui_story_5017_50171201_41_dialog_content = "และจะต้องหาสิ่งมาปกคลุมกระจกไว้จนกว่าจะถึงโอกาสสำคัญจริง ๆ",
  ui_story_5017_50171201_42_dialog_content = "คิดว่ายังไงล่ะ ท่านซามูไร?",
  ui_story_5017_50171201_43_dialog_content = "... ท่านมิโกะ กรุณาวางกระจกเมฆาลงด้วยเถอะ",
  ui_story_5017_50171201_44_dialog_content = "เถรตรงจนน่าเบื่อ",
  ui_story_5017_50171201_45_dialog_content = "<color=#e8d9bb>แกล๊ง...</color>",
  ui_story_5017_50171201_46_dialog_content = "ท่านมิโกะ ต้องขออภัยด้วย",
  ui_story_5017_50171201_47_dialog_content = "ฮึ่ม...",
  ui_story_5017_50171201_48_dialog_content = "ด้วยปัญญาอันกระจ่างบริสุทธิ์ และใจอันสงบนิ่ง จิตญาณแห่งเต๋าจักคงอยู่ชั่วนิรันดร์ และวิญญาณทั้งหลายจักไปสู่สุคติ",
  ui_story_5017_50171201_49_dialog_content = "อา... อืออ...",
  ui_story_5017_50171201_50_dialog_content = "เป็นกระจกที่สะดวกจริง ๆ... แค่หลับไปคงไม่มีปัญหาล่ะนะ",
  ui_story_5017_50171201_51_dialog_content = "(แค่ท่องบทสวดชำระจิตใจธรรมดา ๆ ต่อหน้ากระจกเมฆาก็มีพลังมากพอที่จะทำให้คนหลับ)",
  ui_story_5017_50171201_52_dialog_content = "(สมแล้วที่ต้องเก็บรักษาให้ดี ถ้าตกอยู่ในมือคนชั่วล่ะก็เรื่องใหญ่แน่...)",
  ui_story_5017_50171201_53_dialog_content = "(แต่... เพื่อความสำเร็จของเทศกาลคาสึกะ...)",
  ui_story_5017_50171201_54_dialog_content = "(ต้องขอโทษจริง ๆ ท่านคุโบ ฉันจะนำกลับมาคืนโดยเร็วที่สุด)",
  ui_story_5017_50171201_55_dialog_content = "<color=#e8d9bb>บนถนนในเมืองเขตปราสาทโคฟุโจ</color>",
  ui_story_5017_50171201_56_dialog_content = "(สิ่งชั่วร้ายกำลังเพิ่มขึ้นเรื่อย ๆ ในโคฟุโจ...)",
  ui_story_5017_50171201_57_dialog_content = "(แต่นั่นไม่เป็นปัญหาสำหรับฉันหรอก หวังว่า PlayerName กับพวกหญิงสาวจะปลอดภัยดี...)",
  ui_story_5017_50171201_58_dialog_content = "<color=#e8d9bb>ฟิ้ว—</color>",
  ui_story_5017_50171201_59_dialog_content = "?",
  ui_story_5017_50171201_60_dialog_content = "ปีศาจร้ายจงสลายไป!",
  ui_story_5017_50171201_61_dialog_content = "อืมม...",
  ui_story_5017_50171201_62_dialog_content = "เร็วใช้ได้ แต่นั่นยังไม่พอสำหรับฉันหรอกนะ",
  ui_story_5017_50171201_63_dialog_content = "อ้าว... คุณนินจา",
  ui_story_5017_50171201_64_dialog_content = "ดึกป่านนี้เด็กดีควรไปนอนได้แล้วนะ...",
  ui_story_5017_50171201_65_dialog_content = "หรือจะให้ฉันทดสอบพลังของกระจกเมฆากับเธอดีล่ะ",
  ui_story_5017_50171201_66_dialog_content = "ว้าว! รินเนะ! เธอได้กระจกเมฆามาแล้วงั้นเหรอ?",
  ui_story_5017_50171201_67_dialog_content = "... เหยา, คุณ PlayerName แล้วก็คุณไวซ์?",
  ui_story_5017_50171201_68_dialog_content = "พวกคุณมากับคุณนินจาหรือนี่?",
  ui_story_5017_50171201_69_dialog_content = "เอ่อ เรื่องมันยาวน่ะ แต่สรุปสั้น ๆ ก็คือ...",
  ui_story_5017_50171201_70_dialog_content = "ไม่ต้องกลัวนะรินเนะ อาเมะโมริจะไม่ทำร้ายเธออีกแล้ว!",
  ui_story_5017_50171201_71_dialog_content = "... หือ เหยาอยู่ฝั่งเดียวกับคุณนินจาหรือนี่?",
  ui_story_5017_50171201_72_dialog_content = "เป็นรอยยิ้มที่น่ากลัวชะมัด!",
  ui_story_5017_50171201_73_dialog_content = "จะเชื่อหรือไม่ก็ตาม",
  ui_story_5017_50171201_74_dialog_content = "แต่ฉันคิดว่าระวังตัวกับคนแปลกหน้าไว้มันก็เป็นเรื่องที่ดีกว่า",
  ui_story_5017_50171201_75_dialog_content = "ว่าแต่! รินเนะ ตอนที่เธอไม่อยู่ อาเมะโมริบอกว่า...",
  ui_story_5017_50171201_76_dialog_content = "โอ๊ย!",
  ui_story_5017_50171201_77_dialog_content = "... ต่อยท้องฉันทำไมเนี่ย?",
  ui_story_5017_50171201_78_dialog_content = "ช่วยหุบปากไปก่อนได้มั้ย",
  ui_story_5017_50171201_79_dialog_content = "อ้าวว~ เธอพูดอะไรล่ะเนี่ย? ชักอยากรู้แล้วล่ะ",
  ui_story_5017_50171201_80_dialog_content = "คุณนินจาวิจารณ์ฉันว่ายังไงกันนะ? ช่วยบอกหน่อยสิ",
  ui_story_5017_50171201_81_dialog_content = "... คุไน!",
  ui_story_5017_50171201_82_dialog_content = "พอเถอะน่า ขอผมอธิบายสถานการณ์ก่อน! ที่จริงอาเมะโมริมาขอความช่วยเหลือจากเรา",
  ui_story_5017_50171201_83_dialog_content = "อาเมะโมริหวังว่า...",
  ui_story_5017_50171201_84_dialog_content = "ฉันอยากร่วมมือกับเธอเพื่อกำจัดภูตผีในโคฟุโจ",
  ui_story_5017_50171201_85_dialog_content = "(หา?)",
  ui_story_5017_50171201_86_dialog_content = "(หืม?)",
  ui_story_5017_50171201_87_dialog_content = "<size=30>ได้โปรดเถอะ ฉันยังไม่พร้อมจะเปิดเผยเรื่องท่านอาจารย์ให้คนนอกได้รู้</size>",
  ui_story_5017_50171201_88_dialog_content = "(... เข้าใจแล้ว คราวนี้ผมจะเชื่อคุณก็แล้วกัน...)",
  ui_story_5017_50171201_89_dialog_content = "กระจกเมฆาจะช่วยนำความสงบเรียบร้อยมาสู่โคฟุโจเร็วขึ้น",
  ui_story_5017_50171201_90_dialog_content = "(ดูปราดเดียวก็รู้ว่าโกหก เธอเหงื่อแตกพลั่กแล้ว...)",
  ui_story_5017_50171201_91_dialog_content = "(ว่าแต่เธอโน้มน้าวคุณ PlayerName ให้ช่วยเธอด้วยเหตุผลอะไรกันนะ?)",
  ui_story_5017_50171201_92_dialog_content = "(คงต้องทำเป็นเชื่อเธอไปก่อนสินะ... อืมม จู่ ๆ ก็กลายเป็นเรื่องน่าสนใจขึ้นมาเลยแฮะ...)",
  ui_story_5017_50171201_93_dialog_content = "ในเมื่อคุณ PlayerName พูดแบบนั้น...",
  ui_story_5017_50171201_94_dialog_content = "ฉันก็ไม่มีปัญหา",
  ui_story_5017_50171201_95_dialog_content = "ที่จริงฉันประทับใจมาก ๆ ด้วยซ้ำ...",
  ui_story_5017_50171201_96_dialog_content = "ที่<color=#FFB400>คุณอาเมะโมริ</color>ใส่ใจกับสามัญชนของเกาะเมฆาถึงเพียงนี้",
  ui_story_5017_50171201_97_dialog_content = "หา?",
  ui_story_5017_50171201_98_dialog_content = "หึหึ... การปิดบังตัวตนที่มุ่งมั่นและอบอุ่นด้วยเปลือกนอกที่เย็นชา นี่เป็นส่วนหนึ่งของวิชานินจาด้วยรึเปล่านะ?",
  ui_story_5017_50171201_99_dialog_content = "ตอนนี้ฉันรู้สึกนับถืออาเมะโมริอย่างถึงที่สุดแล้วล่ะ",
  ui_story_5017_50171201_100_dialog_content = "... อย่าดูถูกวิถีแห่งนินจาของฉันนะ!",
  ui_story_5017_50171201_101_dialog_content = "เดี๋ยว...",
  ui_story_5017_50171201_102_dialog_content = "ระวัง!",
  ui_story_5017_50171201_103_dialog_content = "อู!",
  ui_story_5017_50171201_104_dialog_content = "ยอดเลย ได้เวลาใช้กระจกเมฆาแล้วสินะ!",
  ui_story_5017_50171201_105_dialog_content = "เราเข้าใกล้เป้าหมายของคุณอาเมะโมริไปอีกขั้นหนึ่งแล้ว นั่นก็คือการกำจัดภูตผีให้หมดไปจากโคฟุโจ",
  ui_story_5017_50171201_106_dialog_content = "(เป็นผู้หญิงที่น่าหมั่นไส้อะไรยังงี้นะ...)",
  ui_story_5017_50171301_1_dialog_content = "เมฆสีทองจงปรากฏ สาดแสงเรืองรองทั่วสิบทิศ ผีร้ายจักครั่นคร้าม วิญญาณร้ายจงพินาศ",
  ui_story_5017_50171301_2_dialog_content = "อา...",
  ui_story_5017_50171301_3_dialog_content = "โอ...",
  ui_story_5017_50171301_4_dialog_content = "อาาา...",
  ui_story_5017_50171301_5_dialog_content = "พวกมันหายไปแล้ว!",
  ui_story_5017_50171301_6_dialog_content = "กระจกเมฆานี่แข็งแกร่งกว่าที่ฉันคิดไว้อีกนะเนี่ย!",
  ui_story_5017_50171301_7_dialog_content = "หึหึ แน่อยู่แล้ว กระจกบานนี้เป็นอุปกรณ์ศักดิ์สิทธิ์ที่ใช้ชำระวิญญาณผู้ล่วงลับในเทศกาลคาสึกะ",
  ui_story_5017_50171301_8_dialog_content = "ฉันจำเป็นต้องนำมันมาใช้ เพื่อให้เทศกาลในปีนี้ดำเนินไปอย่างราบรื่น",
  ui_story_5017_50171301_S8_dialog_content = "ว้าว! ไม่นึกเลยว่าจะมีของวิเศษขนาดนี้ด้วย! พอกระจกนี้สัมผัสถูกพวกผี ก็ชำระล้างไปจนหมดสิ้น...!",
  ui_story_5017_50171301_S9_dialog_content = "ที่รินเนะพูดว่า \"ชำระล้าง\" มันหมายความว่ายังไงกันแน่?",
  ui_story_5017_50171301_S10_dialog_content = "โฮะ ๆ... ก็หมายความว่าพวกมันตายหมดแล้วไงล่ะ!",
  ui_story_5017_50171301_9_dialog_content = "แถมวิญญาณผู้หลงทางเหล่านี้ได้ไปสู่ภพภูมิที่ดีเร็วขึ้นเพราะพลังของกระจกเมฆา...",
  ui_story_5017_50171301_10_dialog_content = "ช่างรู้สึกเป็นเกียรติยิ่งนัก",
  ui_story_5017_50171301_11_dialog_content = "...",
  ui_story_5017_50171301_12_dialog_content = "เหยา เธอจำอะไรได้บ้างมั้ย?",
  ui_story_5017_50171301_13_dialog_content = "ฉัน...",
  ui_story_5017_50171301_14_dialog_content = "เหมือนฉันจะเคยเห็นกระจกบานนี้มาก่อน...",
  ui_story_5017_50171301_15_dialog_content = "เคยเห็น? เป็นไปไม่ได้ ผู้ที่ได้สัมผัสกับพลังของมันก็น่าจะมีแต่คนที่ตายไปนานแล้ว",
  ui_story_5017_50171301_16_dialog_content = "พูดตรงจังแฮะ...",
  ui_story_5017_50171301_17_dialog_content = "เหยา นี่ไม่ใช่เทศกาลคาสึกะครั้งแรกของเธองั้นรึ? ทำไมกัน....",
  ui_story_5017_50171301_18_dialog_content = "อ่า... ฉันก็ไม่แน่ใจนะ แต่กระจกบานนี้มันดู...",
  ui_story_5017_50171301_19_dialog_content = "<color=#FFB400>ฆ่ามิโกะ...</color>",
  ui_story_5017_50171301_20_dialog_content = "?",
  ui_story_5017_50171301_21_dialog_content = "ย-เหยา?!",
  ui_story_5017_50171301_22_dialog_content = "เหยา เธอรู้ตัวรึเปล่าว่าพูดอะไรออกมา?",
  ui_story_5017_50171301_23_dialog_content = "นี่เธอติดนิสัยไม่ดีมาจากอาเมะโมริงั้นรึ?",
  ui_story_5017_50171301_24_dialog_content = "นั่นไม่ใช่ฉันนะ! จู่ ๆ ฉันก็สัมผัสได้ถึงความคิดที่หลงเหลืออยู่ในหยกชิโนะกิ...",
  ui_story_5017_50171301_25_dialog_content = "ฉันไม่เคยคิดร้ายกับรินเนะเลยนะ!",
  ui_story_5017_50171301_26_dialog_content = "กลับกันซะอีก ตอนฉันเจอรินเนะครั้งแรก ฉันก็รู้สึกคุ้นเคยอย่างประหลาด เหมือนว่าเราเป็นเพื่อนสนิทกันมาก่อน!",
  ui_story_5017_50171301_27_dialog_content = "ให้ตายสิ... หยกชิโนะกิต้องการบอกอะไรกับฉันกันแน่?",
  ui_story_5017_50171301_28_dialog_content = "...",
  ui_story_5017_50171301_29_dialog_content = "(ความคิดที่หลงเหลืออยู่ในหยกชิโนะกิ...)",
  ui_story_5017_50171301_30_dialog_content = "(ท่านอาจารย์ เหยา <color=#FFB400>ตอนนั้น</color>เกิดอะไรขึ้นกันแน่นะ?)",
  ui_story_5017_50171301_31_dialog_content = "<color=#e8d9bb>เปรี๊ยะ... เปรี๊ยะ...</color>",
  ui_story_5017_50171301_32_dialog_content = "หืม?",
  ui_story_5017_50171301_33_dialog_content = "เป็นเสียงที่ชวนให้ไม่สบายใจเลยแฮะ",
  ui_story_5017_50171301_34_dialog_content = "... ทุกคน! ระวังพวกผีที่โดนกระจกเมฆากำจัดนะ...",
  ui_story_5017_50171301_35_dialog_content = "<color=#e8d9bb>เปรี๊ยะ... เปรี๊ยะ...</color>",
  ui_story_5017_50171301_36_dialog_content = "อาา...",
  ui_story_5017_50171301_37_dialog_content = "อู!",
  ui_story_5017_50171301_38_dialog_content = "อ-อะไรกัน?!",
  ui_story_5017_50171301_39_dialog_content = "ฉันใช้กระจกเมฆาแล้วนี่... ทำไมพวกมันถึงกลับมาอีก?",
  ui_story_5017_50171301_40_dialog_content = "ไม่เคยมีเรื่องแบบนี้เกิดขึ้นในเทศกาลคาสึกะมาก่อนเลยนี่นา!!!",
  ui_story_5017_50171301_41_dialog_content = "โฮกกก...!!!",
  ui_story_5017_50171301_42_dialog_content = "เป็นไปไม่ได้... ไม่จริง!",
  ui_story_5017_50171301_S42_dialog_content = "กระจกเมฆาเป็นของวิเศษที่สืบทอดมา ใช้ในการปัดเป่าการบุกรุกของภูตผี...",
  ui_story_5017_50171301_S43_dialog_content = "นั่นคือสิ่งที่ท่านคุโบบอกฉัน...",
  ui_story_5017_50171301_43_dialog_content = "ตราบใดที่ฉันมีพลังของกระจกเมฆา... ฉันก็แค่ต้องใช้มันอีกครั้ง...",
  ui_story_5017_50171301_44_dialog_content = "เมฆสีทองจงปรากฏ สาดแสงเรืองรองทั่วสิบทิศ ผีร้ายจักครั่นคร้าม วิญญาณร้ายจงพินาศ",
  ui_story_5017_50171301_45_dialog_content = "...อ๊ะ?!",
  ui_story_5017_50171301_46_dialog_content = "(ความเจ็บแปลบที่แล่นไปทั่วร่างกายนี่มันอะไรกัน...?)",
  ui_story_5017_50171301_S46_dialog_content = "(กระจกเมฆา...)",
  ui_story_5017_50171301_47_dialog_content = "โฮกกก!!",
  ui_story_5017_50171301_48_dialog_content = "โฮกกกกกกกก!!!",
  ui_story_5017_50171301_49_dialog_content = "จงสำแดงพลัง! เพลงหมัดค้อนศิลา!",
  ui_story_5017_50171301_S49_dialog_content = "กระจกเมฆาใช้ปัดเป่าภูตผีไม่ใช่เหรอ? ทำไมมันชุบชีวิตให้ผีล่ะ?!",
  ui_story_5017_50171301_50_dialog_content = "หยุดใช้กระจกนั่นเถอะ! ส่งพวกมันไปลงนรกดีกว่าน่า!",
  ui_story_5017_50171301_51_dialog_content = "วิชาลับ! คาถาสะกดเงา!",
  ui_story_5017_50171301_52_dialog_content = "โอ...",
  ui_story_5017_50171301_53_dialog_content = "...",
  ui_story_5017_50171301_54_dialog_content = "อย่าเพิ่งกังวลเรื่องกระจกเมฆาเลย...",
  ui_story_5017_50171301_55_dialog_content = "ดูเหมือนว่าผีจะบุกมาจากทิศทางที่แน่ชัด...",
  ui_story_5017_50171301_56_dialog_content = "เดี๋ยวนะ... พวกมันมาจากเมืองโคฟุโจงั้นเหรอ?!",
  ui_story_5017_50171301_57_dialog_content = "ไม่นะ! เราจะให้มันบุกส่วนในของปราสาทไม่ได้!",
  ui_story_5017_50171301_58_dialog_content = "สหายทั้งหลาย จงขับไล่สิ่งชั่วร้ายและปกป้องปราสาทหลักด้วยกันเถอะ!",
  ui_story_5017_50171301_59_dialog_content = "พวกเรามีเป้าหมายเดียวกัน... ในระดับหนึ่ง",
  ui_story_5017_50171301_60_dialog_content = "ช่วยนำทางเข้าไปส่วนในของปราสาทด้วย",
  ui_story_5017_50171301_61_dialog_content = "<color=#e8d9bb>พลับพลาเมฆา เมืองโคฟุโจ ใกล้กับแดนผนึก</color>",
  ui_story_5017_50171301_62_dialog_content = "...",
  ui_story_5017_50171301_63_dialog_content = "...",
  ui_story_5017_50171301_64_dialog_content = "...?",
  ui_story_5017_50171301_65_dialog_content = "ความรู้สึกกดดันนี่มันอะไรกัน...",
  ui_story_5017_50171301_66_dialog_content = "ชู่ว! อย่ารบกวนคุณรินเนะสิ เธอกำลังทำสมาธิอยู่!",
  ui_story_5017_50171301_67_dialog_content = "?!",
  ui_story_5017_50171301_68_dialog_content = "พลังของ \"ฮาราอิ\" กับ \"ชิโนะกิ\" แข็งแกร่งยิ่งกว่าเดิม",
  ui_story_5017_50171301_69_dialog_content = "เราใกล้แล้วสินะ",
  ui_story_5017_50171301_70_dialog_content = "ถูกแล้ว ไม่ต้องสงสัยเลย ฉันสัมผัสได้...",
  ui_story_5017_50171301_71_dialog_content = "ตัวตนของ \"มลทิน\" ที่อาศัยอยู่ภายใน มันชัดเจนยิ่งกว่าครั้งไหน ๆ",
  ui_story_5017_50171301_72_dialog_content = "...",
  ui_story_5017_50171301_73_dialog_content = "\"มลทิน\" งั้นเหรอ? ทำไมอาจารย์ของฉันเป็นต้นกำเนิดของสิ่งชั่วร้ายล่ะ?!",
  ui_story_5017_50171301_74_dialog_content = "หืมม? \"อาจารย์\"... ของเธอ?",
  ui_story_5017_50171301_75_dialog_content = "อา... ศิษย์น้องเจ้าปัญหา",
  ui_story_5017_50171301_76_dialog_content = "...เรื่องมาถึงขั้นนี้แล้ว พูดความจริงไปก็คงไม่เสียหาย",
  ui_story_5017_50171301_77_dialog_content = "ทางที่เธอพาเราไปนั้นเป็นเส้นทางมุ่งสู่แดนผนึก",
  ui_story_5017_50171301_78_dialog_content = "แดนผนึก?",
  ui_story_5017_50171301_79_dialog_content = "ท่านคุโบไม่เคยบอกฉันเลยว่าในปราสาทมีสถานที่แบบนี้อยู่...",
  ui_story_5017_50171301_80_dialog_content = "ในอดีต ฟูจิคุโมะได้จับอาจารย์ของพวกเราขังไว้ในแดนผนึก",
  ui_story_5017_50171301_81_dialog_content = "แสดงว่าสิ่งชั่วร้ายที่ฉันสัมผัสได้เบื้องหน้าก็คือ...",
  ui_story_5017_50171301_82_dialog_content = "เธอคิดว่าสิ่งชั่วร้ายที่เธอสัมผัสได้...",
  ui_story_5017_50171301_83_dialog_content = "เป็นภูตผีที่บุกโจมตีปราสาท หรืออาจารย์ของฉันกันล่ะ?",
  ui_story_5017_50171301_84_dialog_content = "แต่มันจะเป็นใครไปได้อีก?",
  ui_story_5017_50171301_85_dialog_content = "...",
  ui_story_5017_50171301_86_dialog_content = "พูดอย่างเดียวคงไม่เชื่อสินะ",
  ui_story_5017_50171301_87_dialog_content = "พอผ่านตรงนี้ไปก็คงจะถึงที่หมายแล้ว",
  ui_story_5017_50171301_88_dialog_content = "ฉันยังมีอีกเหตุผลหนึ่งที่ตามเธอมา",
  ui_story_5017_50171301_89_dialog_content = "ฉันอยากใช้พลังของเธอปลดปล่อยอาจารย์ของเราจากปีศาจร้ายที่เฝ้าอยู่",
  ui_story_5017_50171301_90_dialog_content = "สิ่งชั่วร้ายที่เธอสัมผัสได้... มาจากผนึกที่กักขังท่านอาจารย์เอาไว้",
  ui_story_5017_50171301_91_dialog_content = "ดูด้วยตาตัวเองสิ รินเนะ",
  ui_story_5017_50171301_92_dialog_content = "นี่ล่ะ คือผลงานของฟูจิคุโมะ...",
  ui_story_5017_50171301_93_dialog_content = "หา...?",
  ui_story_5017_50171301_94_dialog_content = "*โฮก*",
  ui_story_5017_50171301_95_dialog_content = "ผ-ผีพวกนี้... ใส่ชุดเหมือนคนในโคฟุโจเลย!",
  ui_story_5017_50171301_96_dialog_content = "นี่มัน... พวกเขา...",
  ui_story_5017_50171301_97_dialog_content = "ทุกคน... มีตราประจำตระกูลของท่านคุโบ...",
  ui_story_5017_50171301_98_dialog_content = "กรร...",
  ui_story_5017_50171301_99_dialog_content = "กรรร!!!",
  ui_story_5017_50171301_100_dialog_content = "ดูเหมือนพวกเขาจะยังมีสติหลงเหลืออยู่ด้วยนะ!",
  ui_story_5017_50171301_101_dialog_content = "(ปรับตัวได้ง่าย ขับเคลื่อนด้วยจิตสำนึกระดับสูงบางอย่างที่ควบคุมมันอีกที พวกมันมีเป้าหมายชัดเจนเพียงหนึ่งเดียว...)",
  ui_story_5017_50171301_X101_dialog_content = "(แถมยังวิวัฒนาการขึ้นเพื่อฟังคำสั่งและโจมตีเราโดยเฉพาะ...)",
  ui_story_5017_50171301_102_dialog_content = "(ถ้ามองในมุมนั้น ผีพวกนี้ก็ไม่ต่างจากอิคลิพไซท์ชนิดพิเศษเลย...)",
  ui_story_5017_50171301_103_dialog_content = "ระวังตัวให้ดี รินเนะ",
  ui_story_5017_50171301_104_dialog_content = "เธอกำจัดนักรบปีศาจเหล่านี้ด้วยวิธีทั่ว ๆ ไปไม่ได้หรอกนะ",
  ui_story_5017_50171301_105_dialog_content = "เตรียมตัวให้ดีล่ะทุกคน ศึกครั้งนี้ไม่ง่ายแน่",
  ui_story_5017_50171301_106_dialog_content = "แต่ฉันก็ยังไม่เข้าใจอยู่ดีว่าพวกมันมาอยู่ที่นี่ได้ยังไง...",
  ui_story_5017_50171301_107_dialog_content = "แถมยังหลงเหลือจิตสำนึกมากพอที่จะปกป้องที่นี่ต่อไป แม้ว่าร่างกายจะตายไปแล้ว...",
  ui_story_5017_50171301_108_dialog_content = "ทำไมท่านคุโบต้องส่งซามูไรผีมาที่นี่ด้วย?",
  ui_story_5017_50171301_109_dialog_content = "ท... ท่านคุโบวางแผนอะไรอยู่กันแน่?!",
  ui_story_5017_50171301_110_dialog_content = "พอได้แล้ว!",
  ui_story_5017_50171301_111_dialog_content = "\"ไม่ว่าเราจะอยู่ในฐานะอะไร และจะต้องเผชิญกับปัญหาอะไรก็ตาม ศัตรูของเรามีเพียงหนึ่งเดียว นั่นก็คือพวกวิญญาณชั่วร้าย!\"",
  ui_story_5017_50171301_112_dialog_content = "เธอบอกฉันเองไม่ใช่หรือไง?",
  ui_story_5017_50171301_113_dialog_content = "...?!",
  ui_story_5017_50171301_114_dialog_content = "ท่านอาเมะโมริ...",
  ui_story_5017_50171301_115_dialog_content = "อย่ามัวชักช้าอยู่เลย! พลังที่กำปั้นของฉันมันจะเผามืออยู่แล้วเนี่ย!",
  ui_story_5017_50171301_116_dialog_content = "ไวซ์! PlayerName! พวกเธอพร้อมรึยัง?",
  ui_story_5017_50171301_117_dialog_content = "เราจะไปสั่งสอนพวกผีให้รู้สำนึก เพราะงั้นเตรียมตัวให้ดีล่ะ!",
  ui_story_5017_50171301_118_dialog_content = "ย้ากกก!",
  ui_story_5017_50171302_1_dialog_content = "อา...",
  ui_story_5017_50171302_2_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_5017_50171302_3_dialog_content = "ไม่ใช่เล่น ๆ เลยนะเนี่ย!",
  ui_story_5017_50171302_4_dialog_content = "อ๊ากก! อัก!",
  ui_story_5017_50171302_5_dialog_content = "ตัวสุดท้ายแล้ว!",
  ui_story_5017_50171302_6_dialog_content = "ด้วยพลังแห่งการชำระล้าง...",
  ui_story_5017_50171302_7_dialog_content = "ขอม่านพลังนี้จงปัดเป่ามลทินแก่วิญญาณทุกดวง!",
  ui_story_5017_50171302_8_dialog_content = "โอ...",
  ui_story_5017_50171302_9_dialog_content = "ฟู่...",
  ui_story_5017_50171302_10_dialog_content = "จบสักที",
  ui_story_5017_50171302_11_dialog_content = "...",
  ui_story_5017_50171302_12_dialog_content = "รินเนะ... พิธีกรรมชำระล้างของคุณนี่ยอดไปเลย!",
  ui_story_5017_50171302_13_dialog_content = "คุณก็ทำได้อย่างสมบูรณ์แบบโดยไม่ต้องใช้พลังของกระจกเมฆานี่นา...",
  ui_story_5017_50171302_14_dialog_content = "ฉันมั่นใจว่าคุณจะต้องเป็นมิโกะที่แข็งแกร่งคู่ควรกับเทศกาลคาสึกะในอนาคตแน่นอน!",
  ui_story_5017_50171302_15_dialog_content = "หึหึ... หวังว่าจะเป็นแบบนั้นนะ",
  ui_story_5017_50171302_16_dialog_content = "ฉันรอคอยเทศกาลคาสึกะมาเสมอ... เพื่อที่ท่านคุโบ และชาวเกาะเมฆาทุกคนจะได้ยอมรับในตัวฉัน...",
  ui_story_5017_50171302_17_dialog_content = "จนกระทั่งวันนี้ ฉันก็ยังไม่รู้อะไรเลยเกี่ยวกับพลังที่แท้จริงของกระจกเมฆา",
  ui_story_5017_50171302_18_dialog_content = "ฉันพยายามอย่างหนักเพื่อขับไล่ผีร้ายไปจากเมือง และป้องกันไม่ให้เกิดเหตุร้ายกับเทศกาลคาสึกะ",
  ui_story_5017_50171302_19_dialog_content = "แต่ฉันกลับไม่เคยรู้เลยว่ายังมีภูตผีหลบซ่อนอยู่ในมุมมืดของโคฟุโจ",
  ui_story_5017_50171302_20_dialog_content = "ฮะฮะ...",
  ui_story_5017_50171302_21_dialog_content = "รินเนะ...",
  ui_story_5017_50171302_22_dialog_content = "คุณเข้าใจผิดแล้ว รินเนะ",
  ui_story_5017_50171302_23_dialog_content = "คุณอยากเข้าร่วมเทศกาลคาสึกะเพื่อให้ทุกคนยอมรับ นี่เป็นสิ่งสำคัญที่สุดสำหรับคุณจริง ๆ เหรอ?",
  ui_story_5017_50171302_24_dialog_content = "ถ้าคุณถามผม...",
  ui_story_5017_50171302_25_dialog_content = "(นี่ฉัน... พูดมันออกไปจริง ๆ เหรอเนี่ย...?)",
  ui_story_5017_50171302_26_dialog_content = "...",
  ui_story_5017_50171302_27_dialog_content = "ตอนที่เราเสียท่า คุณก็ดูแลพวกเราและปกป้องทุกคนจากฝูงภูตผี...",
  ui_story_5017_50171302_28_dialog_content = "ความรู้สึกของคุณในตอนนั้น... ผมสัมผัสมันได้อย่างชัดเจน",
  ui_story_5017_50171302_29_dialog_content = "...",
  ui_story_5017_50171302_30_dialog_content = "ความตั้งใจที่จะเผชิญหน้ากับความตายโดยไม่ลังเล เพื่อปกป้องชีวิตผู้อื่น...",
  ui_story_5017_50171302_31_dialog_content = "ถ้าคุณถามผม... ผมว่าคุณมีคุณสมบัติของการเป็นมิโกะมากเกินพอด้วยซ้ำ",
  ui_story_5017_50171302_32_dialog_content = "เพราะฉะนั้น ได้โปรด... อย่าโทษตัวเองแบบนั้นเลยนะครับ",
  ui_story_5017_50171302_33_dialog_content = "...",
  ui_story_5017_50171302_34_dialog_content = "...หึหึ",
  ui_story_5017_50171302_35_dialog_content = "บางทีคุณก็ทำตัวน่ารักเป็นเหมือนกันนะเนี่ย PlayerName ฉันดูอมทุกข์ขนาดนั้นเลยเหรอ?",
  ui_story_5017_50171302_36_dialog_content = "(เธอกลับมาเป็นปกติแล้วแฮะ...)",
  ui_story_5017_50171302_37_dialog_content = "โว่ว! นี่มันวิชา \"เปลี่ยนใบหน้าพริบตา\" ที่ร่ำลือของแดนตะวันออกไกลใช่มั้ย?",
  ui_story_5017_50171302_38_dialog_content = "เอ๋?!",
  ui_story_5017_50171302_39_dialog_content = "มีอะไรรึ?",
  ui_story_5017_50171302_40_dialog_content = "เดี๋ยวก่อน นี่มัน...?",
  ui_story_5017_50171302_41_dialog_content = "<color=#e8d9bb>แกล๊ก...</color>",
  ui_story_5017_50171302_42_dialog_content = "หา? หยกหายไป...",
  ui_story_5017_50171302_43_dialog_content = "ไม่ใช่... มันไม่ได้หายไปไหน...",
  ui_story_5017_50171302_44_dialog_content = "<color=#e8d9bb>คึ่กคึ่กคึ่ก...</color>",
  ui_story_5017_50171302_45_dialog_content = "มีการเคลื่อนไหวรุนแรงเกิดขึ้นในแดนผนึก...",
  ui_story_5017_50171302_46_dialog_content = "อาจารย์ของเรายังมีชีวิตอยู่จริง ๆ ด้วย...",
  ui_story_5017_50171302_47_dialog_content = "เธอเรียกฮาราอิชิโนะกิกลับคืนไป... ในที่สุดมันก็กลับไปอยู่ข้างกายเธออีกครั้ง!",
  ui_story_5017_50171302_48_dialog_content = "ท่านคุโบกักขังปีศาจร้ายแบบไหนเอาไว้กันนะ...",
  ui_story_5017_50171302_49_dialog_content = "จะใช่ปีศาจร้ายหรือไม่ เดี๋ยวเราจะได้รู้กัน",
  ui_story_5017_50171401_1_dialog_content = "<color=#e8d9bb>คึ่กคึ่กคึ่ก...</color>",
  ui_story_5017_50171401_2_dialog_content = "<color=#e8d9bb>ตูม!!!</color>",
  ui_story_5017_50171401_3_dialog_content = "เฮ่อ...",
  ui_story_5017_50171401_4_dialog_content = "ฉันให้หยกกับพวกเธอไปแล้ว แต่กลับเอามาคืนแบบนี้ มันหมายความว่ายังไงกัน...",
  ui_story_5017_50171401_5_dialog_content = "ไม่ได้เจอกันนานเลยนะ ศิษย์รักของฉัน",
  ui_story_5017_50171401_6_dialog_content = "ท่านอาจารย์...!",
  ui_story_5017_50171401_7_dialog_content = "ฉันรู้ว่าตลอดหลายปีที่ผ่านมาคุณยังมีชีวิตอยู่ อาจารย์... ฉันไม่เคยสงสัยเลย...",
  ui_story_5017_50171401_8_dialog_content = "ฉันเรียนรู้วิชานินจาใหม่แล้วก็จดในคัมภีร์ไว้เยอะเลย... ฉันอยากอวดกับอาจารย์มากเลยค่ะ...",
  ui_story_5017_50171401_9_dialog_content = "...",
  ui_story_5017_50171401_10_dialog_content = "ยังเหมือนเดิมไม่เปลี่ยนเลยนะ อาเมะโมริ",
  ui_story_5017_50171401_11_dialog_content = "บางครั้งเธอก็พยายามทำตัวไร้หัวใจ... บางครั้งเธอก็แสดงความเห็นอกเห็นใจและตัวตนที่อ่อนแอออกมาโดยไม่จำเป็น",
  ui_story_5017_50171401_12_dialog_content = "ไม่ว่าเปลือกนอกจะดูเย็นชาหรืออำมหิตแค่ไหน แต่สุดท้ายถ้าพ่ายให้กับอารมณ์มันก็ไร้ประโยชน์",
  ui_story_5017_50171401_13_dialog_content = "เธอยังยึดติดกับ \"ความรู้สึก\" และสิ่งนั้นจะคอยถ่วงเธอไว้",
  ui_story_5017_50171401_14_dialog_content = "หากต้องการเอาชีวิตรอดในโลกใบนี้ เธอจะต้องทิ้ง \"ความรู้สึก\" ของตัวเองไปให้หมด",
  ui_story_5017_50171401_15_dialog_content = "ท่านอาจารย์...",
  ui_story_5017_50171401_16_dialog_content = "ฉันจะจำคำสอนให้ขึ้นใจ และจะพยายามพัฒนาให้ดีขึ้นค่ะ อาจารย์...!",
  ui_story_5017_50171401_17_dialog_content = "เหยา... เธอก็มาหาฉันเหมือนกันรึ",
  ui_story_5017_50171401_18_dialog_content = "อาจารย์...?",
  ui_story_5017_50171401_19_dialog_content = "คุณ... เป็นอาจารย์ของฉันจริง ๆ เหรอ?",
  ui_story_5017_50171401_20_dialog_content = "(เธอรู้ชื่อฉันด้วย...)",
  ui_story_5017_50171401_21_dialog_content = "(ทำไมกัน... ทำไมฉันถึงหวาดกลัว พอได้เจอเธออีกครั้ง...?)",
  ui_story_5017_50171401_22_dialog_content = "(ไม่ได้... ฉันจะกลัวไม่ได้ ความกลัวคือศัตรู...)",
  ui_story_5017_50171401_23_dialog_content = "ฉันเดินทางมาที่เกาะเมฆาเพื่อสืบหาว่าเกิดอะไรขึ้นกับตัวฉันเมื่อ 10 ปีก่อน",
  ui_story_5017_50171401_24_dialog_content = "ความทรงจำที่กระจัดกระจายและสับสนฉุดรั้งชีวิตของฉันมานานแล้ว!",
  ui_story_5017_50171401_25_dialog_content = "เสียงกระดิ่งที่ดังไม่หยุด... กระจกที่ฉันคุ้นเคย...",
  ui_story_5017_50171401_26_dialog_content = "ทำไมความทรงจำของฉันถึงเกี่ยวข้องกับเทศกาลคาสึกะ?",
  ui_story_5017_50171401_27_dialog_content = "ถ้าคุณเป็นอาจารย์ของฉันจริง ๆ คุณก็น่าจะรู้คำตอบ!",
  ui_story_5017_50171401_28_dialog_content = "เพียง 10 ปีเท่านั้น เธอเติบโตขึ้นมากจริง ๆ เหยา",
  ui_story_5017_50171401_29_dialog_content = "เธอมีสิทธิ์ที่จะได้รู้เรื่องที่เกิดขึ้นกับตัวเองในอดีต แต่...",
  ui_story_5017_50171401_30_dialog_content = "ตอนนี้ไม่ใช่เวลาที่เหมาะสมนัก",
  ui_story_5017_50171401_31_dialog_content = "เพราะฉันมีสิ่งที่สำคัญมากที่จะต้องทำ",
  ui_story_5017_50171401_32_dialog_content = "เธอ เด็กสาวคนนั้น...",
  ui_story_5017_50171401_33_dialog_content = "...",
  ui_story_5017_50171401_34_dialog_content = "ดูจากท่าทีแล้ว เธอคงเป็นมิโกะที่รับใช้ฟูจิคุโมะสินะ?",
  ui_story_5017_50171401_35_dialog_content = "หึหึ... เธอไม่เหมือน<color=#FFB400>มิโกะคนนั้น</color>แม้แต่นิดเดียว",
  ui_story_5017_50171401_36_dialog_content = "หนอย... เอามือออกไป!",
  ui_story_5017_50171401_37_dialog_content = "บอกฉันทีสิ ฟูจิคุโมะยังอยู่ในโคฟุโจรึเปล่า?",
  ui_story_5017_50171401_38_dialog_content = "นั่นมัน... ไม่ใช่เรื่องของแก",
  ui_story_5017_50171401_39_dialog_content = "ฮึ่ม... นึกแล้วว่าจะต้องเป็นแบบนี้",
  ui_story_5017_50171401_40_dialog_content = "ข้ารับใช้ของฟูจิคุโมะน่ะภักดีต่อเขาไม่เคยเสื่อมคลาย",
  ui_story_5017_50171401_41_dialog_content = "ฉันก็แค่ถามคำถามง่าย ๆ ไม่มีอะไรมากไปกว่านั้น",
  ui_story_5017_50171401_42_dialog_content = "แต่ก็นะ... ถ้าฟูจิคุโมะไม่อยู่ อะไร ๆ มันก็จะง่ายขึ้นมาก",
  ui_story_5017_50171401_43_dialog_content = "หยุดนะ!",
  ui_story_5017_50171401_44_dialog_content = "แกต้องการอะไรกันแน่?!",
  ui_story_5017_50171401_45_dialog_content = "(โอ๊ย...)",
  ui_story_5017_50171401_46_dialog_content = "รินเนะ! คุณไม่เป็นไรนะ?!",
  ui_story_5017_50171401_47_dialog_content = "ฉันไม่เป็นไร... แต่ฉันจะไม่ยอมให้ใครหน้าไหนมาคุกคามผู้คนของโคฟุโจเด็ดขาด!",
  ui_story_5017_50171401_48_dialog_content = "น่ารำคาญจริง ๆ...",
  ui_story_5017_50171401_49_dialog_content = "ฟูจิคุโมะมันหลอกใช้เธอมานานหลายปีเลย ใช่มั้ย?",
  ui_story_5017_50171401_50_dialog_content = "ท่านคุโบเป็นคนดี! เขาไม่มีทางทำร้ายหรือหลอกใช้ใคร!",
  ui_story_5017_50171401_51_dialog_content = "จิตใจแน่วแน่กว่าที่คิดไว้นะเนี่ย...",
  ui_story_5017_50171401_52_dialog_content = "ฉันไม่มีอะไรจะพูดกับเธอแล้ว",
  ui_story_5017_50171401_53_dialog_content = "ถอยไป รินเนะ!",
  ui_story_5017_50171401_54_dialog_content = "...?!",
  ui_story_5017_50171401_55_dialog_content = "<color=#e8d9bb>ฟิ้วว!</color>",
  ui_story_5017_50171401_56_dialog_content = "วิญญาณร้ายจงออกไป!",
  ui_story_5017_50171401_57_dialog_content = "อาจารย์! ระวัง!",
  ui_story_5017_50171401_58_dialog_content = "หึหึ ตอบสนองไวดีนี่... ดูท่า แก้ปัญหาด้วยวิธีคงจะเร็วที่สุดสินะ",
  ui_story_5017_50171401_59_dialog_content = "บาดเจ็บตรงไหนรึเปล่าคะ อาจารย์?",
  ui_story_5017_50171401_60_dialog_content = "คุณเพิ่งหลุดจากผนึก นี่ไม่ใช่เวลามาต่อสู้นะคะ!",
  ui_story_5017_50171401_61_dialog_content = "เกาะเมฆาจะขาดผู้นำไม่ได้ ท่านอาจารย์! ได้โปรดมากับฉันเถอะ",
  ui_story_5017_50171401_62_dialog_content = "...เธอจะขวางฉันหรือไง อาเมะโมริ?",
  ui_story_5017_50171401_63_dialog_content = "ไม่ค่ะ อาจารย์... ฉัน...",
  ui_story_5017_50171401_64_dialog_content = "ฉันแค่อยากติดตามอาจารย์ตลอดไป...",
  ui_story_5017_50171401_65_dialog_content = "มีคนมากมายรอท่านอยู่... ตลอด 10 ปีที่ผ่านมา พวกเขากำลังรอให้ท่านกลับไป",
  ui_story_5017_50171401_66_dialog_content = "ฉันจะไม่กลับไปอีก",
  ui_story_5017_50171401_67_dialog_content = "เมื่อ 10 ปีก่อน ในวันที่ฉันถูกกักขัง ฉันไม่ใช่แม่ทัพของพวกเธออีกต่อไปแล้ว",
  ui_story_5017_50171401_68_dialog_content = "จากนี้ไป ความตั้งใจเดียวที่ฉันมี คือต่อสู้เพื่อตัวเองเท่านั้น",
  ui_story_5017_50171401_69_dialog_content = "ชีวิตและความภักดีของผู้คนเหล่านั้นไม่ใช่ภาระของฉันอีกต่อไป",
  ui_story_5017_50171401_70_dialog_content = "อ-อาจารย์?!",
  ui_story_5017_50171401_71_dialog_content = "...",
  ui_story_5017_50171401_72_dialog_content = "ถ้าเช่นนั้นแล้ว... ฉันก็จะขอติดตามอาจารย์ต่อไป!",
  ui_story_5017_50171401_73_dialog_content = "... ดูเหมือนเธอจะไม่เข้าใจสิ่งที่ฉันพูดเลย การติดตามของเธอจะกลายเป็นเกะกะมากกว่า",
  ui_story_5017_50171401_74_dialog_content = "ถ้าอยากจะหยุดฉันจริง ๆ...",
  ui_story_5017_50171401_75_dialog_content = "ก็ชักดาบออกไป...",
  ui_story_5017_50171401_76_dialog_content = "<color=#e8d9bb>ฟึบ!</color>",
  ui_story_5017_50171401_77_dialog_content = "คงจะเลี่ยงการต่อสู้ไม่ได้จริง ๆ สินะ",
  ui_story_5017_50171401_78_dialog_content = "เอาล่ะ ศิษย์รักของฉัน... ขอดูหน่อยสิ ว่า 10 ปีที่ฉันไม่อยู่ พวกเธอก้าวหน้าไปแค่ไหนแล้ว!",
  ui_story_5017_50171401_79_dialog_content = "ฮึ่ม นึกแล้วเชียวว่าเรื่องจะต้องเป็นแบบนี้",
  ui_story_5017_50171401_80_dialog_content = "งั้นก็โชว์ฝีมือมาเลย อยากรู้เหมือนกันว่าคุณจะเก่งสมกับเป็น \"อาจารย์\" ของฉันรึเปล่า!",
  ui_story_5017_50171401_81_dialog_content = "เราต้องช่วยรินเนะกับเหยานะ PlayerName!",
  ui_story_5017_50171401_82_dialog_content = "แน่นอนอยู่แล้ว!",
  ui_story_5017_50171501_1_dialog_content = "แฮ่ก... แฮ่ก...",
  ui_story_5017_50171501_2_dialog_content = "เป็นศึกที่เหนื่อยอย่างที่คิดจริง ๆ...",
  ui_story_5017_50171501_3_dialog_content = "*หอบ*",
  ui_story_5017_50171501_4_dialog_content = "(อาจารย์ของพวกเธอแข็งแกร่งก็จริง แต่ยังไง... เราก็พอมีทางชนะ)",
  ui_story_5017_50171501_5_dialog_content = "...",
  ui_story_5017_50171501_6_dialog_content = "ตั้งสติไว้ PlayerName...",
  ui_story_5017_50171501_7_dialog_content = "ไม่ต้องกลัวไป ฉันจะไม่เสียเวลากับการต่อสู้ไร้ความหมายแบบนี้หรอก",
  ui_story_5017_50171501_8_dialog_content = "แต่ถึงอย่างนั้น ฉันก็ต้องชมเชย พวกเธอทุกคนได้พิสูจน์แล้วว่าเป็นคู่ต่อสู้ที่คู่ควร",
  ui_story_5017_50171501_9_dialog_content = "ส่วนเธอทั้งสองคน ศิษย์รักของฉัน... พวกเธอเติบโตขึ้นมาก ฉันไม่ผิดหวังเลยจริง ๆ",
  ui_story_5017_50171501_10_dialog_content = "สักวันเราคงจะได้พบกันอีก",
  ui_story_5017_50171501_11_dialog_content = "คุณยัง... ยืนกรานที่จะไปอยู่ดีเหรอคะ... อาจารย์?",
  ui_story_5017_50171501_12_dialog_content = "ฉันรอคอยวันนี้มานานเหลือเกิน",
  ui_story_5017_50171501_13_dialog_content = "ยอดมาก",
  ui_story_5017_50171501_14_dialog_content = "ข้าเองก็รอวันนี้มานานเช่นกัน <color=#FFB400>นากิ</color>",
  ui_story_5017_50171501_15_dialog_content = "(เรียกอาจารย์ด้วยชื่อจริงงั้นรึ...)",
  ui_story_5017_50171501_16_dialog_content = "พวกเจ้าเป็นคนจัดการกับซามูไรผีของข้ารึ?",
  ui_story_5017_50171501_17_dialog_content = "นากิ... แม้จะพ่ายแพ้และถูกจองจำมานานเป็นสิบปีแต่ก็ยังทำอะไรไม่ยั้งคิดเหมือนเดิม ช่างโง่เขลานัก",
  ui_story_5017_50171501_18_dialog_content = "ตกต่ำถึงขนาดต้องให้เด็ก ๆ มาช่วยเลยรึ...",
  ui_story_5017_50171501_19_dialog_content = "ฟูจิคุโมะ... กลับมาเร็วกว่าที่ฉันคิดไว้นะ",
  ui_story_5017_50171501_20_dialog_content = "แต่ก็ดี ฉันจะได้ไม่ต้องลำบากคาดคั้นข้อมูลจากข้ารับใช้ของแก",
  ui_story_5017_50171501_21_dialog_content = "ท่านคุโบ! ท่านกลับมาแล้ว!",
  ui_story_5017_50171501_22_dialog_content = "แต่ทำไมท่านถึงมาคนเดียวล่ะคะ...?",
  ui_story_5017_50171501_23_dialog_content = "<color=#e8d9bb>เพียะ!</color>",
  ui_story_5017_50171501_24_dialog_content = "...?!",
  ui_story_5017_50171501_25_dialog_content = "นี่คือการลงโทษที่นำกระจกเมฆาออกมาใช้โดยไม่ขออนุญาตจากข้า เจ้าได้ละเมิดธรรมเนียมอันศักดิ์สิทธิ์ของตระกูลเรา เข้าใจไหม",
  ui_story_5017_50171501_26_dialog_content = "ข... ขออภัยอย่างสูงค่ะ...",
  ui_story_5017_50171501_27_dialog_content = "และต่อไป... คือการลงโทษในนามประชาชนแห่งเกาะเมฆา เจ้าจะต้องชดใช้ที่นำกระจกออกมาใช้งานโดยไม่สมควร",
  ui_story_5017_50171501_28_dialog_content = "ย้ากกก!",
  ui_story_5017_50171501_29_dialog_content = "...",
  ui_story_5017_50171501_30_dialog_content = "นี่เป็นเรื่องส่วนตัวของข้า รู้ตัวดีใช่ไหมว่าจะเกิดอะไรขึ้น... หากเข้ามายุ่งเกี่ยว?",
  ui_story_5017_50171501_31_dialog_content = "แกจะเป็นใครฉันไม่สนหรอก! คนที่ทำร้ายเพื่อนของฉันก็คือคนชั่ว!",
  ui_story_5017_50171501_32_dialog_content = "และสวะอย่างแก... ก็ไม่สิทธิ์ลงโทษรินเนะหรือใครก็ตามในนามเกาะเมฆา!",
  ui_story_5017_50171501_33_dialog_content = "ฮ่าฮ่าฮ่า... ช่างน่าเอ็นดูจริง ๆ พวกเจ้าเป็นสหายของรินเนะสินะ",
  ui_story_5017_50171501_34_dialog_content = "แต่อย่างน้อย เมื่อเทียบกับนากิแล้ว...",
  ui_story_5017_50171501_35_dialog_content = "คงจะมีข้าเพียงคนเดียวเท่านั้นที่มีคุณสมบัติคู่ควรแก่การปกครองเกาะเมฆา",
  ui_story_5017_50171501_36_dialog_content = "ฉันไม่มีเวลามาฟังเรื่องไร้สาระของแกหรอกนะ ฟูจิคุโมะ แกจะต้องชดใช้ความผิดที่ตัวเองก่อไว้",
  ui_story_5017_50171501_37_dialog_content = "ความผิดอย่างนั้นรึ...?",
  ui_story_5017_50171501_38_dialog_content = "ตัวข้าต่างหาก ที่ต้องแลกอะไรไปมากมายเมื่อ 10 ปีที่แล้ว...",
  ui_story_5017_50171501_39_dialog_content = "10 ปีที่แล้วงั้นเรอะ...?!",
  ui_story_5017_50171501_40_dialog_content = "กล้าดียังไง แกไม่มีสิทธิ์มาพูดแบบนั้นกับฉัน!",
  ui_story_5017_50171501_41_dialog_content = "สงบสติอารมณ์ก่อน นากิ... นี่เจ้ายังยึดติดกับอดีตถึงเพียงนี้เลยรึ?",
  ui_story_5017_50171501_42_dialog_content = "เมื่อคำนึงถึงสถานการณ์ในอดีตแล้ว... คราวนี้ข้าจะเป็นฝ่ายโจมตีก่อนก็แล้วกัน!",
  ui_story_5017_50171501_43_dialog_content = "<color=#e8d9bb>ฟิ้ว!</color>",
  ui_story_5017_50171501_44_dialog_content = "ฟู่...",
  ui_story_5017_50171501_45_dialog_content = "ฉันจะไม่ยอมให้อาจารย์ต้องมาต่อสู้เพราะเรื่องนี้เด็ดขาด",
  ui_story_5017_50171501_46_dialog_content = "น่าสนใจ... สมแล้วที่เป็นศิษย์ของนากิ",
  ui_story_5017_50171501_47_dialog_content = "พวกเราแก่ชราถึงเพียงนี้แล้วรึ นากิ? ถึงกับต้องให้เด็ก ๆ มายุ่งเกี่ยวกับเรื่องราวในยุคของเรา?",
  ui_story_5017_50171501_48_dialog_content = "ฆ่าพวกมันให้หมด รินเนะ",
  ui_story_5017_50171501_49_dialog_content = "...",
  ui_story_5017_50171501_50_dialog_content = "เป็นอะไรไป? ไม่น่าจะเป็นเรื่องยากสำหรับเจ้าเลยนี่ รินเนะ",
  ui_story_5017_50171501_51_dialog_content = "สัมผัสได้ใช่ไหม? พลังของกระจกเมฆา?",
  ui_story_5017_50171501_52_dialog_content = "ถึงตัวเจ้าในตอนนี้จะยังไม่มีทางควบคุมมันได้...",
  ui_story_5017_50171501_53_dialog_content = "แต่ครั้งนี้ข้าอนุญาต",
  ui_story_5017_50171501_54_dialog_content = "สตรีที่อยู่เบื้องหน้าเจ้าไม่ใช่มนุษย์อีกต่อไปแล้ว เธอคือปีศาจที่แหกกรงขังออกมา เป็นสิ่งแปดเปื้อนที่จะนำเกาะเมฆาจมดิ่งสู่ความโกลาหล",
  ui_story_5017_50171501_55_dialog_content = "เอาสิ... เจ้าปรารถนาที่จะปลดปล่อยพลังของมันไม่ใช่หรือ?",
