  ui_story_5017_50171501_70_dialog_content = "...",
  ui_story_5017_50171501_71_dialog_content = "ยอดมาก รินเนะ...",
  ui_story_5017_50171501_72_dialog_content = "ดูเหมือนความปรารถนาและความทะเยอทะยานของเจ้า... จะคู่ควรกับกระจกเมฆาอย่างสมบูรณ์แบบ",
