  ui_story_5017_50171501_80_dialog_content = "ดูเหมือนข้าจะต้องสั่งสอนเจ้าด้วยกฎของโคฟุโจเสียแล้ว",
  ui_story_5017_50171601_1_dialog_content = "*อัก*",
