  ui_story_5017_50171601_4_dialog_content = "<color=#e8d9bb>แกล๊ง!</color>",
  ui_story_5017_50171601_5_dialog_content = "เฮ้อ... ช่างไม่เจียมตัวอะไรอย่างนี้...",
  ui_story_5017_50171601_6_dialog_content = "ของที่ถูกเจ้าขโมยมา ข้ายังต้องลำบากไปเก็บเองอีกรึ?",
  ui_story_5017_50171601_7_dialog_content = "จะต้องให้ข้าบอกอีกกี่ครั้งกี่หนกัน... เจ้ายังแข็งแกร่งไม่พอที่จะควบคุมกระจกเมฆา",
