  ui_story_5017_50171601_9_dialog_content = "แต่ก็ไม่ใช่เรื่องใหญ่อะไร",
  ui_story_5017_50171601_10_dialog_content = "เพราะนั่นแสดงว่ากระจกเมฆาเริ่มยอมรับเจ้าทีละน้อย",
  ui_story_5017_50171601_11_dialog_content = "แสดงว่า... ท่าน... รู้ถึงเป้าหมายที่แท้จริงและพลังของมันอย่างนั้นเหรอ!",
  ui_story_5017_50171601_12_dialog_content = "... ท่านทำไปเพื่ออะไรกัน?!",
  ui_story_5017_50171601_13_dialog_content = "มีเพียงวิญญาณที่เกิดใหม่เท่านั้น ที่จะเข้าใจถึงความเจ็บปวดของความตาย",
  ui_story_5017_50171601_14_dialog_content = "ต่ำช้าที่สุด",
  ui_story_5017_50171601_15_dialog_content = "ส่งตัวมิโกะมาให้ข้า",
  ui_story_5017_50171601_16_dialog_content = "ขอรับ!",
  ui_story_5017_50171601_17_dialog_content = "ฝันไปเถอะ!",
  ui_story_5017_50171601_18_dialog_content = "ยอดเลย...",
  ui_story_5017_50171601_19_dialog_content = "ตอนนั้นแกก็หลอกใช้เธอแบบนี้เหมือนกันสินะ?",
  ui_story_5017_50171601_20_dialog_content = "สาวน้อย เธอเองก็เป็นแค่เครื่องมือเท่านั้น",
