  ui_story_5017_50171601_25_dialog_content = "สิบปีที่ผ่านมาฝีมือเจ้าไม่ได้พัฒนาเท่าไหร่เลยนี่นา? อย่างน้อยก็ไม่เท่าศิษย์ของฉันทั้งสองคน",
